(window.GIM_TS=window.GIM_TS||{})["Yoma.0"]={"from":0,"a":[["\u0003שבעת ימים קודם יום הכפורים מפרישין כהן גדול\u0004 שכל עבודת יום הכיפורים אינה נעשית אלא על ידו \u0003מביתו ללשכת פרהדרין\u0004 חדר מיוחד במקדש שהוכן לצורך מגורי הכהן הגדול בימים אלו. \u0003ומתקינין\u0004 (מכינים) \u0003לו כהן אחר תחתיו\u0004 שיוכל למלא את מקומו \u0003שמא יארע בו פסול\u0004 טומאה או אונס אחר ביום הכיפורים אשר ימנע את כניסתו לבית המקדש.","\u0003ר' יהודה אומר: אף אשה אחרת מתקינין לו, שמא תמות אשתו\u0004 ומתוך \u0003שנאמר\u0004 בסדר עבודת יום הכיפורים \u0003\"וכפר בעדו ובעד ביתו\"\u0004 (ויקרא טז, ו) ופירשו \u0003\"ביתו\"\u0004 — \u0003זו אשתו,\u0004 הרי כדי שיוכל לקיים את האמור בכתוב חייב הכהן להיות נשוי וכיון שיש לחשוש למות אשתו יש להכין לו אשה אחרת. \u0003אמרו לו\u0004 חכמים לר' יהודה: \u0003אם כן\u0004 שאתה חושש למיתת האשה הרי \u0003אין לדבר סוף\u0004 שהרי על אשה זו שהתקינו לו יהא עליך לחשוש שמא תמות. אלא וודאי שאין לחשוש לכך.","דין הפרשת הכהן לצורך עבודת יום הכיפורים, בין במעשה ובין בטעמו, דומה במקצת לדין הכנת הכהן האמור לעסוק בשריפת הפרה האדומה, על כן מביאים \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת פרה: \u0003שבעת ימים קודם שריפת הפרה\u0004 האדומה \u0003היו מפרישין\u0004 את ה\u0003כהן השורף את הפרה מביתו ללשכה שעל פני הבירה\u0004 (שבהר הבית), ואותה לישכה בצד \u0003צפונה מזרחה\u0004 של העזרה היתה, \u0003ולשכת בית האבן היתה נקראת.\u0004 ומבארים: \u0003ולמה נקרא שמה לשכת בית האבן — שכל מעשיה\u0004 שעושים לצורך שריפת הפרה האדומה לא היו אלא \u0003בכלי גללים, בכלי אבנים ובכלי אדמה,\u0004 שכלים אלה אינם מקבלים טומאה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 מחמירים כל כך בטהרת הפרה? ומסבירים: \u0003כיון\u0004 שכהן \u0003טבול יום כשר\u0004 בעשיית \u0003פרה\u0004 לאחר שטבל אף שעדיין לא העריב שמשו, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מטמאין היו\u0004 בכוונה את \u0003הכהן השורף את הפרה ומטבילין אותו\u0004 מיד, וכל זאת כדי \u0003להוציא מלבן של צדוקים\u0004 להראות בפומבי שאין חוששים לדבריהם. ש\u0003היו\u0004 הם \u0003אומרים: במעורבי השמש\u0004 כלומר, בכהנים שטבלו לטהרתם והעריבה עליהם השמש, ונטהרו טהרה גמורה בלבד \u0003היתה נעשית\u0004 הפרה.","וכיון שהיו מטמאים את הכהן השורפה \u0003תקינו\u0004 \u0005[התקינו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 כנגד זה חומרות יתירות מרובות: שתיעשה ב\u0003כלי גללים, כלי אבנים וכלי אדמה דלא ליקבלו\u0004 \u0005[שאינם\u0006 מסוגלים \u0005לקבל]\u0006 \u0003טומאה כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליזלזלו\u0004 \u0005[יזלזלו]\u0006 \u0003בה\u0004 לעשותה בטומאה מתוך שיראו שמקילים בה לעשותה אף בטבול יום.","כיון שהובאה משנה זו שואלים לגופה: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה,\u0006 מדוע\u0005]\u0006 בחרו לשכן את הכהן העושה את הפרה האדומה דווקא בלישכה הפונה \u0003צפונה מזרחה?\u0004 ומשיבים: \u0003כיון\u0004 ש\u0003חטאת היא\u0004 שהפרה האדומה מכונה במקרא \"חטאת\" (במדבר יט, ט) \u0003ו\u0004קרבן \u0003חטאת\u0004 (שחיטתו וזריקת דמו) \u0003טעונה צפונה\u0004 למזבח. \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003בה\u0004 בפרה אדומה גם: \u0003\"\u0004והזה \u0003אל נכח פני אהל מועד\"\u0004 (במדבר יט, ד) ולפני אוהל מועד משמע — צד מזרח שלו. על כן \u0003תקינו\u0004 \u0005[תיקנו]\u0006 \u0003לה רבנן\u0004 \u0005[חכמים]\u0006 \u0003לשכה צפונה מזרחה, כי היכי דלהוי\u0004 \u0005[כדי שיהא]\u0006 \u0003לה\u0004 לעשיית הפרה \u0003היכירא\u0004 \u0005[היכר]\u0006 ומתוך כך ישים הכהן העושה אותה אל ליבו להיות זריז במעשיה וסדר עבודותיה.","עוד שואלים בלשונה של המשנה שהובאה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בירה\"\u0004 הנזכר בה? \u0003אמר רבה בר בר חנה אמר ר' יוחנן: מקום היה בהר הבית ו\"בירה\" שמו,\u0004 ולידו היתה לישכת בית האבן. \u0003וריש לקיש אמר: כל המקדש כולו קרוי \"בירה\", שנאמר\u0004 בדברי דוד: \u0003\"\u0004ולשלמה בני תן לבב שלם לשמור מצוותיך עדותיך וחוקיך ולעשות הכל ולבנות \u0003הבירה אשר הכינותי\"\u0004 (דברי הימים א' כט, יט).","לגופה של ההלכה שיש להפריש את הכהן מביתו לצורך עבודת יום הכיפורים ולצורך עשיית הפרה, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין דברים אלה]\u0006 מה מקורם במקרא? \u0003אמר ר' מניומי בר חלקיה אמר ר' מחסיא בר אידי אמר ר' יוחנן:\u0004 בדין פרישת אהרן ובניו וישיבתם במשכן במשך שבעה ימים ולא עשו את עבודת הקודש אלא ביום השמיני לימי המילואים ו\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"כאשר עשה ביום הזה צוה ה' לעשת לכפר עליכם\"\u0004 (ויקרא ח, לד) משמע שהציווי על הפרשה כגון זו נאמר לא רק לשעתו אלא אף לדורות. וכך יש לדרוש את הכתוב: \u0003\"לעשת\" — אלו מעשי פרה\u0004 אדומה שצריך הכהן העושה אותה בפרישה שבעה ימים טרם עשייתה, \u0003\"לכפר\" — אלו מעשי יום הכפורים,\u0004 שחייב הכהן הגדול בפרישה שבעה ימים טרם יום הכיפורים.","על מדרש זה שואלים: \u0003בשלמא, כוליה קרא בפרה לא מתוקם\u0004 \u0005[נניח, כל הפסוק אינו ניתן להיות מועמד,\u0006 מוסבר, רק לענין \u0005פרה\u0006 אדומה\u0005]\u0006 כי \u0003\"לכפר\" כתיב\u0004 \u0005[נאמר]\u0006 שם, \u0003ופרה לאו\u0004 \u0005[לא]\u0006 \u0003בת כפרה היא,\u0004 שהרי אין ייעודה לכפרה אלא לטהרה היא נעשית. \u0003אלא, אימא כוליה קרא\u0004 \u0005[אמור\u0006 ש\u0005כל הכתוב\u0006 כולו\u0005]\u0006 \u0003ביום הכפורים כתיב\u0004 \u0005[נאמר]\u0006 שמעשה הכפרה של יום הכיפורים הוא כימי המילואים, ומהיכן אם כן תלמד לפרישת הכהן העושה את הפרה האדומה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כתשובה לכך: \u0003יליף\u0004 \u0005[לומד]\u0006 הוא בגזירה שווה \u0003\"צוה\" \"צוה\".\u0004 שכן \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בימי המילואים \u0003\"צוה ה' לעשת\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בפרה אדומה \u0003\"זאת חקת התורה אשר צוה ה' לאמר\"\u0004 (במדבר יט, ב), ונלמד: \u0003מה\u0004 לשון \"צוה\" שנאמר \u0003להלן,\u0004 בענין \u0003פרה\u0004 נאמר \u0003— אף\u0004 האמור \u0003כאן\u0004 \"צוה ה' לעשות\" שנאמר בפרשת המילואים נאמר אף לענין \u0003פרה. ומה כאן\u0004 במילואים יש דין \u0003פרישה\u0004 טרם מעשה העבודה \u0003— אף להלן\u0004 בדין פרה דרושה \u0003פרישה\u0004 טרם עשייתה."],["ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שאכן נלמד גזירה שווה, אך לא כמו זו שלמדנו כי אם \u0003\"צוה\", \"צוה\"\u0004 של \u0003יום הכפורים, דכתיב\u0004 \u0005[שהרי נאמר\u0006 בו\u0005]:\u0006 \u0003\"\u0004והיתה זאת לכם לחוקת עולם לכפר על בני ישראל מכל חטאותם אחת בשנה \u0003ויעש כאשר צוה ה' את משה\"\u0004 (ויקרא טז, לד) ואינך למד אם כן אלא לפרישה טרם יום הכיפורים. ודוחים: אין ללמוד כן, כי אין דנים בגזירה שווה אלא דברים השוים זה לזה, ולכן \u0003דנין \"צוה\"\u0004 שנאמר בענין ש\u0003לפני עשיה\u0004 כגון בפרה של המצוה \u0003מ\"צוה\"\u0004 ש\u0003לפני עשיה\u0004 האמורה במילואים, \u0003ואין דנין \"צוה\"\u0004 ש\u0003לאחר\u0004 עשיה, כגון זה האמור בענין יום הכיפורים, שנאמר לאחר עשייתה וקיומה של המצוה, \u0003מ\"צוה\"\u0004 ש\u0003לפני עשיה.\u0004","ומקשים עוד על הגזירה שווה הראשונה: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהיא באה ללמד לענין \u0003\"צוה\"\u0004 האמור ב\u0003קרבנות, דכתיב\u0004 \u0005[שנאמר]\u0006 בהם: \u0003\"ביום צותו את בני ישראל\u0004 להקריב את קרבניהם\u0003\"\u0004 (ויקרא ז, לח)! ודוחים: \u0003דנין\u0004 ולמדים בגזירה שווה לשון \u0003\"צוה\" מ\u0004לשון \u0003\"צוה\"\u0004 שהן מילים שוות\u0003, ואין דנין\u0004 לשון \u0003\"צותו\" מ\u0004לשון \u0003\"צוה\"\u0004 שאינן מילים שוות.","על כך מקשים: \u0003ומאי נפקא מינה\u0004 \u0005[ומה יוצא\u0006 מהבדל \u0005זה]\u0006 כלומר, האם הבדל זה יש בו כדי לעכב? \u0003והתנא דבי\u0004 \u0005[והרי\u0006 כבר \u0005שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 על הכתוב: \u0003\"ושב הכהן\u0004 ביום השביעי וראה והנה פשה הנגע בקירות הבית\u0003\"\u0004 (ויקרא יד, לט) והכתוב הדומה לו: \u0003\"ובא הכהן\u0004 וראה והנה פשה הנגע בבית\u0003\"\u0004 (ויקרא יד, מד) ודרש: \u0003זו היא \"שיבה\", זו היא \"ביאה\",\u0004 כלומר אף שאין שוויון בין מילים אלו יש ללמוד בהן גזירה שווה, וכל שנאמר בענין אחד שייך גם לשני. ומתוך כך ניתן להסיק שאפילו כשקיים הבדל גדול בין המילים, כיון שהתוכן זהה — דנים גזירה שווה, כל שכן כאן ששורש המילים אחד, ואין הבדל אלא בצורה הדקדוקית!","ודוחים: \u0003הני מילי\u0004 \u0005[דברים אלו]\u0006 שיש ללמוד גזירה שווה כזו, הרי זה דווקא \u0003היכא דליכא דדמי ליה\u0004 \u0005[היכן שאין\u0006 מילה \u0005הדומה לה\u0006 בדיוק\u0005]\u0006 ולכן משווים אף את המילים שאינן דומות. \u0003אבל היכא דאיכא דדמי ליה\u0004 \u0005[היכן שיש\u0006 מילה \u0005הדומה לה] —\u0006 \u0003מדדמי ליה ילפינן\u0004 \u0005[מן הדומה לה למדים אנו].\u0006","עוד דנים ומעיינים בגזירה השווה לענין פרישת הכהן. אמרנו כי \u0003\"לכפר\" — אלו מעשה יום הכפורים.\u0004 ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא \u0003לכפרה\u0004 של \u0003קרבנות\u0004 בכלל, שכל כהן העוסק בעבודת הקרבנות העשויים לכפר יצטרך לפרוש שבעה ימים טרם עבודתו!","את השאלה הזו מנסים לדחות מבחינה מעשית: \u0003מי ידעינן הי\u0004 \u0005[האם יודעים אנו איזה]\u0006 \u0003כהן מתרמי\u0004 \u0005[יזדמן]\u0006 להקריב קרבן מסויים, \u0003דבעי ליה\u0004 \u0005[שיצטרך לעשות]\u0006 \u0003פרישה?\u0004 על דחיה זו משיבים: \u0003אלמה\u0004 \u0005[למה]\u0006 \u0003לא?\u0004 יש ויש דרך לעשות זאת, כגון \u0003ניבעי ליה\u0004 \u0005[נצריך]\u0006 \u0003פרישה לכוליה\u0004 \u0005[לכל]\u0006 \u0003משמרת בית\u0004 ה\u0003אב,\u0004 שהרי לכל משמר יש שבוע קבוע לעבוד בו, ולכל בית אב במשמרת יש יום קבוע לעבודה בשבוע זה, ונאמר כי כל הכהנים השייכים לבית אב המיועד לעבודה ביום מסויים, יצטרכו לפרוש שבוע קודם! על כן דוחים את ההצעה בדרך אחרת: \u0003דנין דבר שקבוע לו זמן\u0004 ידוע בשנה, כיום הכיפורים, \u0003מדבר שקבוע לו זמן\u0004 כמצוות המילואים למשכן, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003קרבנות, דכל יומא איתנהו\u0004 \u0005[שבכל יום ישנם]\u0006 וכיון שאינם מאותו סוג — אין ללמוד לגביהם.","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה במילה \"לכפר\" היא לקרבנות ה\u0003רגלים\u0004 שיצטרכו מקריבי קרבנות הכפרה שברגל לפרוש שבעה ימים קודם! ודוחים: \u0003דנין דבר שנוהג פעם אחת בשנה\u0004 ביום הכיפורים \u0003מדבר הנוהג פעם אחת בשנה\u0004 כמילואים שלא נעשו פעמיים, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003רגלים, דלאו\u0004 \u0005[שלא]\u0006 \u0003פעם אחת בשנה נינהו\u0004 \u0005[הם]\u0006 אלא שלוש פעמים.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שרק \u0003רגל אחד\u0004 מן הרגלים יצטרך פרישה, ויהא זה איפוא רק אחת בשנה! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לא ידעינן הי מיניהו\u0004 \u0005[אין אנו יודעים איזה מהם]\u0006 הוא החשוב שבהם שצריך לפרוש לפניו, והרי יש להסתפק \u0003אי\u0004 \u0005[אם]\u0006 הכוונה ל\u0003חג המצות\u0004 (פסח), \u0003הואיל ופתח בו הכתוב תחלה\u0004 שתמיד מקדימו לשלושה רגלים, \u0003אי\u0004 \u0005[אם]\u0006 הכוונה ל\u0003חג הסוכות, הואיל ומרובה מצותו\u0004 בקרבנות, שמרובים בו יותר מבשאר רגלים!","\u0003אלא\u0004 עלינו לדחות את כל הנימוקים שאמרנו ולתת תשובה אחרת לשאלה: \u0003דנין\u0004 בגזירה השווה \u0003פרישת שבעה\u0004 ימים \u0003ל\u0004פני \u0003יום אחד\u0004 של עבודת קודש, של יום הכיפורים, \u0003מפרישת שבעה ליום אחד\u0004 של המילואים. \u0003ואין דנין פרישת שבעה\u0004 ימים \u0003ל\u0004פני עבודת \u0003שבעה\u0004 ימים של הרגל, \u0003מפרישת שבעה\u0004 ימים \u0003ל\u0004פני \u0003יום אחד\u0004 של המילואים, ולכן אין לפרש \"לכפר\" לענין הרגלים.","ומקשים: אם לפי נימוק זה \u0003ואימא\u0004 \u0005[ואמור]\u0006 שנלמד מן הכתוב שהכוונה שיפרשו שבעה ימים טרם \u0003שמיני\u0004 עצרת, שאף הוא חג, ואז תתקיים ההשוואה, שהרי גם זו \u0003פרישת שבעה ליום אחד הוא!\u0004 ודוחים: \u0003דנין דבר שאין קדושה לפניו\u0004 כיום הכיפורים שהימים שלפניו ימי חול \u0003מדבר שאין קדושה לפניו\u0004 כמילואים, שאף לפניהם לא היה כל יום מקודש, \u0003ואין דנין דבר שיש קדושה לפניו\u0004 כשמיני עצרת שיש לפניו את שבעת ימי חג הסוכות \u0003מדבר שאין קדושה לפניו.\u0004","על כך מקשים: \u0003ולאו\u0004 \u0005[וכי לא]\u0006 \u0003קל וחומר הוא\u0004 שאפשר ללמוד כאן? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003דבר שאין קדושה לפניו בעי\u0004 \u0005[צריך]\u0006 \u0003פרישה\u0004 מפני קדושתו, \u0003דבר שיש קדושה לפניו לא כל שכן\u0004 שיצטרך פרישה קודמת לו! \u0003אמר רב משרשיא\u0004 בדחיית קושיה זו: \u0003לא,\u0004 אי אפשר ללמוד קל וחומר כאן, כי \u0003\"הזה\" כתיב\u0004 \u0005[נאמר]\u0006 (\"כאשר עשה ביום הזה\") להדגיש: דווקא יום \u0003כזה\u0004 בדיוק כפי שהיה במילואים, ולא בכל אופן אחר.","\u0003רב אשי אמר:\u0004 אין לפרש שיצטרכו פרישה לפני שמיני עצרת מטעם אחר, שכן \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 ש\u0003עיקר רגל\u0004 כלומר, היום הראשון של חג הסוכות, \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003פרישה\u0004 כפי שכבר הוכחנו, ואילו ה\u0003טפל דידיה\u0004 \u0005[לו]\u0006 \u0003בעי\u0004 \u0005[צריך]\u0006 \u0003פרישה\u0004 כלומר, שמיני עצרת שהוא כתוספת, יום העצרת שלאחר החג העיקרי תהא בו קדושה וחומרה יותר מאשר בעיקר החג? \u0003ואפילו ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר: שמיני\u0004 עצרת \u0003רגל בפני עצמו הוא\u0004 שאין דינו כחלק מחג הסוכות אלא כחג בפני עצמו, הרי \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 \u0003לענין\u0004"],["\u0003פז\"ר קש\"ב\u0004 כלומר שעושים \u0003פ\u0004יס חדש בפני עצמו לקבוע מי הכהנים הזכאים להקריב את הקרבנות בו, ואין ממשיכים לפי הסדר שנקבע בחג הסוכות. וכן מברכים בו \u0003ז\u0004מן (\"שהחיינו\") כשם שמברכים בכל כניסת חג חדש, וכן נחשב כ\u0003ר\u0004גל לעצמו אף לענין שמו, שאין שם חג הסוכות עליו. ומביאים בו \u0003ק\u0004רבן לעצמו, שאין ממשיכים בסדר קרבנות חג הסוכות אלא באופן שונה. וכן יש לו \u0003ש\u0004יר מיוחד לעצמו ששרים בו הלויים במקדש, ואין ממשיכים בו בסדר מזמורי תהילים ששרים בסוכות. וכן יש לו \u0003ב\u0004רכה לעצמו שאומרים בו נוסח מיוחד בברכת המזון ובתפילה (תוספות) שלא כבשאר ימי חג הסוכות.","\u0003אבל\u0004 עם כל ההבדלים הללו \u0003לענין תשלומין\u0004 כלומר לענין השלמת חובות קרבנות הרגל, לכל הדעות \u0003תשלומין\u0004 של החג ה\u0003ראשון הוא, דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שלא חג\u0004 (לא הביא קרבן חגיגה) \u0003ביום טוב הראשון של חג\u0004 (הוא חג הסוכות) \u0003חוגג\u0004 ומביא קרבן \u0003והולך כל\u0004 ימי \u0003הרגל כולו,\u0004 וכן ב\u0003יום טוב האחרון של חג.\u0004 משמע ששמיני עצרת נחשב יום טוב אחרון של החג, ונספח לו לענין חובותיו.","ועוד מקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שנעשה פרישה לפני \u0003עצרת\u0004 [שבועות], שאף כאן תהא זאת \u0003פרישת שבעה ליום אחד הוא,\u0004 והרי אף הוא חג שאין קדושה לפניו! \u0003אמר ר' אבא:\u0004 יש לחלק בין המילואים ועצרת, שכן \u0003דנין פר אחד ואיל אחד\u0004 שהם חובת יום הכיפורים \u0003מפר אחד ואיל אחד\u0004 שהקריבו במילואים, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עצרת\u0004 ש\u0003שני אילים הם\u0004 \u0005[הם]\u0006 שחייבים להקריב בו ביום.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר יום הכפורים איל אחד\u0004 בלבד \u0003הוא\u0004 שמקריבים בו לחובת היום, \u0003אלא למאן\u0004 \u0005[מי]\u0006 ש\u0003אמר שני אילים נינהו\u0004 \u0005[הם]\u0006 שמקריבים ביום הכיפורים, אם כן \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 שלפי זה אף יום הכיפורים אינו שווה למילואים! \u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: איל אחד הוא,\u0004 כי האיל \u0003האמור כאן\u0004 בספר ויקרא, ככתוב: \"בזאת יבוא אהרן אל הקודש בפר בן בקר לחטאת ואיל לעולה\" (ויקרא טז, ג) \u0003הוא האמור בחומש הפקודים\u0004 \"ובעשור לחודש השביעי הזה מקרא קודש יהיה לכם ועניתם את נפשותיכם כל מלאכה לא תעשו. והקרבתם עולה לה' לריח ניחוח פר בן בקר אחד איל אחד...\" (במדבר כט, ז-ח). \u0003ר' אליעזר בר' שמעון אומר: שני אילים הם\u0004 שמקריבים ביום הכיפורים, \u0003אחד האמור כאן\u0004 בספר ויקרא \u0003ואחד האמור בחומש הפקודים!\u0004","את התירוץ הזה דוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי הדבר כשיטת \u0003ר' אליעזר בר' שמעון\u0004 שמקריבים ביום הכיפורים שני אילים, מכל מקום יש לחלק בינו ובין חג השבועות: \u0003התם\u0004 \u0005[שם]\u0006 ביום הכיפורים \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 שנצטוו עליו בספר ויקרא \u0003חובת היום\u0004 לכפרה המיוחדת ליום כיפור הוא נועד, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 שבספר במדבר \u0003למוספין. לאפוקי עצרת\u0004 \u0005[להוציא]\u0006 \u0003דתרוייהו\u0004 \u0005[ששניהם,\u0006 שני האילים\u0005]\u0006 ל\u0003חובת היום נינהו\u0004 \u0005[הם],\u0006 ואם כן אין הדבר דומה למילואים.","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 שנלמד שיש חובת פרישה לפני \u0003ראש השנה,\u0004 שאף אז תהיה זו \u0003פרישת שבעה ליום אחד הוא\u0004 ובשניהם קרבן היום הוא פר ואיל! \u0003אמר ר' אבהו\u0004 יש לדחות ולומר: \u0003דנין פר ואיל\u0004 שמביא הכהן הגדול \u0003משלו\u0004 ביום הכפורים \u0003מפר ואיל\u0004 שהביא אהרן מ\u0003שלו\u0004 במילואים. \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003עצרת וראש השנה\u0004 שפר ואיל שמביאין אז, משל ה\u0003ציבור נינהו\u0004 \u0005[הם]\u0006 ולא של הכהן. על הסבר זה מקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שבכל מקום שנאמר \u0003\"קח לך\"\u0004 — כוונתו \u0003משלך\u0004 מרכושך הפרטי,"],["וכן כאשר נאמר \u0003\"ועשה לך\"\u0004 — כוונתו \u0003משלך, אלא ל\u0004שיטת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 שאף \"קח לך\" \"ועשה לך\" כוונתו \u0003משל צבור, מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 כדי להבדיל בין יום הכיפורים לשאר ימים?","\u0003דתניא\u0004 \u0005[ש\u0006הרי \u0005שנינו\u0006 בברייתא\u0005]:\u0006 כשנאמר בתורה \u0003\"קח לך\" —\u0004 הכוונה \u0003משלך, ו\"עשה לך\" — משלך,\u0004 ואילו כשנאמר \u0003\"ויקחו אליך\"\u0004 כוונתו \u0003משל צבור,\u0004 שהם יקחו משלהם ויביאו אליו, אלו \u0003דברי ר' יאשיה. ר' יונתן אומר: בין \"קח לך\" בין \"ויקחו אליך\" —\u0004 הכוונה \u0003משל צבור, ומה תלמוד לומר \"קח לך\"\u0004 שמשמעו משלך — יש להבין שאמר ה' למשה: \u0003כביכול משלך אני רוצה יותר משלהם,\u0004 ולכן נתייחסה הלקיחה למשה, אבל בפועל לוקחים משל ציבור.","\u0003אבא חנן אמר משום\u0004 \u0005[בשם]\u0006 \u0003ר' אלעזר: כתוב אחד אומר: \"ועשית לך ארון עץ\"\u0004 (דברים י, א) ומשמע עשה משלך \u0003וכתוב אחד אומר\u0004 באותו ענין: \u0003\"ועשו ארון עצי שטים\"\u0004 (שמות כה, י) משל ישראל, \u0003הא כיצד\u0004 ניישב את הסתירה בין הכתובים? אלא \u0003כאן בזמן שישראל עושין רצונו של מקום\u0004 נקרא מעשה ארון הברית על שמם, \u0003כאן בזמן שאין\u0004 ישראל \u0003עושין רצונו של מקום\u0004 מייחסים את הארון למשה לבדו. ולפי זה אין הבדל בין קרבנות יום הכיפורים לקרבנות אחרים!","את הקושיה הזו דוחים: \u0003עד כאן לא\u0004 שמענו ש\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא בקיחות דעלמא\u0004 \u0005[סתם]\u0006 \u0003ועשיות דעלמא\u0004 \u0005[סתם],\u0006 \u0003קיחות דעלמא\u0004 \u0005[סתם] —\u0006 כגון \u0003\"קח לך סמים\"\u0004 (שמות ל, לד), \u0003עשיות דעלמא\u0004 \u0005[סתם] —\u0006 כגון \u0003\"עשה לך שתי חצוצרת כסף\"\u0004 (במדבר י, ב). \u0003אבל הנך פרושי קא מפרש\u0004 \u0005[באלה\u0006 של מילואים ויום הכיפורים \u0005מפרש הוא]\u0006 הכתוב במיוחד \u0003שמשלך הוא\u0004 ממש. \u0003במלואים\u0004 כיצד — \u0003מכדי כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"ואל בני ישראל תדבר לאמר קחו שעיר עזים לחטאת\u0004 ועגל וכבש בני שנה תמימים לעולה\u0003\"\u0004 (ויקרא ט, ג), ואם כן מה שנאמר \u0003\"ויאמר אל אהרן קח לך עגל בן בקר לחטאת\"\u0004 (ויקרא ט, ב), \u0003למה לי\u0004 שינוי לשון מפורש באותו ענין בין הפניה לבני ישראל ובין הפניה לאהרן? אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003\"קח לך\"\u0004 בענין זה אכן \u0003משלך הוא.\u0004","וכן \u0003ביום הכפורים; מכדי כתיב\u0004 \u0005[הלא נאמר]:\u0006 \u0003\"בזאת יבא אהרן אל הקדש בפר בן בקר לחטאת\u0004 ואיל לעולה\u0003\"\u0004 (ויקרא טז, ג) ונאמר: \u0003\"ומאת עדת בני ישראל יקח שני שעירי עזים לחטאת והקריב את פר החטאת אשר לו\"\u0004 (ויקרא טז, ה) \u0003למה לי\u0004 הדגשה זו שהשעירים באים מבני ישראל? אלא \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003האי\u0004 \u0005[זה]\u0006 שנאמר \u0003\"לו\" —\u0004 הכוונה \u0003משלו\u0004 ממש \u0003הוא.\u0004","\u0003רב אשי אמר\u0004 נימוק אחר להבדיל בין יום הכיפורים ובין עצרת וראש השנה: \u0003דנין פר לחטאת ואיל לעולה\u0004 של יום הכיפורים \u0003מפר לחטאת ואיל לעולה\u0004 שנאמרו במילואים, \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003ראש השנה ועצרת דתרוייהו\u0004 \u0005[ששניהם]\u0006 גם הפר וגם האיל \u0003עולות נינהו\u0004 \u0005[הם],\u0006 ואם כן אין להשוות.","\u0003רבינא אמר\u0004 בתירוץ לשאלה: \u0003דנין\u0004 דבר שהוא \u0003עבודה בכהן גדול\u0004 בלבד, כעבודת יום הכיפורים, \u0003מעבודה בכהן גדול\u0004 של המילואים (שנעשה על ידי אהרן) \u0003לאפוקי כולהו קושייתין\u0004 \u0005[להוציא\u0006 מן \u0005כל קושיותינו]\u0006 מתחילת הסוגיה עד כאן \u0003דלאו\u0004 \u0005[שאין]\u0006 \u0003עבודה בכהן גדול נינהו\u0004 \u0005[הם]\u0006 אלא נעשים בכל כהן.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 כך \u0003אמר רבינא: דנין\u0004 דבר שהוא \u0003עבודה תחלה מעבודה תחילה, לאפוקי הני דלאו תחלה נינהו\u0004 \u0005[להוציא\u0006 את כל \u0005אלה שלא עבודה תחילה הם].\u0006 דברי רבינא אלה לא היו מובנים, ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003תחלה\u0004 זו שאמר רבינא? \u0003אילימא\u0004 \u0005[אם תאמר,\u0006 תפרש\u0005]\u0006 \u0003תחלה בכהן גדול — היינו קמייתא\u0004 \u0005[הרי זה\u0006 התירוץ \u0005הראשון]\u0006 עצמו. \u0003אלא\u0004 כך יש להבין: \u0003עבודה תחלה במקום\u0004 כלומר עבודת יום הכיפורים שהיא עבודה בקודש הקודשים שלפני כן לא נעשתה בו עבודה על ידי אחר \u0003מעבודה תחלה במקום\u0004 שנעשתה במילואים כאשר התחילו להקריב במשכן. ואם כן אין ללמוד ממילואים אלא ליום הכיפורים בלבד.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: ר' יוחנן מתני חדא\u0004 \u0005[היה\u0006 שונה \u0005אחת]\u0006 כלומר, למד מדין המילואים רק הלכה אחת, \u0003ר' יהושע בן לוי מתני תרתי\u0004 \u0005[היה שונה שתיים].\u0006 ומפרש: \u0003ר' יוחנן מתני חדא\u0004 \u0005[שונה אחת]\u0006 וכך היה גורס: \u0003\"לעשת לכפר\" — אלו מעשה יום הכפורים\u0004 הטעונים פרישה לפניהם כמילואים. \u0003ור' יהושע בן לוי מתני תרתי\u0004 \u0005[שונה שתיים]:\u0006 \u0003\"לעשת\" — אלו מעשה פרה\u0004 אדומה, \u0003\"לכפר\" — אלו מעשה יום הכפורים\u0004 ששניהם טעונים פרישה.","ושואלים: וכיצד יתכן כי \u0003ר' יוחנן מתני חדא\u0004 \u0005[שונה\u0006 רק \u0005אחת]\u0006 לזו של יום הכיפורים? \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במפורש במשנה\u0005]:\u0006 \u0003שבעת ימים קודם יום הכפורים,\u0004 וכן \u0003שבעת ימים קודם שריפת הפרה\u0004 מפרישים את הכהן, הרי ששתי פרישות הן! ומשיבים: פרישה זו של הכהן לפני שריפת הפרה \u0003מעלה בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 כלומר, שהוא רק מתקנות חכמים שנעשו כדי להדגיש את קדושתה לאחר שהותרה עשייתה בטבול יום, אבל אינה מחוייבת מדין תורה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' מניומי בר חלקיה אמר ר' מחסיא בר אידי אמר ר' יוחנן:\u0004 נאמר: \u0003\"כאשר עשה ביום הזה צוה ה' לעשת לכפר עליכם\"\u0004 (ויקרא ח, לד) ולמדים מכאן \u0003\"לעשת\" — אלו מעשה פרה \"לכפר\" — אלו מעשה יום הכפורים\u0004 הרי שאף ר' יוחנן עצמו שונה שתים! ומתרצים: \u0003ההוא דרביה\u0004 \u0005[\u0006שיטה \u0005זו של רבו]\u0006 היא, והוא עצמו אינו סבור כך. \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל \u0003אמר ר' יוחנן משום\u0004 \u0005[בשם]\u0006 \u0003ר' ישמעאל: \"לעשת\" — אלו מעשה פרה, \"לכפר\" — אלו מעשה יום הכפורים.\u0004 ואם כן, מה שמסר ר' מניומי בשם ר' יוחנן אינו אלא שיטת ר' ישמעאל רבו.","לגופה של מצוות הפרישה מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש לר' יוחנן: מהיכא קא ילפת לה\u0004 \u0005[מהיכן אתה לומד אותה]\u0006 דין זה של פרישה — \u0003ממלואים, אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 \u0003מה מלואים — כל הכתוב בהן מעכב בהן\u0004 ואם שינה משהו פסל, \u0003אף הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כל הכתוב בהן\u0004 יהא \u0003מעכב בהן\u0004 שצריך לקיים כל דיני פרישה כדיוקם.","\u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא באמת \u0005גם כן]\u0006 ואף מצוות פרישת יום הכיפורים מעכבת בכל פרטיה, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"ומתקינים לו כהן אחר\", ולא קתני\u0004 \u0005[שנינו]\u0006 \u0003\"מפרישין\"\u0004 גם את הכהן ממלא המקום שבעת ימים אף שיתכן שבסופו של דבר יעשה הוא את עבודת יום הכיפורים. משמע שפרישה זו איננה מהחובות המעכבות את עצם עבודת יום הכיפורים! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ותרצה להסביר: כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003מתקינין\u0004 כוונתו שאכן \u0003מפרישין\u0004 אותו, הרי אין הדבר נראה כלל, כי \u0003ליתני\u0004 \u0005[שישנה]\u0006 \u0003או אידי ואידי\u0004 \u0005[זה\u0006 בכהן הגדול המכהן \u0005וזה\u0006 ממלא מקומו\u0005]\u0006 \u0003\"מתקינין\" או אידי ואידי\u0004 \u0005[זה וזה]\u0006 בלשון \u0003\"מפרישין\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אלא מר מהיכא יליף לה\u0004 \u0005[אדוני מהיכן לומד\u0006 הלכה זו\u0005]\u0006 שיש לפרוש לפני יום הכיפורים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסיני, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישכן כבוד ה' על הר סיני ויכסהו הענן ששת ימים ויקרא אל משה ביום השביעי\u0004 מתוך הענן\u0003\"\u0004 (שמות כד, טז). \u0003מכדי כתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ויקרא אל משה ביום השביעי\"\u0004 ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הלימוד מן ההזכרה המפורשת של \u0003\"ששת ימים\"\u0004 קודם לכן? אלא זה \u0003בנה אב,\u0004 כלומר הרי זה מקור ללמוד ממנו הלכה לדורות: \u0003שכל הנכנס למחנה שכינה\u0004 למקום גילוי שכינה בהר סיני, או למקומה בקודש הקודשים \u0003טעון פרישת ששה\u0004 לקדושה קודם לכן.","ומקשים: לפי דבריך פרישה זו היא שישה ימים, \u0003והא אנן\u0004 \u0005[והרי אנו\u0006 במשנה\u0005]\u0006 \u0003שבעה\u0004 ימים של פרישה \u0003תנן\u0004 \u0005[שנינו]!\u0006 ותירץ ריש לקיש: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 המצריכה פרישת הכהן שבעת ימים כשיטת \u0003ר' יהודה בן בתירא היא, דחייש\u0004 \u0005[ש\u0006הוא \u0005חושש]\u0006"],["\u0003לטומאת ביתו\u0004 (כלומר: אשתו) שמא ייטמא על ידה בטומאת נדה (שהיא טומאת שבעה), לכן צריך לפרוש לשבעה ימים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש: בשלמא לדידי, דילפינא\u0004 \u0005[נניח לשיטתי, שאני למד]\u0006 \u0003ממלואים, היינו דתניא\u0004 \u0005[זהו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003זה\u0004 הכהן העוסק בשריפת הפרה האדומה \u0003וזה\u0004 הכהן הגדול לפני יום הכיפורים \u0003מזין עליו כל שבעה\u0004 ימים של פרישה \u0003מכל חטאות\u0004 (אפר פרה האדומה) \u0003שהיו שם\u0004 במקדש ונותרו למשמרת מכל הפרות האדומות שנשרפו במשך הדורות, ואני יכול להסביר זאת \u0003דהואי נמי\u0004 \u0005[שהיתה גם כן]\u0006 \u0003הזאה במלואים\u0004 ולכן מזים ומטהרים את הכהן לדורות. \u0003אלא לדידך דילפת\u0004 \u0005[לשיטתך, שאתה למד]\u0006 \u0003מסיני, הזאה בסיני מי הואי\u0004 \u0005[האם היתה]?\u0006 ואם כן מפני מה יש להזות על הכהן?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003ולטעמיך מי ניחא\u0004 \u0005[ולשיטתך האם נוח,\u0006 מובן\u0005]?\u0006 הלא \u0003במלואים\u0004 היו מזים \u0003דם,\u0004 ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 מזים \u0003מים!\u0004 ענה לו ר' יוחנן: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה]\u0006 \u0003דתני\u0004 \u0005[שהרי\u0006 כבר \u0005שנה]\u0006 \u0003ר' חייא\u0004 בענין זה: \u0003נכנסו מים תחת דם,\u0004 ושניהם בכלל הזאה, \u0003אלא לדידך\u0004 \u0005[לשיטתך]\u0006 \u0003הזאה בסיני מי הואי\u0004 \u0005[האם היתה]\u0006 כלל? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הזאה זו מעלה בעלמא\u0004 \u0005[בלבד]\u0006 ואינה חובה מעיקר הדין.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ר' יוחנן\u0004 שהדבר נלמד ממילואים, \u0003תניא כוותיה\u0004 \u0005[\u0006ו\u0005שנויה\u0006 ברייתא \u0005כשיטתו\u0006] של \u0003ריש לקיש\u0004 שהדבר נלמד מסיני. ומפרטים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003ר' יוחנן,\u0004 נאמר במילואים: \u0003\"בזאת יבא אהרן אל הקדש\u0004 בפר בן בקר לחטאת ואיל לעולה\u0003\"\u0004 (ויקרא טז, ג) מה הוא \"בזאת\" — \u0003במה שאמור בענין, מאי היא\u0004 \u0005[מה הוא]\u0006 — \u0003בענין\u0004 של \u0003מלואים\u0004 שכדרך הכנת הכהן למילואים כך הכנתו ליום הכיפורים. \u0003ומה אמור בענין\u0004 של \u0003מלואים — אהרן\u0004 הכהן \u0003פירש שבעה\u0004 ימים קודם עבודה \u0003ושמש\u0004 לאחר מכן \u0003יום אחד, ומשה מסר לו כל שבעה\u0004 דברי תורה \u0003כדי לחנכו\u0004 ולהרגילו \u0003בעבודה.\u0004","\u0003ואף לדורות; כהן גדול פורש שבעה\u0004 ימים קודם יום הכיפורים \u0003ומשמש יום אחד, ושני תלמידי חכמים מתלמידיו של משה\u0004 ודווקא הם — כדי \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003צדוקין\u0004 שאינם בכלל תלמידיו של משה, \u0003מוסרין לו כל שבעה כדי לחנכו\u0004 (ללמדו) \u0003בעבודה.\u0004","\u0003מכאן אמרו\u0004 במשנה: \u0003שבעה ימים קודם יום הכיפורים מפרישין כהן גדול מביתו ללשכת פרהדרין. וכשם שמפרישין כהן גדול כך מפרישין כהן השורף את הפרה\u0004 ומביאים אותו \u0003ללשכה שעל פני הבירה\u0004 שהיתה פונה \u0003צפונה מזרחה. ואחד זה\u0004 הכהן הפורש לעבודת יום הכיפורים \u0003ואחד זה\u0004 הכהן הפורש לצורך עשיית הפרה \u0003מזין עליו כל שבעה\u0004 ימי הפרישה \u0003מכל חטאות\u0004 (אפר פרה אדומה) \u0003שהיו שם\u0004 במקדש.","\u0003ואם תאמר\u0004 ותקשה: שהרי \u0003במלואים\u0004 היו מזים \u0003דם, הכא\u0004 \u0005[כאן]\u0006 \u0003מים, אמרת\u0004 לתרץ: \u0003נכנסו מים תחת דם. ו\u0004יש להוכיח עוד ממה שהוא \u0003אומר\u0004 בפסוק: \u0003\"כאשר עשה ביום הזה צוה ה' לעשת לכפר עליכם\"\u0004 (ויקרא ח, לד) ופירושו: \u0003\"לעשת\" — אלו מעשה פרה, \"לכפר\" — אלו מעשה יום הכיפורים.\u0004 ומברייתא זו הוכחה לדברי ר' יוחנן.","ומעתה מבררים את הברייתא לגופה, ומקשים: \u0003והאי\u0004 \u0005[והרי זה,\u0006 מה שנאמר\u0005]\u0006 \u0003\"בזאת\" מיבעי ליה לגופיה\u0004 \u0005[נצרך לו לגופו]\u0006 של הכתוב, כאמור, שצריך להביא \u0003פר בן בקר לחטאת ואיל לעולה! אמרי\u0004 \u0005[אומרים,\u0006 מתרצים\u0005]:\u0006 \u0003אי לקרבן\u0004 \u0005[אם]\u0006 \u0003לחודיה\u0004 \u0005[בלבד]\u0006 היתה הכוונה, אם כן \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 כאן את הביטוי \u0003\"בזה\"\u0004 או \u0003\"באלה\"\u0004 שמובנו לענין הפר, או הפר והאיל, \u0003מאי\u0004 \u0005[מה]\u0006 משמעו של הביטוי \u0003\"בזאת\"\u0004 שהוא לשון נקיבה ואינו מתייחס לא לפר ולא לאיל — \u0003שמעת מינה תרתי\u0004 \u0005[שומע אתה מכאן שנים,\u0006 שני דברים\u0005]\u0006 גם לענין הבאת הקרבנות, וגם לענין פרישה.","ושואלים עוד על לשון הברייתא: \u0003מאי\u0004 \u0005[מה\u0006 משמעו\u0005]\u0006 של \u0003\"ואומר\"\u0004 כלומר, לשם מה הובאה בברייתא ראיה נוספת מפסוק אחר, ומדוע אין די בראיה הראשונה? \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 שמא \u0003יום הכיפורים קמא\u0004 \u0005[ראשון]\u0006 שעשה אהרן \u0003הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003פרישה, כדאשכחן\u0004 \u0005[כמו שמצינו]\u0006 \u0003במלואים\u0004 שהיו צריכים הכהנים פרישה כדי להתקדש בכהונתם תחילה \u0003אבל ביום הכיפורים דעלמא\u0004 \u0005[סתם]\u0006 \u0003לא\u0004 יפרשו, שהרי כבר פרשו בפעם ראשונה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לומר באופן אחר: \u0003כהן גדול קמא\u0004 \u0005[הראשון]\u0006 \u0003הוא דבעי\u0004 \u0005[שצריך]\u0006 \u0003פרישה\u0004 כשם שהוצרכו כל הכהנים במילואים \u0003אבל כהן גדול בעלמא\u0004 \u0005[סתם]\u0006 שבא אחריו לא יצטרך פרישה לפני יום הכיפורים, על כן \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ממה נאמר: \u0003\"כאשר עשה כן תעשו\"\u0004 — שתהא זו מצווה לדורות.","וכאמור, \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003ריש לקיש: משה עלה בענן, ונתכסה בענן, ונתקדש בענן, כדי לקבל תורה לישראל בקדושה, שנאמר: \"וישכן כבוד ה' על הר סיני\u0004 ויכסהו הענן ששת ימים ויקרא אל משה ביום השביעי מתוך הענן\u0003\"\u0004 (שמות כד, טז). \u0003זה היה מעשה אחר עשרת הדברות\u0004 שניתנו לישראל, ושישה ימים אלה \u0003היו תחלה לארבעים יום\u0004 שהיה משה על ההר (שמות כד, יח), אלו \u0003דברי ר' יוסי הגלילי.\u0004 ושיטת ר' יוסי הגלילי היא כדברי ריש לקיש, שהיה על משה לפרוש שישה ימים לפני שרשאי היה להכנס לתוך מקום גילוי השכינה.","ואילו \u0003ר' עקיבא אומר:\u0004 מעשה זה ודאי היה לפני עשרת הדברות ומה שנאמר \u0003\"וישכן כבוד ה'\u0004 על הר סיני \u0003\"\u0004כוונתו לגילוי כבוד שכינה שהיה על הר סיני \u0003מראש חודש\u0004 סיון והלאה, שישה ימים לפני מתן תורה."],["ומה שנאמר \u0003\"ויכסהו הענן\",\u0004 כוונתו שכסה את ה\u0003הר\u0004 ולא שכיסה את משה. \u0003\"ויקרא אל משה\"\u0004 ש\u0003משה וכל ישראל עומדין\u0004 לרגלי ההר ושומעים, ואם לא נתכוון שיעלה משה להר מפני מה קראו — \u0003לא בא הכתוב אלא לחלק כבוד למשה\u0004 שכל העם ישמעו שה' קורא ומדבר אליו. \u0003ר' נתן אומר\u0004 שאכן נקרא משה להיות בענן, אלא שאותה כניסה לא נועדה לשם פרישות וטהרה, \u0003לא בא הכתוב אלא למרק אכילה ושתיה שבמעיו לשומו\u0004 (לעשותו) \u0003כמלאכי השרת\u0004 שאינם נזקקים לאכילה ושתיה.","\u0003ר' מתיא בן חרש אומר: לא בא הכתוב\u0004 שקראו להיות בענן \u0003אלא לאיים עליו,\u0004 כלומר להביא אותו להרגשה של אימת הבורא, \u0003כדי שתהא תורה ניתנת באימה, ברתת\u0004 (ברעדה) \u0003ובזיע\u0004 (זעזוע), \u0003שנאמר: \"עבדו את ה' ביראה וגילו ברעדה\"\u0004 (תהלים ב, יא). כיון שהוזכר פסוק זה שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וגילו ברעדה\"?\u0004 שהרי לכאורה הגילה (השמחה) והרעדה הם מושגים סותרים! \u0003אמר רב אדא בר מתנה אמר רב: במקום גילה\u0004 כלומר במקום שבו יש שמחה של מצוה \u0003שם\u0004 גם \u0003תהא רעדה\u0004 של יראת שמים.","כיון שעסקנו בפירוש המקראות בענין מתן תורה שואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005חלוקים]\u0006 \u0003ר' יוסי הגלילי ור' עקיבא?\u0004 ומסבירים כי חלוקים הם \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה],\u0006 \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בששה בחודש\u0004 סיון \u0003ניתנה תורה לישראל, ר' יוסי אומר: בשבעה בו.\u0004 לדעת \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר בששה, בששה ניתנה\u0004 תורה, שנאמרו בו עשרת הדברות \u0003ובשבעה\u0004 לחודש \u0003עלה דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקרא אל משה ביום השביעי\"\u0004 (שמות כד, טז). \u0003מאן\u0004 \u0005[מי]\u0006 ש\u0003אמר\u0004 ש\u0003בשבעה\u0004 בחודש ניתנה תורה, \u0003בשבעה ניתנה, ובשבעה עלה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקרא אל משה ביום השביעי\".\u0004","ומבארים את הקשר בין השיטות, \u0003ר' יוסי הגלילי סבר לה כתנא קמא\u0004 \u0005[סבור\u0006 הוא \u0005כתנא הראשון]\u0006 בברייתא ש\u0003אמר בששה בחודש ניתנה תורה, הלכך\u0004 (על כן) צריכים לפרש כי \u0003זה\u0004 כל האמור שם \u0003היה מעשה אחר עשרת הדברות,\u0004 ולפיכך מפרש הוא כך: \u0003\"וישכן כבוד ה' על הר סיני ויכסהו הענן ששת ימים\"\u0004 ולמי כיסה הענן \u0003— למשה, \"ויקרא אל משה ביום השביעי\" —\u0004 כדי \u0003לקבולי\u0004 \u0005[לקבל]\u0006 את \u0003שאר\u0004 ה\u0003תורה\u0004 נוסף לעשרת הדברות. \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לפרש \u0003\"וישכן כבוד ה'\"\u0004 משמעו \u0003מראש חדש\u0004 סיון, \u0003\"ויכסהו הענן\"\u0004 משמעו את ה\u0003הר, \"ויקרא אל משה ביום השביעי\"\u0004 רק כדי \u0003לקבל את עשרת הדברות,\u0004 אולם \u0003הא קבילו להו\u0004 \u0005[הרי קיבלו הם\u0006 כבר\u0005]\u0006 את עשרת הדברות \u0003מששה\u0004 בחודש לפי שיטה זו, \u0003והא אסתלק\u0004 \u0005[והרי הסתלק]\u0006 ה\u0003ענן\u0004 שהיה על ההר כבר \u0003מששה\u0004 לחודש!","ואילו \u0003ר' עקיבא סבר לה\u0004 בענין זה כשיטת \u0003ר' יוסי,\u0004 ש\u0003אמר: בשבעה בחדש ניתנה תורה לישראל.\u0004 ולכן הוא מפרש שקריאה זו שנקרא משה ביום השביעי היתה בשביעי בסיון, מיד לאחר נתינת עשרת הדברות. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לשיטת \u0003ר' עקיבא\u0004 והסבורים כשיטתו שבשבעה בסיון ניתנה התורה, ומיד לאחר מכן היה משה בהר ארבעים יום, \u0003היינו דמשכחת לה\u0004 \u0005[זהו שאתה מוצא]\u0006 לפי חשבון זה כי \u0003בשבעה עשר בתמוז נשתברו הלוחות\u0004 כפי המסורת המקובלת בענין זה. כיצד? מנה \u0003עשרין וארבעה\u0004 ימים של חודש \u0003סיון, ושיתסר\u0004 \u0005[ושישה עשר\u0006 ימים\u0005]\u0006 של חודש \u0003תמוז, מלו להו ארבעין יומין דהוה\u0004 \u0005[מלאו להם ארבעים ימים שהיה]\u0006 \u0003בהר, ובשבסר\u0004 \u0005[ובשבעה עשר]\u0006 \u0003בתמוז נחית\u0004 \u0005[ירד]\u0006 מן ההר \u0003ואתא ותברינהו\u0004 \u0005[ובא ושברם]\u0006 את ה\u0003לוחות\u0004\u0005.\u0006","\u0003אלא לר' יוסי הגלילי\u0004 ש\u0003אמר: ששה\u0004 ימים של \u0003פרישה\u0004 אחרי מתן תורה ועוד \u0003ארבעין\u0004 יום של שהיה ב\u0003הר,\u0004 ומתוך שיש להוסיף שישה ימים נוספים, אם כן \u0003עד עשרין ותלת\u0004 \u0005[עשרים ושלושה]\u0006 \u0003בתמוז לא אתבור\u0004 \u0005[נשברו]\u0006 ה\u0003לוחות,\u0004 וזאת בניגוד למסורת המקובלת! ומשיבים: \u0003אמר לך\u0004 \u0005[יכול היה לומר לך]\u0006 \u0003ר' יוסי הגלילי: ארבעין\u0004 יום של ה\u0003הר\u0004 הם מספר כולל \u0003בהדי\u0004 \u0005[עם]\u0006 \u0003ששה\u0004 ימים אלו של ה\u0003פרישה.\u0004","ב\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: מה שנאמר \u0003\"ויקרא אל משה\"\u0004 כוונתו ש\u0003משה וכל ישראל עומדין\u0004 ושומעים. ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לר' אלעזר,\u0004 ש\u0003אמר ר' אלעזר:\u0004 מה שנאמר \u0003\"ויקרא אל משה\" — משה וכל ישראל עומדין,\u0004 ומה שהיתה הקריאה דווקא למשה \u0003לא בא הכתוב אלא לחלק לו כבוד למשה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 מתוך דבריו מובן שקול ה' נשמע לכל ישראל, והלא שנינו שהכתוב אומר: \"ובבוא משה אל אוהל מועד לדבר איתו וישמע את הקול מדבר אליו מעל הכפורת אשר על ארון העדות מבין שני הכרובים וידבר אליו\" (במדבר ז, פט), שהיה יכול לומר: \"וישמע את ה\u0003קול\u0004 מדבר \u0003לו\",\u0004 והדגיש ואמר: \u0003\"\u0004וישמע את ה\u0003קול\u0004 מדבר \u0003אליו\"\u0004 לומר: אליו בלבד דיבר, כלומר: \u0003משה שמע\u0004 את קול ה' ואילו \u0003כל ישראל לא שמעו!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששמעו כולם היה בהר \u0003סיני, והא\u0004 \u0005[זה]\u0006 ששמע רק משה לבדו — \u0003באהל מועד. ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003לא קשיא\u0004 \u0005[אינו קשה]\u0006 ואפשר לומר: \u0003הא\u0004 \u0005[זה]\u0006 ששמעו כולם את הקול הוא \u0003בקריאה\u0004 שקרא ה' למשה לדבר אליו, \u0003הא\u0004 \u0005[זה]\u0006 ששמע משה לבדו — הוא \u0003בדבור,\u0004 שמה שאמר ה' למשה אחר כך, שמע רק משה לבדו.","מסופר: \u0003ר' זריקא רמי קראי קמיה\u0004 \u0005[השליך,\u0006 הראה סתירה, \u0005בכתובים לפני]\u0006 \u0003ר' אלעזר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך היה הדבר \u0003אמר ר' זריקא: ר' אלעזר\u0004 עצמו \u0003רמי\u0004 \u0005[השליך\u0006 הראה סתירה\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 במקום אחד: \u0003\"ולא יכל משה לבא אל אהל מועד כי שכן עליו הענן\"\u0004 (שמות מ, לה) משמע שאין משה יכול לבוא בענן, \u0003וכתיב\u0004 \u0005[\u0006ובמקום אחר \u0005נאמר]:\u0006 \u0003\"ויבא משה בתוך הענן\"\u0004 (שמות כד, יח)! אלא, \u0003מלמד שתפסו הקדוש ברוך הוא למשה והביאו בענן\u0004 כי בעצמו לא היה יכול לעשות זאת.","\u0003דבי\u0004 \u0005[בבית מדרשו]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנו]:\u0006 \u0003נאמר כאן \"בתוך\",\u0004 ככתוב: \"ויבוא משה בתוך הענן\", \u0003ונאמר להלן \"בתוך\" — \"ויבאו בני ישראל בתוך הים\u0004 ביבשה\u0003\"\u0004 (שמות יד, כב) \u0003מה להלן\u0004 בביאת ישראל לתוך הים היה \u0003שביל\u0004 של יבשה בתוך הים \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"והמים להם חומה\"\u0004 (שמות יד,כב), \u0003אף כאן — שביל\u0004 נעשה לו למשה בתוך הענן שיוכל להיכנס בו, אבל לא נכנס בתוך הענן עצמו.","נאמר \u0003\"ויקרא אל משה וידבר\u0004 ה' אליו מאוהל מועד לאמור\u0003\"\u0004 (ויקרא א, א) ויש לשאול \u0003למה הקדים קריאה לדיבור\u0004 ולא דיבר אליו מיד? אלא \u0003לימדה תורה דרך ארץ: שלא יאמר אדם דבר לחבירו\u0004 סתם \u0003אלא אם כן קורהו\u0004 ופונה אליו קודם. ומעירים, דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' חנינא,\u0004 ש\u0003אמר רבי חנינא: לא יאמר אדם דבר לחבירו אלא אם כן קורהו\u0004 תחילה. על אותו כתוב דרשו: \u0003\"לאמר\" — אמר ר' מוסיא בר בריה\u0004 \u0005[בן בנו]\u0006 של \u0003ר' מסיא, משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' מוסיא רבה\u0004 \u0005[הגדול]\u0006 \u0003מניין לאומר דבר לחבירו שהוא\u0004 דבר זה \u0003בבל יאמר\u0004 שאסור להיאמר לאחרים \u0003עד שיאמר לו\u0004 החבר במפורש: \u0003לך אמור\u0004 לאחרים — \u0003שנאמר: \"וידבר ה' אליו מאהל מועד לאמר\"\u0004 שהוא נוטריקון של \"לא אמור\", שאין לו לומר לאחרים עד שיקבל רשות מפורשת לכך.","לאחר הסטיה לביאור המקראות של הר סיני שבים אנו לדבריהם של ר' יוחנן וריש לקיש. \u0003מכלל\u0004 הדברים, ממה שהקשה ריש לקיש לר' יוחנן מן המילואים שהכל מעכב בהם, ומזה שהסכים לכך כנראה ר' יוחנן, למדים אנו \u0003דתרווייהו סבירא להו\u0004 \u0005[שניהם סבורים הם]\u0006 כי \u0003מלואים — כל הכתוב בהן מעכב בהן\u0004 ואם שינו אף בפרט אחד — היה צורך לעשות מחדש. כי, \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בדבר \u0003ר' יוחנן ור' חנינא, חד\u0004 \u0005[אחד מהם]\u0006 \u0003אמר כל הכתוב בהן\u0004 במילואים \u0003מעכב בהן, וחד\u0004 \u0005[ואחד מהם]\u0006 \u0003אמר: דבר המעכב\u0004 באותם קרבנות \u0003לדורות מעכב\u0004 אף \u0003בהן,\u0004 ואילו דבר \u0003שאין מעכב לדורות — אין מעכב בהן.\u0004","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 כי \u0003ר' יוחנן הוא\u0004 ש\u0003אמר כל הכתוב בהן מעכב בהן.\u0004 כי \u0003מדקאמר ליה\u0004 \u0005[ממה שאמר לו]\u0006 \u0003ר' שמעון בן לקיש לר' יוחנן: אי\u0004 \u0005[אם]\u0006 \u0003מה מלואים כל הכתוב בהן מעכב בהן ולא קא מהדר ליה\u0004 \u0005[משיב לו]\u0006 ר' יוחנן \u0003ולא מידי\u0004 \u0005[דבר]\u0006 לחלוק עליו, אם כן הרי זו הוכחה שאף ר' יוחנן עצמו סבור כן. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכן דעתו של ר' יוחנן.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מהו\u0006 ההבדל ההלכתי \u0005ביניהם]\u0006 בין ר' יוחנן ור' חנינא, הלכה למעשה?"],["\u0003אמר רב יוסף:\u0004 לענין חובת \u0003סמיכה\u0004 על הקרבנות \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה. \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 כי \u0003כל הכתוב בהן\u0004 במילואים \u0003מעכב בהן\u0004 אף דבר שאין מעכב לדורות —אם כן \u0003סמיכה מעכבא\u0004 \u0005[מעכבת],\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003דבר שאין מעכב לדורות אין מעכב בהן\u0004 — אם כן \u0003סמיכה לא מעכבא\u0004 \u0005[אינה מעכבת]\u0006 גם במילואים.","ושואלים: ובהלכות קרבנות הקבועים \u0003לדורות מנא לן דלא מעכבא\u0004 \u0005[מנין לנו\u0006 שאין הסמיכה \u0005מעכבת]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 נאמר: \u0003\"וסמך\u0004 ידו על ראש העולה \u0003ונרצה\u0004 לו לכפר עליו\u0003\"\u0004 (ויקרא א, ד), \u0003וכי סמיכה מכפרת\u0004 ובה תלויה הכפרה? \u0003והלא אין כפרה אלא בדם, שנאמר: \"כי הדם הוא בנפש יכפר\"\u0004 (ויקרא יז, יא)!","ואם כן \u0003מה תלמוד לומר \"וסמך\" \"ונרצה\"?\u0004 — מלמד \u0003שאם עשאה\u0004 והחשיבה \u0003לסמיכה\u0004 רק כ\u0003שירי\u0004 וכטפילה ל\u0003מצוה\u0004 ולכך לא סמך —\u0003 מעלה עליו הכתוב כאילו לא כיפר\u0004 כפרה מובחרת, ועם כל זאת, להלכה \u0003\"וכפר\"!\u0004 הרי שמצוות הסמיכה אינה מעכבת לדורות, שאף אם לא עשאה נתכפר, ואילו במילואים היתה הסמיכה מעכבת.","\u0003רב נחמן בר יצחק אמר:\u0004 חובת \u0003תנופה איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 בין ר' יוחנן לר' חנינא, הבדל למעשה. \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאמר]\u0006 \u0003כל הכתוב בהן\u0004 במילואים \u0003מעכב בהן —\u0004 אם כן \u0003מעכבא\u0004 \u0005[מעכבת]\u0006 התנופה. \u0003ולמאן דאמר\u0004 \u0005[\u0006ולשיטת \u0005מי שאמר]\u0006 \u0003דבר שאין מעכב לדורות אין מעכב\u0004 אף \u0003בהן —\u0004 אם כן \u0003לא מעכבא\u0004 \u0005[אין\u0006 התנופה \u0005מעכבת].\u0006","ושואלים: \u0003ולדורות מנא לן דלא מעכבא\u0004 \u0005[מנין לנו שאין\u0006 התנופה \u0005מעכבת]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"\u0004ולקח כבש אחד אשם \u0003לתנופה לכפר\"\u0004 (ויקרא יד, כא), ויש לשאול: \u0003וכי תנופה מכפרת? והלא אין כפרה אלא בדם,\u0004 שנאמר: \u0003\"כי הדם הוא בנפש יכפר\"\u0004 (ויקרא יז, יא)! אם כן \u0003מה תלמוד לומר \"לתנופה לכפר\"\u0004 — ללמדנו \u0003שאם עשאה לתנופה\u0004 רק כ\u0003שירי מצוה\u0004 ולא קיימה — \u0003מעלה עליו הכתוב כאילו לא כפר,\u0004 אולם למעשה \u0003\"וכפר\".\u0004","\u0003רב פפא אמר:\u0004 ענין \u0003פרישת שבעה איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה. כיצד? \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003כל הכתוב בהן מעכב בהן\u0004 — אם כן \u0003מעכבא\u0004 \u0005[מעכבת]\u0006 פרישה לשבעת הימים, שאם לא פרשו היו קרבנותיהם נפסלים. ואילו \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003דבר שאינו מעכב לדורות אינו מעכב בהן — לא מעכבא\u0004 \u0005[אין\u0006 הפרישה \u0005מעכבת].\u0006","ושואלים: \u0003ולדורות מנא לן דלא מעכבא\u0004 \u0005[מנין לנו שאינה מעכבת]?\u0006 ומשיבים: \u0003מדקא תני\u0004 \u0005[ממה ששנינו]\u0006 במשנתנו שהיו \u0003\"מתקינין\"\u0004 ממלא מקום הכהן הגדול, \u0003ולא קתני\u0004 \u0005[שנה]\u0006 שהיו \u0003\"מפרישין\"\u0004 אותו אף שיתכן שבסופו של דבר יצטרך לשמש ביום הכיפורים ככהן גדול בפועל, הרי שאין חסרון הפרישה מעכב.","\u0003רבינא אמר: ריבוי\u0004 בגדים, שיהא הכהן הגדול לובש את כל שמונת בגדי הכהונה הגדולה כל אותם \u0003שבעה\u0004 ימי פרישה וכן \u0003משיחה\u0004 שלו בשמן המשחה כל \u0003שבעה\u0004 ימים אלו, היא הנקודה ש\u0003איכא בינייהו\u0004 \u0005[שיש ביניהם]\u0006 הבדל למעשה בין ר' יוחנן ור' חנינא אם יש בהן כדי לעכב. \u0003למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003כל הכתוב בהן מעכב בהן\u0004 — אם כן \u0003מעכבא\u0004 \u0005[מעכבת]\u0006 הן לבישת שמונת הבגדים וכן המשיחה. \u0003ולמאן דאמר\u0004 \u0005[ול\u0006שיטת \u0005מי שאומר]\u0006 \u0003דבר שאין מעכב לדורות אין מעכב\u0004 אף \u0003בהן\u0004 — אם כן אף זו \u0003לא מעכבא\u0004 \u0005[אינה מעכבת].\u0006","ושואלים: \u0003ולדורות מנא לן דלא מעכבא\u0004 \u0005[מנין לנו שאין\u0006 המשיחה \u0005מעכבת]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב: \u0003\"וכפר הכהן אשר ימשח אתו ואשר ימלא את ידו לכהן תחת אביו\"\u0004 (ויקרא טז, לב) ושאלו: \u0003מה תלמוד לומר\u0004 בכפילות לשון זו?","— \u0003לפי שנאמר: \"שבעת ימים ילבשם הכהן תחתיו מבניו\u0004 אשר יבוא אל אוהל מועד לשרת בקודש\u0003\"\u0004 (שמות כט, ל), \u0003אין לי\u0004 ללמוד מפסוק זה \u0003אלא\u0004 שהכהן הגדול הוא זה ש\u0003נתרבה\u0004 כלומר שלבש את כל שמונת הבגדים במשך \u0003שבעה\u0004 ימים, \u0003ונמשח\u0004 במשך \u0003שבעה\u0004 ימים. ואם כן, כהן ש\u0003נתרבה\u0004 בבגדים \u0003שבעה\u0004 ימים \u0003ונמשח\u0004 בשמן המשחה \u0003יום אחד\u0004 בלבד, או ש\u0003נתרבה יום אחד\u0004 בלבד \u0003ונמשח שבעה מניין\u0004 שאף בכך נעשה כהן גדול? \u0003תלמוד לומר: \"אשר ימשח אתו ואשר ימלא את ידו\" — מכל מקום,\u0004 בלא הגבלת מספר הימים.","ושואלים: אכן, \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 חובת \u0003ריבוי שבעה לכתחלה\u0004 אולם חובת \u0003משיחה שבעה לכתחלה מנלן\u0004 \u0005[מנין לנו]?\u0006 שהרי לדעת רבינא לכתחילה אף המשיחה שבעה ימים, אלא שאינה מעכבת לדורות, אולם מנין למדנו שקיימת מצוה כזו לכתחילה?","ומשיבים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 להוכיח \u0003מדאיצטריך קרא למעוטה\u0004 \u0005[ממה שהוצרך הכתוב למעטה]\u0006 שהרי הכתוב \"וכיפר הכהן אשר ימשח אותו ואשר ימלא את ידו\" בא למעט ולצמצם חובה הנלמדת ממקומות אחרים, לומר שבכל אופן שנמשח ומתמנה נעשה בכך כהן גדול, ואם כן מובן מכאן שלכתחלה צריך להמשח שבעה ימים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הוכחה אחרת ממה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ובגדי הקדש אשר לאהרן יהיו לבניו אחריו למשחה בהם ולמלא בם את ידם\"\u0004 (שמות כט, כט), \u0003איתקש\u0004 \u0005[הושווה]\u0006 בפסוק זה \u0003משיחה לריבוי,\u0004 ללמדנו: \u0003מה ריבוי\u0004 בגדים מלכתחילה הריהו \u0003שבעה\u0004 ימים, \u0003אף משיחה\u0004 מלכתחילה יש לקיימה \u0003שבעה\u0004 ימים.","אחרי שנתבררו ההבדלים ההלכתיים שבין דברי ר' יוחנן ור' חנינא ביחס למילואים, באים לדון בטעמיהם. ושואלים: \u0003מאי טעמא דמאן דאמר\u0004 \u0005[מה טעמו של מי שאומר]\u0006 \u0003כל הכתוב בהן\u0004 במילואים \u0003מעכב? אמר ר' יצחק בר ביסנא אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ועשית לאהרן ולבניו ככה\u0004 ככל אשר צויתי אותכה שבעת ימים תמלא ידם\u0003\"\u0004 (שמות כט, לה) — הביטוי \u0003\"ככה\"\u0004 בא להדגיש כי \u0003עיכובא\u0004 \u0005[לעכב]\u0006 \u0003הוא,\u0004 שרק כך יש לעשות ולא בכל אופן אחר. על ראיה זו מקשים: \u0003תינח\u0004 \u0005[\u0006דבר זה \u0005נוח]\u0006 ומלמד ל\u0003כל\u0004"],["\u0003מילתא דכתיבא בהאי ענינא\u0004 \u0005[דבר שכתוב בענין זה]\u0006 בספר שמות בפרשת מצוות המילואים אליו מתייחסים הדברים. אולם, \u0003מילתא דלא כתיבא בהאי ענינא מנא לן\u0004 \u0005[דבר שאינו כתוב\u0006 במפורש \u0005בענין זה מנין לנו]\u0006 שאף הוא מעכב? שהרי יש פרטי דינים שלא נאמרו שם אלא נאמרו בספר ויקרא, כשמסופר כיצד נעשו המילואים!","\u0003אמר רב נחמן בר יצחק: יליף\u0004 \u0005[למד]\u0006 דבר זה בגזירה שווה מן המילים \u0003\"פתח\" \"פתח\",\u0004 שנאמר בשעת הציווי: \"פתח אוהל מועד\" (שמות כט, לב) וכן נאמר בעשייה: \"פתח אוהל מועד\" (ויקרא ח, לא), ללמד מפרשה אחת על חברתה. \u0003רב משרשיא אמר:\u0004 אין צורך בגזירה שווה, אלא מעניינו הוא נלמד, שאף בשעת העשייה נאמר: \u0003\"ושמרתם את משמרת ה'\u0004 ולא תמותו כי כן צוויתי\u0003\"\u0004 (ויקרא ח, לה) הרי הקפדה זו של \"משמרת ה'\" באה ללמד \u0003עכובא\u0004 \u0005[לעכב]\u0006 שאף פרטי הדינים שנאמרו בעשייה מעכבים. \u0003רב אשי אמר:\u0004 נאמר בכתוב: \u0003\"כי כן צויתי\"\u0004 והדגשה זו באה ללמד ל\u0003עכובא\u0004 \u0005[לעכב].\u0006","כיון שהוזכר כתוב זה מביאים מדרש הלכה הקשור בו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת המילואים כמה לשונות של ציווי: \u0003\"כי כן צויתי\"\u0004 (ויקרא ח, לה), \u0003\"כאשר צויתי\"\u0004 (ויקרא י, יח), וכן \u0003\"כאשר צוה ה'\"\u0004 (ויקרא י, טו) ומה למדים אנו מחזרות אלה? כך יש ללמוד: \u0003\"כי כן צויתי\"\u0004 כוונתו להדגיש: אפילו \u0003באנינות\u0004 (ביום ראשון לאבילות, שהאבל קשה) \u0003יאכלום\u0004 לקרבנות הללו. \u0003\"כאשר צויתי\" — בשעת מעשה אמר להם,\u0004 שבאותה שעה שמתו נדב ואביהוא והיו אהרן ובניו אבלים, אמר להם לעשות כן. וכשאומר \u0003\"כאשר צוה ה'\"\u0004 הריהו בא לומר: \u0003ולא מאלי\u0004 (מעצמי) לפי סברתי והבנתי \u0003אני אומר\u0004 כן, אלא כך נאמר לי במפורש מפי הקדוש ברוך הוא.","כיון שהזכרנו דברים שאינם מפורשים בפרשה מביאים מה ש\u0003אמר ר' יוסי בר' חנינא: מכנסים\u0004 כחלק מפרטי לבוש הכהן בעבודת המילואים \u0003אין כתובין\u0004 ומוזכרים \u0003בפרשה,\u0004 ו\u0003כשהוא אומר \"וזה הדבר אשר תעשה להם לקדש אתם לכהן\u0004 לי\u0003\"\u0004 (שמות כט, א) הרי זה בא \u0003להביא\u0004 (לרבות) את \u0003המכנסים\u0004 שכן \"ו\" של המילה \"וזה\" בא להוסיף על מה שנאמר קודם לכן ובין השאר אף את דין המכנסים, וכן לרבות לימי המילואים אף את קרבן \u0003עשירית האיפה\u0004 שמביא כל כהן ביום חינוכו לעבודה.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 לענין \u0003מכנסים\u0004 מובן כיצד למדים אנו אותם, שהרי \u0003כתיבי בענינא\u0004 \u0005[כתובים\u0006 הם \u0005בענין]\u0006 ה\u0003בגדים\u0004 שנתפרש עניינם סמוך לענין המילואים, \u0003אלא\u0004 קרבן \u0003עשירית האיפה מנא לן\u0004 \u0005[מנין לנו]\u0006 שחייבים בו במילואים? ומשיבים: \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 הלכה זו בגזירה שווה של המילים \u0003\"זה\", \"זה\",\u0004 שנאמר: \u0003\"זה קרבן אהרן ובניו אשר יקריבו לה'\u0004 ביום המשח אותו \u0003עשירית האפה\"\u0004 (ויקרא ו, יג) ובענין מילואים נאמר: \"וזה הדבר\", ללמד שגם במילואים יש להביא עשירית האיפה.","\u0003אמר ר' יוחנן משום ר' שמעון בן יוחאי: מנין שאף מקרא פרשה\u0004 זו של מילואים לפני הציבור \u0003מעכב\u0004 את המילואים, \u0003תלמוד לומר: \"ויאמר משה אל העדה זה הדבר אשר צוה ה'\u0004 לעשות\u0003\"\u0004 (ויקרא ח, ה) ללמד: \u0003אפילו דיבור\u0004 (\"הדבר\") מעכב שגם אמירת הדברים לעדת ישראל מעכבת במצוה זו.","כיון שאנו עוסקים בפרשת המילואים, שואלים: \u0003כיצד\u0004 באיזה סדר \u0003הלבישן\u0004 משה לאהרן ובניו את בגדי הכהונה? ותוהים: \u0003כיצד הלבישן?!\u0004 מה מקום לשאלה זו, הרי \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ומה לנו לשאול על מה שכבר היה, ואין ללמוד ממנו להלכה? \u0003אלא\u0004 אם שואלים בענין זה כך יש לשאול: \u0003כיצד מלבישן לעתיד לבוא\u0004 לכשיחיו המתים ויתחדש סדר העבודה, כיצד ילביש את הכהנים? אף נוסח זה נדחה: \u0003לעתיד לבוא נמי\u0004 \u0005[גם כן]\u0006 \u0003לכשיבואו אהרן ובניו ומשה עמהם,\u0004 והרי הוא יודע כיצד סדר הלבישה, ומה לנו לחקור בדבר?","\u0003אלא\u0004 כך יש לשאול: \u0003כיצד הלבישן\u0004 כדי \u0003למיסבר קראי\u0004 \u0005[להבין את הכתובים].\u0006 שכן הכתובים הדנים בדבר, סותרים זה את זה במקצת. ומשיבים: אכן בשאלה זו \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה בני ר' חייא ור' יוחנן. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: אהרן\u0004 הולבש בגדים תחילה \u0003ואחר כך בניו, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אהרן ובניו\u0004 הולבשו \u0003בבת אחת\u0004 בזה אחר זה שלא להפסיק ולשנות את הסדר.","\u0003אמר אביי: בכתונת ומצנפת — כולי עלמא לא פליגי\u0004 \u0005[לדעת הכל אינם חלוקים]\u0006 ש\u0003אהרן\u0004 הולבש קודם \u0003ואחר כך בניו.\u0004 ומדוע אומרים כן כי \u0003בין בצואה\u0004 (בכתובים המצווים על המילואים) \u0003ובין\u0004 בכתובים המדברים \u0003בעשייה — אהרן קדים\u0004 \u0005[קודם]\u0006 בתיאור לבישת בגדים אלה, ואם כן פשוט לנו לומר שבזה הוקדם אהרן. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה בלבישת ה\u0003אבנט,\u0004 מי מהם קדם ללובשו. ובירור צדדי הספק: \u0003מאן דאמר\u0004 \u0005[מי שאמר]\u0006 \u0003אהרן ואחר כך בניו,\u0004 הדבר נלמד ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויחגור אתו באבנט\"\u0004 (ויקרא ח, ז) \u0003והדר כתיב\u0004 \u0005[ואחר כך נאמר]:\u0006 \u0003\"ויחגר אתם אבנט\"\u0004 (ויקרא ח, יג) משמע שתחילה הלביש את אהרן את כל בגדיו ואבנט בכללם, ואחר כך הלביש את הבנים. \u0003ומאן דאמר\u0004 \u0005[ומי שאמר]\u0006 כי \u0003אהרן ובניו בבת אחת — דכתיב\u0004 \u0005[שנאמר]\u0006 בציווי לאחר שמצוה על הלבשת בגדים לאהרן: \u0003\"וחגרת אתם\u0004 אבנט אהרן ובניו\u0003\"\u0004 (שמות כט, ט) משמע חגירת אבנט היתה לכולם כאחת. ושואלים: \u0003ולמאן דאמר\u0004 \u0005[\u0006ולדעת \u0005מי שאמר]\u0006 כי \u0003אהרן ובניו בבת אחת, הכתיב\u0004 \u0005[הרי נאמר]:\u0006 \u0003\"ויחגר אתו באבנט\" והדר כתיב\u0004 \u0005[ואחר כך נאמר]\u0006 בהפסק ניכר: \u0003\"ויחגר אתם אבנט\",\u0004 משמע שלמעשה סיים להלביש את אהרן ורק אחר כך הלביש את בניו!"],["\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך:\u0004 הכתוב \u0003ההוא\u0004 בא ללמדנו כי \u0003אבנטו של כהן גדול לא זה הוא אבנטו של כהן הדיוט,\u0004 כי אבנטו של כהן גדול מפורש שהיה עשוי משש תכלת וארגמן, ואילו אבנט של כהן הדיוט שלא נתפרשה עשייתו היה עשוי פשתן כשאר בגדיו. אכן לבישתו על ידי אהרן ובניו היתה כאחת.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[\u0006ולשיטת \u0005מי שאומר]\u0006 כי את \u0003אהרן\u0004 הלביש תחילה \u0003ואחר כך\u0004 את \u0003בניו, והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"וחגרת אתם אבנט\",\u0004 משמע שחגירתו היתה לכולם כאחד! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: ההוא\u0004 אותו כתוב \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כדעה השניה לענין זה, כי \u0003אבנטו של כהן גדול זהו אבנטו של כהן הדיוט,\u0004 שגם אבנטו של ההדיוט היה עשוי שש ותכלת וארגמן, ולכן אף על פי שחילק ביניהם בעשייה לא חילק ביניהם בציווי, ללמד שכל האבנטים שווים בעשייתם.","ושואלים: ואם כן \u0003\"ויחגר אתו אבנט\" \"ויחגר אתם\" למה לי?\u0004 ומסבירים כי \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 את \u0003אהרן\u0004 הלביש תחילה \u0003ואחר כך בניו.\u0004 לעצם הדבר שואלים: \u0003ובבת אחת מי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]\u0006 אפשרות שיוכל משה לחגור לאהרן וארבעת בניו אבנטים בבת אחת? ומסבירים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 רק לומר \u0003דאקדים\u0004 \u0005[ש\u0006אכן \u0005הקדים]\u0006 את אהרן, וחגרם בזה אחר זה לפי מעלתם, אלא בא לומר שלא הפסיק בין חגירת אהרן לבניו בהלבשת בגד אחר לאהרן.","לאחר שעסקנו בבעיות צדדיות רבות, שבים אנו לפירוש המשנה. שנינו: \u0003\"מפרישין כהן גדול\u0004 מביתו ללשכת פרהדרין \u0003\"\u0004. ושואלים: \u0003למה מפרישין?\u0004 על שאלה זו תוהים: כיצד אפשר לשאול \u0003למה מפרישין?!\u0004 והרי הטעם הוא \u0003כדקאמרינן\u0004 \u0005[כפי\u0006 שכבר \u0005אמרנו];\u0006 \u0003אי\u0004 \u0005[אם]\u0006 לשיטת \u0003ר' יוחנן — כדאית ליה\u0004 \u0005[כמו\u0006 הטעם \u0005שיש לו]\u0006 שהוא נלמד מסדר המילואים, \u0003אי\u0004 \u0005[אם]\u0006 לשיטת \u0003ריש לקיש כדאית ליה\u0004 \u0005[כמו\u0006 הטעם \u0005שיש לו]\u0006 שהוא כפרישה בהר סיני. ואם כן מה מקום לשאלה זו עוד?","ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך היתה השאלה: \u0003מביתו\u0004 כלומר מאשתו \u0003למה פירש?\u0004 שהסברנו מדוע צריך הוא להיות מובדל במקום מיוחד, אולם מדוע לא תבוא אשתו עמו לשם? \u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה בן בתירה אומר: שמא תמצא אשתו ספק נדה ויבא עליה\u0004 ויטמא.","ותוהים: \u0003אטו ברשיעי עסקינן\u0004 \u0005[וכי ברשעים אנו עוסקים]\u0006 שכהן זה יודע שאשתו ספק נדה והוא בא עליה במזיד? \u0003אלא,\u0004 כך יש לתקן את הלשון: \u0003שמא יבא על אשתו ותמצא ספק נדה,\u0004 כי עשוי לקרות שאחר שיבוא עליה ימצא דם נדה על הסדין, וכיון שלא ברור אם פירסה נדה קודם הביאה או אחריה, הרי זו ספק נדה והבועלה טמא מספק.","מסופר: \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב חסדא\u0004 את ההשערה הבאה: \u0003כמאן\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 נאמרה הלכה זו — כשיטת \u0003ר' עקיבא,\u0004 ש\u0003אמר:\u0004 ספק \u0003נדה,\u0004 כלומר: אשה שנמצא דם על סדינה בתוך זמן מסויים (מעת לעת) לאחר הביאה — \u0003מטמאה את בועלה\u0004 למפרע מספק, שחוששים שמא כבר בשעת הביאה פירסה נדה. \u0003דאי רבנן\u0004 \u0005[שאם\u0006 כשיטת \u0005חכמים]\u0006 בענין זה \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמרי\u0004 [\u0005אמרו]\u0006 חכמים: \u0003אין\u0004 ספק \u0003נדה מטמאה את בועלה\u0004 למפרע, ולשיטה זו אם כן אין הכהן צריך לפרוש מאשתו כל אותם ימים!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא: אפילו תימרו רבנן\u0004 \u0005[תאמרו\u0006 שמשנתנו כשיטת \u0005חכמים\u0006 היא\u0005],\u0006 \u0003עד כאן לא\u0004 שמענו \u0003פליגי רבנן עליה\u0004 \u0005[\u0006ש\u0005נחלקו חכמים עליו]\u0006 על \u0003ר' עקיבא\u0004 שאין הנדה מטמאה למפרע \u0003אלא באחר אחר,\u0004 כלומר: שלא נמצא הדם מיד אחר הביאה, אלא שהתה זמן כדי שתרד ממטתה ותרחץ עצמה ואחר כך בדקה ומצאה, שמשום משך הזמן שעבר אמרו חכמים שאין הוכחה לקשר בין זמן הבעילה ובין זמן פריסת נדה, \u0003אבל בחד אחר\u0004 כלומר, אם מצאה מיד אחר הביאה — \u0003מודו ליה\u0004 \u0005[מודים לו]\u0006 חכמים לר' עקיבא, שמטמאה את בועלה למפרע.","\u0003אמר ר' זירא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מהלכה זו כי \u0003בועל נדה אינו כנדה\u0004 לענין זמן הטבילה, \u0003וטובל\u0004 אפילו \u0003ביום\u0004 השביעי לטומאתו, ואינו צריך להמתין עד הלילה לטבול אחר היום השביעי כמו הנדה עצמה. והכהן הגדול שיום השביעי לטומאתו בבעילת אשתו שהיתה ספק נדה חל בערב יום הכיפורים, טובל בו ביום ובהערב שמש הריהו טהור גמור ונכנס למקדש לעבודת יום הכיפורים.","וראיה לדבר: \u0003דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 ש\u0003בועל נדה כנדה\u0004 הוא, אם כן \u0003אימת טביל\u0004 \u0005[מתי הוא טובל]\u0006 לפי זה — \u0003בליליא\u0004 \u0005[בלילה]\u0006 שלאחר שבעת הימים, ולילה זה הריהו ליל יום הכיפורים! אם כן, \u0003למחר\u0004 ביום הכיפורים עצמו \u0003היכי עביד\u0004 \u0005[איך הוא\u0006 יכול \u0005לעשות]\u0006 \u0003עבודה\u0004 במקדש \u0003והא בעי\u0004 \u0005[הרי צריך]\u0006 הוא עדיין \u0003הערב שמש,\u0004 שלאחר יום טבילתו יספור יום נוסף, ורק לכשתעריב שמשו של יום זה יוצא הוא מגדר טבול יום ונטהר טהרה גמורה המתירתו לעבוד במקדש. \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 ש\u0003בועל נדה אינו כנדה,\u0004 וטבילתו בניגוד לנדה עצמה היא ביום השביעי עצמו, ומיד בהערב שמש ראוי הוא לעבודת המקדש.","\u0003רב שימי מנהרדעא אמר; אפילו תימא\u0004 \u0005[תאמר]\u0006 כי \u0003בועל נדה\u0004 דינו \u0003כנדה\u0004 לענין זמן הטבילה, אלא שאין מפרישים אותו מביתו בלילה כי אם \u0003דמפרשינן ליה\u0004 \u0005[שמפרישים אותו]\u0006 שמונה ימים לפני יום הכיפורים \u0003שעה אחת סמוך לשקיעת החמה,\u0004 קודם שמתחילים שבעת הימים ולכן יש מעתה אפשרות למנות שבעה ימים שלמים עד ערב יום הכיפורים. אכן אף שפרישתו ארוכה בשעה אחת על שבעה ימים, אין בשעה קצרה זו כדי להחשיבם כשמונה.","על שיטה זו שבועל נדה חייב לטבול בלילה \u0003מיתיבי\u0004 \u0005[מקשים],\u0006 שנינו: \u0003כל חייבי טבילות — טבילתן ביום,\u0004 חוץ מ\u0003נדה ויולדת\u0004 ש\u0003טבילתן בלילה.\u0004 ונדייק מכאן: \u0003נדה — אין\u0004 \u0005[כן]\u0006 טבילתה אכן בלילה, אולם \u0003בועל נדה לא!\u0004","ודוחים: מכאן אין ראיה, אפשר לומר: \u0003נדה וכל דאתי מרבוייא\u0004 \u0005[שבא מן הריבוי]\u0006 שהוא כיוצא בה, וכיון שנאמר שבועל נדה חלה עליו טומאתה, ממילא אף דינו לענין טבילה כמותה, ואין להוכיח מכאן.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד ממה ששנינו: \u0003בעל קרי\u0004 דינו \u0003כמגע\u0004 (כמי שנוגע) ב\u0003שרץ, בועל נדה\u0004 דינו \u0003כטמא מת.\u0004 ונברר: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 באה ברייתא זו ללמדנו לענין \u0003טבילה,\u0004 שבועל נדה דינו כטמא מת שטובל ביום! ודוחים: לא, הברייתא באה ללמדנו למשך זמן \u0003טומאתן,\u0004 שבעל קרי טמא יום אחד כנוגע בשרץ, ובועל נדה טמא שבעה ימים כטמא מת.","על כך תוהים: מה טעם ללמדנו \u0003טומאתן?!\u0004 הלא \u0003בהדיא כתיב בהו\u0004 \u0005[במישרין,\u0006 במפורש, \u0005כתוב בהן]\u0006 משך זמן טומאתם, \u0003האי\u0004 \u0005[זה]\u0006 טמא מת \u0003טומאת שבעה כתיב ביה, והאי\u0004 \u0005[וזה]\u0006 בועל נדה \u0003טומאת שבעה כתיב ביה\u0004 \u0005[כתובה בו]\u0006 במפורש ובודאי לא נצרכה הברייתא ללמדנו דבר המפורש בתורה,"],["\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 ההשוואה היא לזמן \u0003טבילתן,\u0004 ולמדנו שבועל נדה טובל ביום כטמא מת!","ודוחים: \u0003לא, לעולם\u0004 מדברת ברייתא זו \u0003לטומאתן,\u0004 ואכן בדברים שאמרנו אין כל חידוש, אלא \u0003סיפא אצטריכא ליה\u0004 \u0005[סופה\u0006 של הברייתא \u0005הוצרכה לו]\u0006 לומר ולחדש בה, ואגב סופה הקדים דברים אלה בתחילה, שנאמר בהמשך הברייתא: \u0003אלא שחמור ממנו בועל נדה\u0004 יותר מטמא מת, שבועל הנדה \u0003מטמא משכב ומושב\u0004 שישב או שכב עליהם (ואפילו היתה חציצה בינו ובינם) \u0003בטומאה קלה,\u0004 שהיא \u0003לטמא אוכלין ומשקין,\u0004 מה שאין כן טמא מת שאינו מטמא משכב ומושב.","ועוד מקשים: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 הוכחה אחרת, \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: הזב והזבה והמצורע והמצורעת ובועל נדה וטמא מת — טבילתן ביום, נדה ויולדת — טבילתן בלילה!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה\u0006 חמורה היא\u0005]\u0006 לדעת רב שימי שבועל נדה טובל בלילה, שהרי בברייתא נאמר במפורש להיפך, והושבו ונסתרו דבריו.","על פרישתו של הכהן הגדול שואלים: \u0003ועד שאתה מפרישו מטומאת ביתו\u0004 מפני החשש שמא תיטמא אשתו, \u0003הפרישהו מטומאת המת\u0004 שראוי לתקן שלא יבוא אדם לבקרו בלשכתו, שמא ימות אחד הנכנסים פתאום ויטמאנו! \u0003אמר רב תחליפא אבוה\u0004 \u0005[אביו]\u0006 של \u0003רב הונא בר תחליפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: זאת אומרת: טומאת המת — הותרה היא בציבור.\u0004 כלומר, מיוחדת היא טומאת המת, שאם כל הציבור כולו טמא — אין חוששים לטומאה זו, ומותר לעבוד במקדש כרגיל. וכיון שעבודת הכהן הגדול ביום הכיפורים עבודת קרבנות הציבור היא — אין אנו חוששים לטומאת המת, שהרי איננה פוסלת בציבור.","\u0003רבינא אמר: אפילו תימא\u0004 \u0005[אפילו תאמר]\u0006 כי \u0003טומאת המת דחויה היא בצבור\u0004 שלא הותרה היתר גמור, אלא התורה דחתה את איסור העבודה בטומאת מת מפני מצות הקרבת הקרבנות, אבל לכתחילה צריך להזהר הרבה בטהרה זו אף עבור כל הציבור. ואף על פי כן יש לומר כי לא הפרישוה את הכהן הגדול מחברת בני אדם בשבעה ימים הללו מפני ש\u0003טומאת המת לא שכיחא\u0004 \u0005[אינה מצוייה]\u0006 שהרי אין זה מצוי שאדם הבא לבקר ימות פתאום, אבל \u0003טומאת ביתו\u0004 (אשתו) \u0003שכיחא\u0004 \u0005[מצוייה]\u0006 שהרי בכל שעה יש לחשוש שמא תמצא אשתו ספק נדה.","כיון שהוזכרו חילוקי הדעות לענין טומאת המת בציבור מביאים כאן את המחלוקת היסודית בנושא זה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים ביחס לעבודת המקדש כשרוב הציבור טמא ב\u0003טומאת המת, רב נחמן אמר: הותרה היא בציבור\u0004 וכאשר רוב הציבור טמא — אין יתרון לעבודה בטהרה על פני עבודה בטומאה, לפי שלענין זה כאילו לא היתה כאן טומאה. \u0003ורב ששת אמר:\u0004 טומאת המת רק \u0003דחויה היא בציבור\u0004 ומשתדלים בכל האפשר שתהא העבודה בטהרה,","ומגבילים את המחלוקת: \u0003היכא דאיכא\u0004 \u0005[מקום שיש]\u0006 \u0003טמאין וטהורין בההוא\u0004 \u0005[באותו]\u0006 \u0003בית אב\u0004 של כהנים שהגיע תורו לעבוד בו ביום במקדש — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 גם רב נחמן, \u0005אינם חלוקים]\u0006 שה\u0003טהורין — עבדי\u0004 \u0005[עושים\u0006 עבודה\u0005],\u0006 ואילו ה\u0003טמאין — לא עבדי\u0004 \u0005[אינם עושים\u0006 עבודה\u0005],\u0006 שודאי עדיפה עבודה בטהרה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כאשר כל בית האב כולו טמא, והשאלה למעשה היא: האם \u0003לאהדורי ולאתויי\u0004 \u0005[לחזור ולהביא]\u0006 כהנים \u0003טהורין מבית אב אחרינא\u0004 \u0005[אחר]\u0006 מאותו משמר כהנים, שתורו לעבוד במקדש ביום אחר באותו שבוע, או לא;","ש\u0003רב נחמן אמר:\u0004 טומאת המת \u0003היתר היא בציבור, ולא מהדרינן\u0004 \u0005[ואין אנו מחזרים]\u0006 למצוא כהנים אחרים, שכיון שהתירה התורה לעבוד עבודת קרבנות הציבור בטומאת מת — הרי זה כהיתר גמור וכאילו נעשה הכל בטהרה. \u0003ורב ששת אמר: דחויה היא בציבור,\u0004 שרק מדוחק דוחים אנו את הטומאה, אולם כאשר אפשר לחזר \u0003מהדרינן\u0004 \u0005[מחזרים]\u0006 אנו ומוצאים כהנים כשרים.","\u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 שהמחלוקת היתה באופן אחר קצת: \u0003אפילו היכא דאיכא\u0004 \u0005[במקום שיש]\u0006 \u0003טהורין וטמאין בההוא\u0004 \u0005[באותו]\u0006 \u0003בית אב פליג\u0004 \u0005[חולק]\u0006 \u0003רב נחמן, ואמר: עבדי נמי\u0004 \u0005[עושים\u0006 עבודה \u0005גם כן]\u0006 ה\u0003טמאין\u0004"],["\u0003כל טומאת מת בציבור רחמנא שרייה\u0004 \u0005[התורה התירה]\u0006 אותה.","לאחר הגדרת השיטות, מגיעים לנימוקי הצדדים, \u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מנין אומר אני אותה]\u0006 את דעתי זו שטומאה דחויה היא בציבור — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה\u0004 הכהן \u0003עומד ומקריב מנחת העומר ונטמאת בידו, אומר\u0004 הכהן שנטמאה \u0003ומביאין\u0004 מנחה \u0003אחרת תחתיה. ואם אין שם אלא היא\u0004 שלא הכינו רק כדי מנחה אחת בצמצום, \u0003אומרין לו\u0004 הכהנים: \u0003הוי פקח ושתוק,\u0004 ואל תספר שנטמאה.","\u0003קתני מיהת\u0004 \u0005[שנינו מכל מקום]\u0006 \u0003אומר ומביאין אחרת תחתיה,\u0004 משמע שכאשר אפשר לעשות בטהרה — עושים, ואין אומרים שהותרה טומאה בציבור! על הוכחה זו \u0003אמר רב נחמן: מודינא היכא דאיכא\u0004 \u0005[מודה אני במקום שיש]\u0006 \u0003שיריים\u0004 של הקרבן שנותרו בטהרתם ועומדים \u0003לאכילה,\u0004 שהרי אף כשהותרה הקרבת הקרבן בטומאה, מכל מקום לכשנטמא הרי אסור לאוכלו בטומאתו, ומשנותר חלקו טהור וראוי לאכילה מודה אני שמן הראוי אף לעשותו בטהרה, כדי לקיים גם את מצות אכילת הקרבנות.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על רב נחמן ממה ששנינו: \u0003היה מקריב מנחת פרים ואילים וכבשים, ונטמאת\u0004 המנחה \u0003בידו, אומר\u0004 הוא לכהנים \u0003ומביאין\u0004 לו מנחה \u0003אחרת תחתיה. ואם אין שם אלא היא,\u0004 שלא הכינו מנחות אחרות, \u0003אומרין לו: הוי פקח ושתוק.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן ב\u0003פרים, אילים וכבשים\u0004 של ה\u0003חג\u0004 שהן קרבנות ציבור, ומנחות כאלו אינן נאכלות. הרי שאף בקרבן הציבור מהדרים שיהיה מלכתחילה בטהרה, ומכאן שלא הותרה טומאה בציבור אלא דחויה!","\u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב נחמן: לא\u0004 אין המדובר שם בקרבנות ציבור ממש, אלא: \u0003פרים\u0004 שנזכרו כוונתם ל\u0003פר עבודה זרה\u0004 שהוא קרבן שמביא הציבור אם עבדו עבודה זרה בשגגה. כי, \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 שקרבן ה\u0003ציבור הוא,\u0004 מכל מקום מ\u0003כיון\u0004 ש\u0003לא קביע ליה\u0004 \u0005[קבוע לו]\u0006 \u0003זמן\u0004 ותאריך קבוע להקרבתו — \u0003מהדרינן\u0004 \u0005[מחזרים]\u0006 אנו שייעשה בטהרה, שהרי קרבן זה מותר להקריבו גם לאחר זמן. וכשדובר ב\u0003אילים\u0004 מדובר לא בקרבנות מוספי הציבור אלא \u0003באילו של אהרן\u0004 שמקריב ביום הכיפורים, ש\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 \u0003דקביע ליה\u0004 \u0005[שקבוע לו]\u0006 \u0003זמן, כיון\u0004 שקרבנו של \u0003יחיד הוא,\u0004 של הכהן הגדול כפרט — \u0003מהדרינן\u0004 \u0005[מחזרים אנו]\u0006 שייעשה בטהרה, שלא הותרה טומאה מכל וכל אלא לגבי קרבן ציבור שקבוע לו זמן. ולענין ה\u0003כבשים\u0004 אין מדובר בכבשים של קרבנות התמיד והמוסף, אלא \u0003בכבש הבא עם העומר דאיכא\u0004 \u0005[שיש]\u0006 \u0003שיריים לאכילה\u0004 והיא מנחת העומר ששיירה נאכלים בטהרה, והרי כבר אמר רב נחמן שבמקרה כזה מחזרים שאף ההקרבה תהיה בטהרה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד על רב נחמן, שנינו: \u0003דם\u0004 קרבנות \u0003שנטמא וזרקו\u0004 על המזבח, אם זרקו \u0003בשוגג — הורצה\u0004 (נתקבל הקרבן) אם זרקו \u0003במזיד — לא הורצה.\u0004 הרי שלא הותרה טומאת ציבור במקדש לגמרי! ודוחים: \u0003כי תנא ההיא\u0004 \u0005[כאשר שנויה\u0006 הברייתא \u0005ההיא]\u0006 הרי היא בקרבן של \u0003יחיד,\u0004 שודאי בקרבן יחיד לא הותרה טומאה.","ומקשים עוד: \u0003תא שמע\u0004 \u0005[בוא ושמע]\u0006 ראיה אחרת, ממה ששנינו: \u0003על מה הציץ\u0004 של הכהן הגדול \u0003מרצה — על הדם ועל הבשר, ועל החלב, שנטמא\u0004 במקדש, \u0003בין\u0004 שנטמא \u0003בשוגג בין במזיד, בין באונס בין ברצון, בין ביחיד בין בציבור. ואי סלקא דעתך\u0004 \u0005[ואם עולה בדעתך]\u0006 לומר כי \u0003טומאה היתר היא בציבור — למה לי\u0004 אם כן \u0003לרצויי\u0004 \u0005[שיהיה\u0006 הציץ \u0005מרצה],\u0006 שהרי אם הותרה הטומאה לגמרי, מה צורך יש בריצוי הציץ?","ומשיבים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב נחמן: כי קתני\u0004 \u0005[כאשר שנינו]\u0006 כי \u0003\"הציץ מרצה\"\u0004 אין הדבר שייך לכל הפרטים שנזכרו אלא כוונתו \u0003אדיחיד\u0004 \u0005[על\u0006 קרבן \u0005היחיד]\u0006 שהציץ מרצה אם הובא בטומאה, ולא לענין טומאת הציבור נאמרה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותרץ כך: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהציץ מרצה על קרבן\u0005]\u0006 ה\u0003ציבור,\u0004 אלא שמדובר שם \u0003בהנך\u0004 \u0005[באלה\u0006 מן הקרבנות\u0005]\u0006 ש\u0003לא קביע\u0004 \u0005[קבוע]\u0006 \u0003להן זמן,\u0004 והרי אף רב נחמן מודה שקרבן ציבור שאין זמנו קבוע, לא הותרה טומאתו בציבור ועדיין צריך ריצוי ציץ.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 נאמר: \u0003\"ונשא אהרן את עון הקדשים\u0004 אשר יקדישו בני ישראל לכל מתנות קדשיהם והיה על מצחו תמיד לרצון להם לפני ה'\u0003\"\u0004 (שמות כח, לח) ואמרו חכמים בברייתא: \u0003וכי איזה עו‍ן הוא\u0004 הציץ \u0003נושא? אם\u0004 תאמר \u0003עון פיגול\u0004 שהוא קרבן שחשב הכהן להקריבו שלא בזמנו — \u0003הרי כבר נאמר\u0004 בו: \u0003\"לא ירצה\u0004 המקריב אותו לא יחשב לו פיגול יהיה\u0003\"\u0004 (ויקרא ז, יח) משמע שאין עליו ריצוי. \u0003ואם עון נותר\u0004 שהותירו מן הקרבן לאחר זמן הראוי לו — \u0003הרי כבר נאמר\u0004 בו \u0003\"לא יחשב\u0004 לו\u0003\"\u0004 (ויקרא ז, יח)"],["\u0003הא\u0004 \u0005[הרי]\u0006 \u0003אינו נושא\u0004 ומכפר \u0003אלא עון טומאה שהותרה מכללה בציבור. וקשיא\u0004 \u0005[וקשה]\u0006 הלשון \u0003לרב ששת,\u0004 שהרי בברייתא זו נאמר במפורש שהטומאה הותרה בציבור! ומשיבים: לדעת רב ששת \u0003תנאי היא\u0004 \u0005[\u0006מחלוקת \u0005תנאים היא]\u0006 אם הותרה הטומאה בציבור או נדחתה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ציץ של כהן גדול, בין שישנו על מצחו\u0004 של הכהן הגדול בשעה שנטמא הקרבן, \u0003בין שאינו על מצחו\u0004 הרי הוא \u0003מרצה,\u0004 אלו \u0003דברי ר' שמעון.\u0004","\u0003ר' יהודה אומר:\u0004 אם \u0003עודהו על מצחו — מרצה, אין עודהו על מצחו — אינו מרצה. אמר לו ר' שמעון\u0004 לר' יהודה: \u0003כהן גדול ביום הכפורים יוכיח, שאין עודהו על מצחו,\u0004 שבעבודות המיוחדות ליום הכיפורים לובש הכהן הגדול רק ארבעה בגדי לבן ככהן הדיוט, ומסיר מעליו את הציץ ושאר בגדי הזהב, ובכל זאת \u0003מרצה\u0004 על הטומאה!","\u0003אמר לו ר' יהודה: הנח\u0004 לו \u0003לכהן גדול ביום הכפורים\u0004 שאין צורך בריצוי הציץ, לפי \u0003שטומאה הותרה לו בציבור.\u0004 ומדיוק הדברים נוכיח, שכיון שר' יהודה אומר שטומאה הותרה בציבור (ולכן אין צורך בציץ המרצה) \u0003מכלל\u0004 ש\u0003ר' שמעון סבר\u0004 ש\u0003טומאה דחויה היא בציבור\u0004 ולשיטתו נחוץ הציץ לכפרה. נמצא שמחלוקת זו בין רב ששת ורב נחמן מחלוקת תנאים היא, וברייתא זו כשיטת ר' יהודה נשנתה.","כיון שהוזכרה מחלוקת זו מסבירים ומבארים אותה: \u0003אמר אביי:\u0004 כאשר \u0003נשבר הציץ דכולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 גם ר' שמעון, \u0005אינם חלוקים]\u0006 \u0003דלא\u0004 \u0005[שאינו]\u0006 \u0003מרצה\u0004 עוד. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 \u0003—\u0004 כשאינו על מצחו אלא \u0003דתלי בסיכתא\u0004 \u0005[תלוי על יתד,\u0006 קולב\u0005],\u0006 ש\u0003ר' יהודה סבר:\u0004 כיון שנאמר \u0003\"\u0004והיה \u0003על מצח\u0004 אהרן \u0003ונשא\u0004 אהרן את עון הקדשים\u0003\"\u0004 (שמות כח, לח) כוונתו: כל עוד שהציץ על מצחו נושא הוא עון.","\u0003ור' שמעון סבר\u0004 שיש להדגיש את חלקו האחרון של הכתוב \u0003\"\u0004והיה על מצחו \u0003תמיד לרצון\u0004 להם \u0003לפני ה'\"\u0004 (שמות כח, לח), ללמד שתמיד הציץ מרצה, אף בשעה שאינו על מצחו. כי \u0003מאי\u0004 \u0005[מהו,\u0006 מאי משמעות\u0005]\u0006 המילה \u0003\"תמיד\"\u0004 שנאמרה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שפירושה: \u0003תמיד על מצחו,\u0004 שהציץ חייב להימצא לעולם על מצחו של הכהן הגדול, \u0003מי משכחת לה\u0004 \u0005[האם מוצא אתה אותה]\u0006 במציאות שיוכל להיות הדבר כן?! שכן \u0003מי לא בעי מיעל\u0004 \u0005[האם אינו צריך ליכנס]\u0006 \u0003לבית הכסא\u0004 ואז חייב להסיר מעליו את הציץ משום שבציץ חקוק שם ה'. וכן \u0003מי לא בעי מינם\u0004 \u0005[האם איננו צריך לישון]\u0006 וכשהוא ישן פושט הרי את בגדיו. \u0003אלא\u0004 ודאי יש להבין: \u0003תמיד מרצה הוא,\u0004 בין שהוא על מצחו ובין שאינו על מצחו.","ושואלים: \u0003ולר' יהודה נמי, הכתיב\u0004 \u0005[גם כן, הרי נאמר]\u0006 \u0003\"תמיד\",\u0004 וברור שאי אפשר לפרשו שיהא תמיד על מצחו! ומתרצים: \u0003ההוא \"תמיד\"\u0004 \u0005[\"תמיד\" זה\u0006 שנאמר\u0005]\u0006 כוונתו שכל עוד הציץ על מצחו \u0003לא יסיח דעתו ממנו.\u0004 וכדברי \u0003רבה בר רב הונא.\u0004 ש\u0003אמר רבה בר רב הונא: חייב אדם למשמש בתפיליו בכל שעה ושעה\u0004 שהם נתונים בראשו וזרועו, כדי להזכר בהם, \u0003קל וחומר מציץ:\u0004"],["\u0003ומה ציץ שאין בו אלא אזכרה אחת\u0004 של שם ה' \u0003אמרה תורה \"על מצחו תמיד\"\u0004 ללמד \u0003שלא יסיח דעתו ממנו, תפילין שיש בהן אזכרות הרבה\u0004 בארבע פרשיות שבהם \u0003על אחת כמה וכמה\u0004 שחייב לזכור אותן, ולא להסיח דעתו מהן.","ושואלים: ולשיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שהכתוב בא ללמד ש\u0003תמיד מרצה\u0004 הציץ אף כשאינו על מצח הכהן, \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 גם כן \u0003\"על מצחו ונשא\"!\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו\u0006 כתוב\u0005]\u0006 \u0003לקבוע לו מקום הוא דאתא\u0004 \u0005[שבא],\u0006 שממילים אלה למדים היכן מניח הכהן הגדול את הציץ, אבל לא שהציץ חייב להיות שם תמיד.","ושואלים: \u0003ור' יהודה,\u0004 דין זה של \u0003לקבוע לו מקום מנא ליה\u0004 \u0005[מנין לו]?\u0006 ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 לומד הוא\u0005]\u0006 דבר זה ממה שכתוב \u0003\"על מצחו\" —\u0004 ללמד שהציץ יהיה מצוי על מצחו. ושואלים: אם כן, \u0003לר' שמעון נמי\u0004 \u0005[גם כן]\u0006 \u0003תיפוק ליה\u0004 \u0005[תצא לו,\u0006 ילמד\u0005]\u0006 הלכה זו ממה שנאמר \u0003\"על מצחו\"!\u0004 ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן\u0006 הוא \u0005גם כן]\u0006 ומכאן הוא למד.","ושואלים: \u0003אלא\u0004 אם כן, \u0003\"על מצחו ונשא\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו],\u0006 מה הוא למד מחזרה זו? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה ר' שמעון \u0005לומר]\u0006 \u0003לך\u0004 בביאור הכתוב: אם הציץ שלם ו\u0003ראוי למצח — מרצה, שאינו ראוי למצח — אינו מרצה, לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003נשבר הציץ דלא\u0004 \u0005[שאינו]\u0006 \u0003מרצה.\u0004","ושואלים: \u0003ולר' יהודה, נשבר הציץ מנא ליה\u0004 \u0005[מנין לך]\u0006 שאינו מרצה? ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו,\u0006 נלמד\u0005]\u0006 הדבר מפני שלא נאמר \u0003\"מצח\"\u0004 אלא \u0003\"מצחו\"\u0004 וזו לדעתו הדגשה הבאה ללמד: דבר הראוי להיות על מצחו שלו. \u0003ור' שמעון:\u0004 לימוד זה מן הדיוק \u0003\"מצח\" \"מצחו\" — לא משמע ליה\u0004 \u0005[אינו נשמע לו,\u0006 אינו נראה לו\u0005],\u0006 שלדעתו אין כל הבדל משמעות לענין זה בין \"מצח\" ו\"מצחו\".","ומציעים: \u0003נימא\u0004 \u0005[\u0006האם \u0005נאמר]\u0006 \u0003הני תנאי\u0004 \u0005[תנאים אלה]\u0006 ר' יהודה ור' שמעון שנחלקו לענין טומאה בציבור \u0003כהני תנאי\u0004 \u0005[כתנאים אלה]\u0006 אחרים, שאף הם נחלקו באותה בעיה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אחד זה\u0004 הכהן הגדול לפני יום הכיפורים \u0003ואחד זה\u0004 הכהן העוסק בשריפת הפרה האדומה \u0003מזין עליו כל שבעה\u0004 ימים של פרישה \u0003מכל\u0004 מי \u0003חטאות\u0004 של אפר הפרות האדומות \u0003שהיו שם\u0004 במקדש למשמרת, שמא נטמא בטומאת מת באחד הימים לפני פרישתו, וכיון שאין יודעים מתי הוא יום שלישי ושביעי שלו — מזים בכל יום. אלו \u0003דברי ר' מאיר, ר' יוסי אומר: אין מזין עליו,\u0004 שבעה ימים, \u0003אלא\u0004 ביום ה\u0003שלישי\u0004 וביום ה\u0003שביעי בלבד\u0004 שהרי אם יש לחשוש לטומאתו — די בהזאה זו בלבד כדי לטהרו. ואילו \u0003ר' חנינא סגן הכהנים\u0004 מחלק ו\u0003אומר: כהן השורף את הפרה מזין עליו כל שבעה\u0004 ימים, ואלו \u0003כהן גדול ביום הכפורים אין מזין עליו אלא שלישי ושביעי.\u0004","ומדייקים: \u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא\u0006 בנושא \u0005זה הם חלוקים],\u0006 כי \u0003ר' מאיר סבר: טומאה\u0004 של מת רק \u0003דחויה\u0004 היא \u0003בציבור,\u0004 ולכן מזים אנו עליו כל שבעה ימים, כדי לטהרו טהרה גמורה, ולצאת מידי כל ספק טומאה. ואילו \u0003ר' יוסי סבר: טומאה היתר\u0004 גמור \u0003היא בציבור,\u0004 ולכן אין צורך להקפיד כל כך בהזאה.","על הצעת הסבר זו תוהים: \u0003ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 שאפשר להבין כך? שכן \u0003אי\u0004 \u0005[אם]\u0006 \u0003סבר ר' יוסי\u0004 כי טומאת מת \u0003היתר\u0004 גמור \u0003היא בציבור\u0004 — אם כן \u0003הזאה כלל למה לי?\u0004 שהרי כיון שהותרה, הרי זה כאילו הוקרב בטהרה. \u0003אלא\u0004 עלינו לחזור בנו מהסבר זה ולומר \u0003דכולי עלמא הני תנאי סברי\u0004 \u0005[לדעת הכל, תנאים אלה סבורים]\u0006 כי \u0003טומאת\u0004 המת רק \u0003דחויה היא בציבור,\u0004 ועל כן צריך להזות עליו.","ואלא \u0003הכא בהא קמיפלגי\u0004 \u0005[כאן\u0006 בנושא \u0005זה נחלקו],\u0006 \u0003ר' מאיר סבר: אמרינן טבילה בזמנה מצוה\u0004 שאף כי הטמא, משעה שהותר לטבול, הריהו נטהר מטומאתו בכל זמן שיטבול אף אם איחר טבילתו, מכל מקום מצוה היא שיטבול מיד כשיגיע זמן טהרתו. וכשם שטבילה בזמנה מצוה כך הזאה בזמנה מצוה, וכיון שיש חשש שמא נטמא הכהן הגדול בשלושת הימים שלפני פרישתו, יש להזות עליו בכל יום, למן היום הראשון, שמא הוא שלישי לטומאתו. ואילו \u0003ר' יוסי סבר: לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 כי \u0003טבילה בזמנה מצוה\u0004 היא וכן אין הזאה בזמנה מצוה, ולכן אין להזות עליו אלא ביום השלישי וביום השביעי, והרי הוא נטהר בכך אף שאולי אינו יום שלישי ושביעי לטומאתו.","על הסבר זה מקשים: וכי \u0003סבר ר' יוסי\u0004 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 \u0003טבילה בזמנה מצוה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה שם\u0004 משמות ה' האסורים במחיקה \u0003כתוב\u0004 בדיו \u0003על בשרו\u0004 של אדם — \u0003הרי זה לא ירחץ\u0004 את גופו במים \u0003ולא יסוך\u0004 את גופו בשמן, שמא ימחק, \u0003ולא יעמוד במקום הטנופת,\u0004 שאסור לבזות את השם. \u0003נזדמנה לו טבילה של מצוה\u0004 וחייב לטבול \u0003כורך עליו\u0004 על מקום השם \u0003גמי\u0004 (מין עשב) שיכסה את השם אבל יניח למי הטבילה לחדור בלי חציצה \u0003וטובל. ר' יוסי אומר: יורד וטובל כדרכו\u0004 ואינו צריך להקפיד על כריכת הגמי \u0003ובלבד שלא ישפשף\u0004 את המקום וימחקנו בידים.","\u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 כי בשאלה אם \u0003טבילה בזמנה מצוה קא מיפלגי\u0004 \u0005[חולקים הם],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 כי \u0003לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 ש\u0003טבילה בזמנה מצוה,\u0004 ולכן צריך להמתין עד שיהא לו גמי לכרוך. אף אם ימנע על ידי כך מטבילה בזמנה. \u0003ור' יוסי סבר: אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003טבילה בזמנה מצוה,\u0004 ולכך אינו צריך להמתין עד שיהא לו גמי אלא יורד וטובל מיד. ואם כן אין לומר שמחלוקת ר' מאיר ור' יוסי היתה לענין טבילה בזמנה. \u0003אלא\u0004 יש להסביר כך: \u0003דכולי עלמא להני תנאי אמרינן\u0004 \u0005[לדעת הכל\u0006 לשיטת \u0005תנאים אלה אומרים]\u0006 אנו \u0003טבילה בזמנה מצוה.\u0004 ואם כן במה נחלקו?","\u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן ב\u0006ענין \u0005זה הם חלוקים]\u0006 ש\u0003ר' מאיר סבר: מקשינן\u0004 \u0005[מקישים,\u0006 משווים, \u0005אנו]\u0006 דין \u0003הזאה\u0004 לדין \u0003טבילה,\u0004 לומר שכשם שטבילה בזמנה מצוה — אף הזאה בזמנה מצוה. \u0003ור' יוסי סבר: לא מקשינן\u0004 \u0005[אין אנו משווים]\u0006 \u0003הזאה לטבילה,\u0004 שאף שטבילה בזמנה מצוה — אין הזאה בזמנה מצוה.","ושואלים: \u0003ור' חנינא סגן הכהנים\u0004 המחלק בין יום הכיפורים ופרה אדומה מה דעתו בענין זה? \u0003אי מקיש\u0004 \u0005[אם\u0006 הוא \u0005משווה]\u0006 \u0003הזאה לטבילה,\u0004 אם כן \u0003אפילו כהן גדול ביום הכפורים נמי\u0004 \u0005[גם כן]\u0006 יצטרך להזות בכל יום משבעת הימים, ו\u0003אי לא מקיש\u0004 \u0005[אם אינו משווה]\u0006 \u0003הזאה לטבילה\u0004 — אם כן \u0003אפילו כהן השורף את הפרה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא!\u0004 ומדוע איפוא הוא מבדיל ביניהם?","ומשיבים: \u0003לעולם\u0004 תפרש כי \u0003לא מקיש\u0004 \u0005[אינו משווה]\u0006 ובעצם אף על כהן השורף את הפרה לא היה צריך להזות כל שבעה, אלא ש\u0003כהן השורף את הפרה מעלה בעלמא\u0004 \u0005[בלבד]\u0006 היא שעשו בו, כשם שהוסיפו חכמים הרבה מאד מעלות ודקדוקים נוספים בדין הכהן השורף את הפרה, ולא מעיקר ההלכה, אלא כדי להדגיש את צד הטהרה שבדבר.","ושואלים: \u0003כמאן אזלא\u0004 \u0005[\u0006כשיטת \u0005מי הולכת]\u0006 \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003אין\u0004 הבדל \u0003בין כהן השורף את הפרה לכהן גדול ביום הכפורים אלא\u0004"],["\u0003שזה\u0004 הכהן הגדול הפורש לפני יום הכיפורים \u0003פרישתו לקדושה\u0004 כדי שלא יקל ראשו וליבו ותבוא עליו אימה ויכין עצמו לפני כניסתו אל הקודש ולכן \u0003אחיו הכהנים נוגעין בו\u0004 שהרי לא מחשש טומאה מפרישים אותו, \u0003וזה\u0004 השורף את הפרה \u0003פרישתו לטהרה, ואין אחיו הכהנים נוגעין בו. כמאן\u0004 \u0005[\u0006כשיטת \u0005מי]\u0006 היא הברייתא הזאת — \u0003או\u0004 כשיטת \u0003ר' מאיר או\u0004 כשיטת \u0003ר' יוסי. דאי\u0004 \u0005[שאם]\u0006 תאמר שהיא כדעת \u0003ר' חנינא סגן הכהנים — הא איכא נמי הא\u0004 \u0005[הרי יש גם כן זה]\u0006 שהכהן השורף את הפרה מזים עליו כל שבעה, וכהן ביום הכיפורים רק בשלישי ושביעי.","על השיטה שמזים על הכהן כל שבעת הימים, שמא יום זה יום שלישי או יום שביעי לטומאה \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003ר' יוסי ברבי חנינא: בשלמא\u0004 \u0005[נניח]\u0006 שמזים עליו ביום \u0003ראשון — שמא שלישי\u0004 הוא לטומאתו, ביום \u0003שני\u0004 מזים עליו \u0003— שמא שלישי\u0004 הוא לטומאתו שנטמא יום לפני פרישתו. וכן ביום ה\u0003שלישי — שמא שלישי\u0004 הוא לטומאה. יום \u0003חמישי — שמא שביעי\u0004 הוא, שנטמא יומיים לפני פרישתו. יום \u0003ששי — שמא שביעי\u0004 לטומאה הוא, אם נטמא יום לפני פרישתו, וכן ביום ה\u0003שביעי\u0004 מזים עליו — \u0003שמא שביעי\u0004 לטומאה הוא,","\u0003אלא\u0004 ביום \u0003הרביעי\u0004 לפרישתו \u0003למה לי הזאה כלל? לא\u0004 בחשש שהוא היום ה\u0003שלישי איכא לספוקי\u0004 \u0005[יש להסתפק],\u0006 שהרי לפני שלושה ימים כבר פרש לטהרה \u0003ולא\u0004 שמא זהו היום ה\u0003שביעי איכא לספוקי\u0004 \u0005[יש להסתפק],\u0006 שגם אם יום זה הוא השביעי לטומאתו אין בדבר תועלת שהרי לא היזו עליו ביום השלישי לטומאה זו, ואם כן אין טעם להזות בשביעי, שאין הזאת שביעי בלא הזאת שלישי, ואם כן מה טעם ההזאה ביום הרביעי?","ותוהים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה סבור שממש בכל יום מזים עליו, \u0003הזאה כל שבעה מי איכא\u0004 \u0005[האם ישנה],\u0006 האפשר שיזו עליו כל שבעה ימים? \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003הזאה שבות\u0004 היא, שתיקנו חכמים שמירה יתירה לשבת, ואסרו כמה דברים, והזאה בכלל זה \u0003ואינה דוחה את השבת,\u0004 ואם כן, בשבת על כרחך הרי אין מזים! \u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 שכאשר אמרו שמזים \u0003שבעה\u0004 ימים אינו מדוייק, ולמעשה הריהו \u0003לבר\u0004 \u0005[חוץ\u0006 מיום\u0005]\u0006 ה\u0003שבת,\u0004 ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לפרש שמזים עליו שבעה ימים — \u0003לבר\u0004 \u0005[חוץ]\u0006 מן היום ה\u0003רביעי\u0004 לפרישה, שאז אין צורך להזות עליו.","\u0003אמר רבא: הלכך\u0004 \u0005[משום כך]\u0006 \u0003כהן גדול ביום הכפורים, דלא בדידן תליא מילתא אלא בקביעא דירחא תליא מילתא\u0004 \u0005[שלא בנו תלוי הדבר אלא בקביעות החודש תלוי הדבר]\u0006 באיזה יום מימי השבוע יחל בפרישתו שהרי \u0003בתלתא\u0004 \u0005[בשלושה]\u0006 \u0003בתשרי בעי לאפרושי\u0004 \u0005[צריך להפריש אותו]\u0006 \u0003וכל אימת\u0004 בימי השבוע \u0003דמתרמי תלתא\u0004 \u0005[שמזדמן שלושה]\u0006 \u0003בתשרי מפרשינן ליה\u0004 \u0005[מפרישים אנו אותו],\u0006 אף שיתכן שתתבטל בשל כך הזאתו פעמיים, ביום השבת וכן ביום הרביעי להפרשתו כאמור. \u0003אבל כהן השורף את הפרה, דבדידן תליא מילתא\u0004 \u0005[שבנו תלוי הדבר]\u0006 באיזה יום נפריש אותו \u0003מפרשינן ליה\u0004 \u0005[מפרישים אנו אותו]\u0006 ביום \u0003רביעי בשבת כי היכי דניתרמי\u0004 \u0005[כדי שיזדמן]\u0006 \u0003רביעי שלו בשבת,\u0004 כי ביום הרביעי לפרישה אין צורך להזות, ובשבת אסור להזות, ונמצא שבשאר הימים שבהם יש טעם להזות יוכלו להזות בכולם.","אחרי הדיון בגמרא בענין מצות הפרישה, שבים לביאור המשנה. שנינו שם שמביאין את הכהן הגדול \u0003ללשכת פרהדרין. תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 אמר \u0003ר' יהודה וכי לשכת פרהדרין\u0004 (לשכת פקידי המלך הממונים לשנה) \u0003היתה? והלא לשכת בלווטי\u0004 לשכת השרים וראשי המועצה \u0003היתה\u0004 קרויה!","\u0003אלא, בתחלה\u0004 בזמן כהונת שמעון הצדיק וחביריו שבשל צידקותם האריכו ימים בכהונתם \u0003היו קורין אותה לשכת בלווטי\u0004 (הגדולים), לפי שהיתה מקומו הקבוע של הכהן הגדול. \u0003ומתוך\u0004 שבמשך הדורות היו זמנים שהיו אנשים שאינם ראויים \u0003נותנין\u0004 למחזיק בשלטון \u0003עליו\u0004 על הרצון לזכות בכהונה הגדולה אף שלא לפי מעלתם \u0003ממון\u0004 רב כדי לקבל מינוי זה של \u0003כהונה\u0004 גדולה וכך היו אכן מתמנים, ומתוך שהיו רשעים ולא הוציאו שנתם לכך היו \u0003מחליפין אותה\u0004 את הכהונה הגדולה \u0003כל שנים עשר חודש\u0004 וממנים לתפקיד זה בכל שנה איש אחר \u0003כפרהדרין הללו\u0004 (כמו פקידים אלה) \u0003שמחליפין אותם כל שנים עשר חודש, לפיכך היו קורין אותה\u0004 בזלזול \u0003לשכת פרהדרין\u0004 שאף היא בשל חילופי הכהנים היתה מתחלפת בכל שנה לפי שכל אחד היה הורס את לישכת קודמו ובונה לו מפוארת ממנה.","כיון שהוזכר ענין הפרהדרין, מביאים הלכה אחרת שבה נזכרו פקידים אלה. \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת דמאי: \u0003הנחתומין\u0004 אופי הלחם לרבים — \u0003לא חייבו אותן חכמים להפריש\u0004 מן הדמאי (תבואה שנקנתה מעם הארץ וספק אם הופרשו ממנה כל מתנות הלוים והכהנים) \u0003אלא תרומת מעשר\u0004 אחד ממאה מן התבואה, שהיה ניתן לכהנים וכן \u0003חלה\u0004 שמפרישים תמיד מן העיסה.","ושאלו: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003תרומה גדולה\u0004 הניתנת לכהן, (ששיעורה אחד מחמישים בערך) \u0003לא\u0004 חייבו אותם להפריש, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"],["\u0003לפי ששלח\u0004 יוחנן כהן גדול שגזר על הדמאי \u0003בכל גבולי ישראל\u0004 לבדוק מה מצב הדברים, \u0003וראה שאין\u0004 העם \u0003מפרישין אלא תרומה גדולה בלבד\u0004 ולא היו מפרישים מעשרות, ולכן גזר שהקונה מעם הארץ יחשוש שמא אכן לא הופרשו המעשרות ויפריש במקומו. ומתוך שהיו העם מפרישים תרומה גדולה, משום כך אין הנחתום צריד לחשוש ולחזור ולהפרישה.","\u0003מעשר ראשון ומעשר עני נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 יתנו הנחתומים, וטעם הדבר כי \u0003המוציא מחבירו עליו הראיה,\u0004 ומעשר ראשון הניתן ללוים ומעשר עני הניתן לעניים אין בהם קדושה, אלא מתנה היא להם, והיא חולין, וכיון שהדמאי היא רק ספק, הרי אם רוצה הלוי (או העני) לקבל את המעשר מן הדמאי — חייב הוא להוכיח שאכן לא הופרשו ממנו מעשרות קודם לכן. \u0003אלא מעשר שני\u0004 שחובה להעלותו לירושלים והוא רכוש הבעלים, \u0003נפרשו ונסקו\u0004 \u0005[שיפרישו ויעלוהו]\u0006 \u0003וניכלוהו\u0004 \u0005[ויאכלוהו]\u0006 \u0003בירושלים\u0004 כדרך שעושים אף בדמאי, ומדוע לא חייבו גם את הנחתומים לעשות כן?","\u0003אמר עולא: מתוך שפרהדרין\u0004 (שפקידי המלכות) \u0003הללו חובטין אותן\u0004 את הנחתומין \u0003כל שנים עשר חודש\u0004 של תקופת מינויים, \u0003ואומרים להם: מכרו בזול! מכרו בזול!\u0004 שהם מקפידים עליהם שלא יעלו את המחירים, \u0003לא אטרחונהו רבנן\u0004 \u0005[הטריחום חכמים]\u0006 מפני הספק בלבד להפריש כמות כה גדולה ולהעלותה לירושלים, שהרי הדבר כרוך בהוצאה ובטירחה גדולה שאין הם יכולים לעמוד בה, לפי שאינם יכולים להעלות את המחירים בהתאם להוצאותיהם וטרחתם, מפני אותם פקידים, ולכך סמכו על כך שמן הסתם כבר הופרש מהם מעשר שני. ושם הסברנו: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003פרהדרין?\u0004 — אלה הם \u0003פורסי\u0004 \u0005[פקידי המלכות הממונים לצרכים שונים].\u0006","אגב הדברים שאמרנו שבימי הבית השני היו הכהנים הגדולים מתחלפים בתדירות רבה, מביאים מה ש\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"יראת ה' תוסיף ימים ושנות רשעים תקצרנה\"\u0004 (משלי י, כז), \u0003\"יראת ה' תוסיף ימים\" — זה\u0004 מה שאמרנו ב\u0003מקדש ראשון שעמד ארבע מאות ועשר שנים. ולא שמשו בו אלא שמונה עשר כהנים גדולים\u0004 כפי שאפשר ללמוד מרשימת היוחסין במקרא,","\u0003\"ושנות רשעים תקצרנה\" — זה מקדש שני, שעמד ארבע מאות ועשרים שנה ושמשו בו יותר משלש מאות כהנים.\u0004 ועוד, אם נבדוק במספרים אלה \u0003צא מהם\u0004 \u0005[הוצא מהם]\u0006 משנים אלה \u0003ארבעים שנה ששמש שמעון הצדיק, ושמונים ששמש יוחנן כהן גדול, עשר\u0004 שנים \u0003ששמש ישמעאל בן פאבי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003אחת עשרה\u0004 שנה \u0003ששמש ר' אלעזר בן חרסום\u0004 שהיו צדיקים והאריכו ימים בכהונתם, \u0003מכאן ואילך צא וחשוב,\u0004 ותמצא לפי חישוב זה: \u0003כל אחד ואחד\u0004 משאר הכהנים \u0003לא הוציא שנתו\u0004 שהרי מספר הכהנים הגדולים גדול ממנין השנים ששימשו בהן.","מתוך שהוזכרו חטאות הכהנים בבית שני, מביאים מה ש\u0003אמר ר' יוחנן בן תורתא: מפני מה חרבה שילה — מפני שהיו בה שני דברים: גלוי עריות, ובזיון\u0004 ה\u0003קדשים. גלוי עריות — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועלי זקן מאד ושמע את כל אשר יעשון בניו לכל ישראל ואת אשר ישכבן את הנשים הצבאות פתח אהל מועד\"\u0004 (שמואל א', ב, כב). \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן: כל האומר בני עלי חטאו\u0004 בגילוי עריות ממש \u0003אינו אלא טועה,\u0004 אולם מכל מקום אף להסבר האחר שניתן לכתוב כי \u0003מתוך\u0004"],["\u0003ששהו את קיניהן\u0004 שהיו בעלי גאווה ולכך התרשלו ושהו מלהקריב את קיני בני היונה או התורים שמביאות היולדות למשכן כדי להיטהר מטומאתן, וכל אותו הזמן לא היו יכולות אותן נשים לחזור לבתיהן והיו חייבות להשאר ליד המשכן ובשל כך נמנעו מפריה ורביה, \u0003מיהא\u0004 \u0005[בכל אופן]\u0006 \u0003מעלה עליהן הכתוב כאילו שכבום,\u0004 שגם אם לא עברו בגילוי עריות ממש, מכל מקום הכתוב מחשיב כך את חטאם.","ב\u0003בזיון קדשים\u0004 חטאו, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"גם בטרם יקטרון את החלב ובא נער הכהן ואמר לאיש הזבח תנה בשר לצלות לכהן ולא יקח ממך בשר מבשל כי אם חי. ויאמר אליו האיש קטר יקטרון כיום החלב וקח לך כאשר תאוה נפשך ואמר לו כי עתה תתן ואם לא לקחתי בחזקה. ותהי חטאת הנערים גדולה מאד את פני ה' כי נאצו האנשים את מנחת ה'\"\u0004 (שמואל א' ב, טו-יז).","כהמשך לאמור מוסיפה התוספתא בענין חטאי ישראל לדורותיהם. \u0003מקדש ראשון מפני מה חרב — מפני שלשה דברים שהיו בו: עבודה זרה, וגלוי עריות, ושפיכות דמים. עבודה זרה — דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"כי קצר המצע מהשתרע\u0004 והמסכה צרה כהתכנס\u0003\"\u0004 (ישעיה כח, כ).","\u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קצר המצע מהשתרע\"? אמר ר' יונתן: קצר\u0004 (צר) \u0003מצע זה מהשתרר עליו שני רעים כאחד\u0004 (פירוש: השתרע — השתרר רע) שאי אפשר שיהיו במקדש גם עבודת ה' וגם פסל עבודה זרה שהעמיד מנשה בהיכל.","מהו \u0003\"והמסכה צרה כהתכנס\"\u0004 (ישעיה כח, כ) \u0003אמר ר' שמואל בר נחמני: כי מטי\u0004 \u0005[כאשר\u0006 היה \u0005מגיע]\u0006 \u0003ר' יונתן להאי קרא בכי\u0004 \u0005[למקרא זה היה בוכה],\u0006 \u0003אמר: מאן דכתיב ביה\u0004 \u0005[מי שנאמר בו]\u0006 \u0003\"כנס כנד מי הים\"\u0004 (תהלים לג, ז) \u0003נעשית לו מסכה\u0004 צרה? שהוא דורש את הכתוב \"והמסכה\" (הוא הפסל) נעשה צרה (יריב, כמו אשה צרה), \"כהתכנס\" כמו ה' שיכול לכנוס את מי הים.","\u0003גלוי עריות\u0004 היה שם, שנאמר: \u0003\"ויאמר ה' יען כי גבהו בנות ציון ותלכנה נטויות גרון ומשקרות עינים הלוך וטפוף תלכנה וברגליהן תעכסנה\"\u0004 (ישעיה ג, טז), ומפרש: \u0003\"יען כי גבהו בנות ציון\"\u0004 שהיו מבליטות ומדגישות את גובהן, בכך \u0003שהיו מהלכות\u0004 אשה \u0003ארוכה\u0004 (גבוהה) \u0003בצד קצרה\u0004 כדי שהארוכה תראה גבוהה יותר. \u0003\"ותלכנה נטויות גרון\" — שהיו מהלכות בקומה זקופה. \"ומשקרות עינים\" — דהוו מליין כוחלא עיניהן\u0004 \u0005[שהיו ממלאות עיניהן בכוחל]\u0006 כדי להדגישן. \u0003\"הלוך וטפוף תלכנה\" — שהיו מהלכות עקב בצד גודל\u0004 (אגודל), פסיעות קטנות כדרך הטף. \u0003\"וברגליהן תעכסנה\" אמר ר' יצחק: שהיו מביאות מור ואפרסמון ומניחות במנעליהן, וכשמגיעות אצל בחורי ישראל בועטות ומתיזות עליהן\u0004 את בשמיהן, \u0003ומכניסין בהן יצר הרע, כארס בכעוס.\u0004 שמפרש \"תעכסנה\" מלשון \"עכס\" = נחש.","\u0003שפיכות דמים\u0004 היתה שם, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וגם דם נקי שפך מנשה הרבה מאד עד אשר מלא את ירושלים פה לפה\"\u0004 (מלכים ב' כא, טז).","\u0003אבל מקדש שני שהיו עוסקין בתורה ובמצות וגמילות חסדים\u0004 ולא היו מצויים בו חטאים חמורים אלו, \u0003מפני מה חרב? מפני שהיתה בו שנאת חנם. ללמדך ששקולה שנאת חנם כנגד שלש עבירות\u0004 חמורות אלו: \u0003עבודה זרה, גלוי עריות, ושפיכות דמים.\u0004","ומעירים: \u0003רשעים היו, אלא שתלו בטחונם בהקדוש ברוך הוא.\u0004 ומסבירים: במשפט זה \u0003אתאן\u0004 \u0005[הגענו,\u0006 חזרנו\u0005]\u0006 לדבר בענין אנשי \u0003מקדש ראשון, דכתיב\u0004 \u0005[ש\u0006עליהם \u0005נאמר]:\u0006 \u0003\"ראשיה בשחד ישפטו וכהניה במחיר יורו ונביאיה בכסף יקסמו ועל ה' ישענו לאמר הלא ה' בקרבנו לא תבוא עלינו רעה\"\u0004 (מיכה ג, יא), שזה מכל מקום היה צד זכות להם. \u0003לפיכך,\u0004 בשל עבירות חמורות שחטאו בהן \u0003הביא עליהן הקדוש ברוך הוא שלש גזירות כנגד שלש עבירות שבידם, שנאמר: \"לכן בגללכם ציון שדה תחרש וירושלים עיין תהיה והר הבית לבמות יער\"\u0004 (מיכה ג, יב).","ושואלים: וכי \u0003במקדש ראשון לא הוה ביה\u0004 \u0005[לא היתה בו]\u0006 \u0003שנאת חנם? והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"\u0004זעק והילל בן אדם כי היא היתה בעמי היא בכל נשיאי ישראל \u0003מגורי אל חרב היו את עמי לכן ספק אל ירך\"\u0004 (יחזקאל כא, יז) \u0003ואמר ר' אלעזר\u0004 בביאור דברי הפסוק: \u0003אלו בני אדם שאוכלין ושותין זה עם זה\u0004 (\"מגורי\") \u0003ודוקרין זה את זה בחרבות שבלשונם.\u0004 הרי שאף אלה שהיו קרובים זה לזה היו מלאים שנאה זה לזה!","ומשיבים: \u0003ההיא\u0004 \u0005[אותה\u0006 מידה\u0005]\u0006 \u0003בנשיאי ישראל\u0004 בלבד \u0003הואי\u0004 \u0005[היתה]\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"זעק והילל בן אדם כי היא היתה בעמי\"\u0004 (יחזקאל כא, יז), \u0003ותניא\u0004 \u0005[ושנינו\u0006 בברייתא\u0005]:\u0006 \u0003\"זעק והילל בן אדם\u0004 כי היא היתה בעמי \u0003\"יכול לכל\u0004 היתה מידה רעה זו? — \u0003תלמוד לומר: \"היא בכל נשיאי ישראל\"\u0004 (יחזקאל כא, יז), הרי ששנאת חינם היתה מצויה רק בין גדולי העם, אבל רוב ישראל לא היו שונאים זה את זה.","\u0003ר' יוחנן ור' אלעזר דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003ראשונים\u0004 (בני בית המקדש הראשון) \u0003שנתגלה עונם\u0004 שלא הסתירו חטאיהם, אף \u0003נתגלה קצם\u0004 שפירש להם הנביא שבעוד שבעים שנה יחזרו לארצם. \u0003אחרונים\u0004 (בני בית המקדש השני) \u0003שלא נתגלה עונם\u0004 לפי שחטאו בסתר \u0003— לא נתגלה קצם\u0004 מתי יגאלו.","\u0003אמר ר' יוחנן: טובה צפורנן של ראשונים\u0004 כלומר, אפילו ציפורן, שהיא קטנה וחסרת ערך, \u0003מכריסן של אחרונים. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ריש לקיש: אדרבה\u0004 (להיפך) \u0003אחרונים עדיפי, אף על גב דאיכא\u0004 \u0005[אף על פי שיש]\u0006 \u0003שעבוד מלכיות\u0004 עליהם מכל מקום \u0003קא עסקי\u0004 \u0005[עוסקים הם]\u0006 \u0003בתורה. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בירה תוכיח\u0004 (המקדש יוכיח) \u0003שחזרה לראשונים\u0004 שהרי נבנה בית המקדש השני לאחר מיצוי עונשם \u0003ולא חזרה לאחרונים,\u0004 הרי שהראשונים חשובים יותר.","בדומה לכך \u0003שאלו את ר' אלעזר: ראשונים גדולים\u0004 מן האחרונים, \u0003או\u0004 שמא \u0003אחרונים גדולים\u0004 מהם? \u0003אמר להם: תנו עיניכם בבירה.\u0004 כלומר: הביטו במקדש, האם הושב לנו כלאבותינו? הרי שהראשונים גדולים מהאחרונים! \u0003איכא דאמרי\u0004 \u0005[יש אומרים]\u0006 בלשון אחרת \u0003אמר להם: עידיכם בירה,\u0004 כלומר בנין בית המקדש השני שחזר לראשונים, הריהו משמש עדות לכך שהם גדולים מן האחרונים\u0003.\u0004","מסופר: \u0003ריש לקיש הוי סחי בירדנא\u0004 \u0005[היה שוחה בירדן]\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003רבה בר בר חנה יהב ליה ידא\u0004 \u0005[נתן לו יד\u0006 לסייע לו לצאת\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003אלהא\u0004 \u0005[אלוקים]!\u0006 כלומר, נשבע בשמו, \u0003סנינא לכו\u0004 \u0005[שונא אני אתכם]\u0006 את הבבליים, ומה טעם — \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אם חומה היא נבנה עליה טירת כסף ואם דלת היא נצור עליה לוח ארז\"\u0004 (שיר השירים ח, ט), וכך משמעות הכתוב כפניה לכנסת ישראל: \u0003אם עשיתם עצמכם כחומה\u0004 כגוש חזק אחד \u0003ועליתם כולכם בימי עזרא — נמשלתם ככסף, שאין רקב שולט בו\u0004 והריכם ראויים להשראת השכינה באופן מלא, \u0003עכשיו שעליתם כדלתות,\u0004 כלומר: מעט ולא כולכם — \u0003נמשלתם כארז שהרקב שולט בו\u0004 ואינכם ראויים אלא להשראה חלקית.","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 רקב זה השולט ב\u0003ארז? אמר עולא: ססמגור,\u0004 שהיא מין תולעת הפוגעת בעצי הארז. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 עניינו של \u0003ססמגור\u0004 לענין השראת השכינה בימי הבית השני? \u0003אמר ר' אבא:\u0004 כשם שלא נותר מעץ הארז לאחר פגיעת תולעת זו אלא מקצתו כך, לא נותרה בימי בית שני מהשראת השכינה אלא \u0003בת קול\u0004 בלבד. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003משמתו נביאים האחרונים חגי זכריה ומלאכי נסתלקה רוח הקודש\u0004 של גילוי הנבואה \u0003מישראל ועדיין היו משתמשין בבת קול,\u0004 שהיו שומעים כהדה של נבואה.","אגב סיפור זה שואלים: \u0003וריש לקיש, מי משתעי בהדיה\u0004 \u0005[האם היה משוחח\u0006 במקום פומבי \u0005עם]\u0006 \u0003רבה בר בר חנה? ומה ר' אלעזר, דמרא דארעא דישראל הוה\u0004 \u0005[שאדון,\u0006 גדול, \u0005ארץ ישראל היה]\u0006 בחכמה ובמידות, ובכל זאת \u0003לא הוה משתעי\u0004 \u0005[היה משוחח]\u0006 \u0003ריש לקיש בהדיה\u0004 \u0005[אתו]\u0006 בפומבי, שריש לקיש היה מקפיד מאד בשיחה ובהודעת ידידותו רק ליחידי סגולה, \u0003דמאן דמשתעי\u0004 \u0005[שמי ששוחח]\u0006 \u0003ריש לקיש בהדיה\u0004 \u0005[אתו]\u0006 \u0003בשוק, יהבו ליה עיסקא בלא סהדי\u0004 \u0005[היו נותנים לו עסק,\u0006 כלומר הלוואה ושותפות עסקית, \u0005בלא עדים],\u0006 כי היה ידוע שריש לקיש לא היה משוחח אלא עם אדם גדול וצדיק בלבד. ואם ר' אלעזר לא היה נחשב בעיניו כדי לעמוד בשוק ולשוחח עימו, אם כן \u0003בהדי\u0004 \u0005[עם]\u0006 \u0003רבה בר בר חנה משתעי\u0004 \u0005[\u0006היה \u0005משוחח]?!\u0006","\u0003אמר רב פפא: שדי גברא בינייהו\u0004 \u0005[זרוק,\u0006 הטל, \u0005בן אדם ביניהם]\u0006 כלומר, חייב אתה לומר שלא אלה היו, אלא \u0003או ריש לקיש הוה\u0004 \u0005[היה]\u0006 זה שרחץ \u0003וזעירי\u0004 הבבלי שהיה מגדולי הדור הוא שהושיט לו יד, \u0003או\u0004 שתאמר כי \u0003רבה בר בר חנה\u0004 היה זה שרחץ, \u0003ור' אלעזר\u0004 הוא שהושיט לו ידו. על כל פנים, החכם ששמע את הדבר, \u0003כי אתא לקמיה\u0004 \u0005[כאשר בא לפני]\u0006 \u0003ר' יוחנן\u0004 וסיפר לו מעשה זה, \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003לאו היינו טעמא\u0004 \u0005[לא זהו הטעם],\u0006 כי \u0003אי נמי סליקו כולהו\u0004 \u0005[גם אם היו עולים כולם]\u0006 \u0003בימי עזרא לא הוה שריא\u0004 \u0005[היתה שורה]\u0006 ה\u0003שכינה במקדש שני, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"יפת אלהים ליפת וישכן באהלי שם\"\u0004 (בראשית ט, כז),"],["\u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003\"יפת אלהים ליפת\"\u0004 שהפרסים שמבני יפת הם שסייעו לבנות את בית המקדש השני — מכל מקום \u0003אין השכינה שורה אלא באהלי שם,\u0004 כלומר: בבית המקדש הראשון שנבנה על ידי שלמה המלך בלא סיוע מלכות זרה.","ושואלים: \u0003ופרסאי מנא לן\u0004 \u0005[והפרסיים מנין לנו]\u0006 ש\u0003מיפת קאתו\u0004 \u0005[הם באים]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"בני יפת גמר ומגוג ומדי ויון ותבל ומשך ותירס\"\u0004 (בראשית י, ב), ומפרשים: \u0003\"גומר\" — זה גרממיא, מגוג — זו קנדיא, מדי — זו מקדוניא, יון — כמשמעו\u0004 אלו היוונים, \u0003תובל\u0004 — זאת האומה הקרויה \u0003בית אונייקי, משך — זו מוסיא, תירס, פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה ר' סימאי ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' סימון ורבנן\u0004 \u0005[וחכמים]\u0006 נחלקו; \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: תירס זו בית תרייקי, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: זו‍ פרס.\u0004 ואם כן לדעה מסויימת, פרס (תירס) נמנה על בני יפת. \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 בברייתא: \u0003תירס — זו פרס.\u0004","נאמר עוד ברשימת העמים: \u0003\"\u0004ו\u0003סבתה ורעמה וסבתכא\"\u0004 (בראשית י, ז), \u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף:\u0004 אלו \u0003סקיסתן גוייתא\u0004 \u0005[הפנימית]\u0006 \u0003וסקיסתן ברייתא\u0004 \u0005[החיצונית],\u0006 \u0003בין חדא לחדא\u0004 \u0005[אחת לאחת]\u0006 מרחק \u0003מאה פרסי\u0004 \u0005[פרסאות],\u0006 \u0003והיקפא אלפא פרסי\u0004 \u0005[והיקפה\u0006 של ארץ זו \u0005אלף פרסאות].\u0006","ועוד בפירוש מקראות אלה, נאמר: \u0003\"ותהי ראשית ממלכתו בבל וארך ואכד וכלנה\u0004 בארץ שנער\u0003\"\u0004 (בראשית י, י) \u0003\"בבל\" — כמשמעה, ארך זו\u0004 העיר שהיתה קרויה בימיהם \u0003אוריכות, ואכד\u0004 — זהו המקום שנקרא אז \u0003בשכר. \"כלנה\" — זה נופר נינפי.\u0004","נאמר עוד: \u0003\"מן הארץ ההיא יצא אשור\"\u0004 (בראשית י, יא), \u0003תני רב יוסף: \"אשור\" — זה סילק\u0004 כלומר זה האיזור שבו נבנתה אחר כך העיר סילקיא. \u0003\"ויבן את נינוה ואת רחבת עיר ואת כלח\"\u0004 (בראשית י, יא), \u0003נינוה — כמשמעו, \"רחובות עיר\" — זו\u0004 הקרויה לאחר זמן \u0003פרת דמישן, \"כלח\" — זו פרת\u0004 של \u0003בורסיף. \"ואת רסן בין נינוה ובין כלח היא העיר הגדלה\"\u0004 (בראשית י, יב). \u0003\"רסן\" — זה\u0004 המקום הקרוי לאחר זמן \u0003אקטיספון. \"היא העיר הגדלה\" איני יודע אם\u0004 הכוונה היא ש\u0003נינוה\u0004 היא \u0003העיר הגדולה, אם רסן\u0004 היא \u0003העיר הגדולה, כשהוא אומר \"ונינוה היתה עיר גדולה לאלהים מהלך שלשת ימים\"\u0004 (יונה ג, ג) \u0003הוי אומר: נינוה היא העיר הגדולה.\u0004 וכיון שפירשנו ודרשנו שמות מקומות מן המקרא, מפרשים כיוצא בהם.","מה שנאמר \u0003\"ושם אחימן ששי ותלמי ילידי הענק\"\u0004 (במדבר יג, כב) \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003\"אחימן\"\u0004 נקרא כך — משום שהוא \u0003מיומן\u0004 וגדול \u0003שבאחים\u0004 (אחימן = אח ימין). \u0003\"ששי\"\u0004 נקרא כך — לפי \u0003שמשים את הארץ כשחיתות\u0004 (בורות), \"\u0003תלמי\"\u0004 נקרא כך — לפי \u0003שמשים את הארץ תלמים\u0004 (שורות המחרישה\u0003) תלמים\u0004 בפסיעותיו. \u0003דבר אחר: \"אחימן\"\u0004 הוא זה ש\u0003בנה\u0004 את המקום \u0003ענת, \"ששי\" בנה\u0004 את העיר \u0003אלוש, \"תלמי\" בנה\u0004 את המקום \u0003תלבוש. \"ילידי הענק\" — שמעניקין החמה בקומתן\u0004 כלומר שהם גבוהים כל כך עד שהחמה נראית כענק על צואריהם.","כיון שהזכרנו כאן את הדעות כי תירס היא פרס, מביאים דבר הקשור לכך. \u0003אמר ר' יהושע בן לוי אמר רבי: עתידה רומי שתפול ביד פרס, שנאמר: \"לכן שמעו עצת ה' אשר יעץ אל אדום ומחשבותיו אשר חשב אל ישבי תימן אם לוא יסחבום צעירי הצאן אם לא ישים עליהם נוהם\"\u0004 (ירמיה מט, כ).","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבה בר עולא: מאי\u0004 \u0005[מה]\u0006 \u0003משמע\u0004 (משמעות), מהו המקור לכך \u0003דהאי\u0004 \u0005[שזה\u0006 הכתוב\u0005]\u0006 \u0003\"צעירי הצאן\" פרס הוא\u0004 — בוודאי משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"האיל אשר ראית בעל הקרנים הוא מלכי מדי ופרס\"\u0004 (דניאל ח, כ) והאיל הוא מבני הצאן. ואולם מה הראיה מכאן? \u0003ואימא\u0004 \u0005[ואמור]\u0006 ש\"צעירי הצאן\" כוונתו ל\u0003יון\u0004 והם אשר יפילו את רומי \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]\u0006 גם בהם דימוי זה: \u0003\"והצפיר השעיר מלך יון\"\u0004 (ירמיה מט, כא), הרי שגם הם מדומים לצאן!","מסופר: \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 מבבל לארץ ישראל \u0003רב חביבא בר סורמקי אמרה\u0004 לקושיה זו \u0003קמיה דההוא מרבנן\u0004 \u0005[לפני אחד החכמים]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו חכם: \u0003מאן דלא ידע פרושי קראי\u0004 \u0005[מי שאינו יודע לפרש את הכתובים]\u0006 \u0003מותיב תיובתא\u0004 \u0005[מקשה קושיה]\u0006 \u0003לרבי?!\u0004 כלומר עזות מצח ישנה במי שאינו יודע פירוש המקראות ומקשה על אדם גדול כרבי. כי באמת לא הבין רבה בר עולא את יסוד הדרשה. \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"צעירי הצאן\" — זוטרא דאחוהי\u0004 \u0005[קטן שבאחיו]\u0006 ולכן הוא כינוי לפרס. \u0003דתני\u0004 \u0005[ש\u0006כן \u0005שנה]\u0006 \u0003רב יוסף: תירס זה פרס,\u0004 והרי תירס נמנה האחרון, והוא הקטן שבבני יפת. וזו היא איפוא מקור דרשתו של רבי, והכוונה של המדרש לגבי צעירי הצאן.","כיוצא בזה \u0003אמר רבה בר בר חנה אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יהודה בר' אלעאי: עתידה רומי שתפול ביד פרס; קל וחומר: ומה מקדש ראשון שבנאוהו בני שם והחריבוהו כשדיים,\u0004 בסופו של דבר \u0003נפלו כשדיים\u0004 (בלשאצר) \u0003ביד פרסיים\u0004 (דריוש המדי וחתנו כורש הפרסי), \u0003מקדש שני שבנאוהו פרסיים והחריבוהו רומיים — אינו דין שיפלו רומיים ביד פרסיים?\u0004","ואילו בניגוד לדעות אלה \u0003אמר רב: עתידה פרס שתפול ביד רומי. אמרו ליה\u0004 \u0005[לו]\u0006 תלמידיו \u0003רב כהנא ורב אסי לרב: בנויי ביד סתורי\u0004 \u0005[הבונים ביד הסותרים]?!\u0006 וכי כן הדין?! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 \u0003גזירת מלך היא\u0004 שכך יהיה למרות שאין זה נראה מן היושר. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אינהו נמי קא סתרי בי כנישתא\u0004 \u0005[הם גם כן,\u0006 הפרסיים, \u0005סותרים בתי כנסת]\u0006 אם כן אינם טובים יותר מן הרומאים.","\u0003תניא נמי הכי\u0004 \u0005[שנויה ברייתא גם כן כך]:\u0006 \u0003עתידה פרס שתפול ביד רומי, חדא\u0004 \u0005[\u0006טעם \u0005אחד] —\u0006 משום \u0003דסתרי בי כנישתא\u0004 \u0005[שהם סותרים\u0006 הורסים \u0005את בתי הכנסת],\u0006 \u0003ועוד: גזירת מלך הוא שיפלו בונין ביד סותרין.\u0004 ש\u0003אמר רב יהודה אמר רב: אין בן דוד בא עד שתפשוט מלכות רומי הרשעה בכל העולם כולו תשעה חדשים, שנאמר: \"לכן יתנם עד עת יולדה ילדה ויתר אחיו ישובון על בני ישראל\"\u0004 (מיכה ה, ב), שכזמן ההריון (\"עת יולדה\") שהוא תשעה חדשים, כך יהיה שלטון של רומי על כל העולם.","עתה שבים לעסוק בדיני פרישת הכהן הגדול ללשכת פרהדרין. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל הלשכו‍ת שהיו במקדש לא היה להן מזוזה,\u0004 כי אין קובעים מזוזה אלא בבית דירה שישנים בו, ובלשכות המקדש לא היו ישנים, \u0003חוץ מלשכת פרהדרין, שהיה בה בית דירה לכהן גדול,\u0004 ולכך היתה חייבת במזוזה.","\u0003אמר ר' יהודה:\u0004 לא זה הטעם, \u0003והלא כמה לשכות היו במקדש שהיה להן בית דירה,\u0004 שהיו משמשות מקום קבוע בשביל הכהנים לישיבה ולשינה שם \u0003ו\u0004בכל זאת \u0003לא היה להן מזוזה? אלא לשכת פרהדרין גזירה\u0004 מיוחדת \u0003היתה\u0004 שם שיקבעו בה מזוזה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שסבור שמן הדין לא היה צריך שתהא מזוזה בלשכת פרהדרין לולא הגזירה? \u0003אמר רבא: קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יהודה: כל בית שאינו עשוי\u0004 לגור בו \u0003לימות החמה ולימות הגשמים — אינו\u0004 נחשב \u0003בית,\u0004 ולכן אינו חייב במזוזה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי:\u0004 כיצד אפשר לומר שאינו נחשב כבית, \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"והכיתי בית החרף על בית הקיץ\"\u0004 (עמוס ג, טו) הרי שבית שנמצאים בו רק מחצית שנה, אף הוא קרוי בית! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003\"בית חורף\" ו\"בית קיץ\" איקרי\u0004 \u0005[נקרא]\u0006 בנין כגון זה, אולם \u0003\"בית\" סתמא לא איקרי\u0004 \u0005[סתם אינו נקרא],\u0006 שבית סתם הוא דווקא זה שגרים בו כל ימות השנה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 קושיה אחרת: שנינו, אם הכניס פירות מן השדה בחג הסוכות לתוך \u0003סוכת החג\u0004 בתוך ימי ה\u0003חג, ר' יהודה מחייב וחכמים פוטרין. ותני עלה\u0004 \u0005[ושנויה עליה]\u0006 כדברי ביאור: \u0003ר' יהודה מחייב\u0004 את הסוכה \u0003בעירוב\u0004 כדין בית הנמצא בחצר שצריך להשתתף בעירוב החצר כשאר בתים שבחצר, ומחייב את הסוכה \u0003במזוזה,\u0004 ומחייב אותה \u0003במעשר,\u0004 שיהא דינה למעשר כדין בית, שכל פרי הארץ אף שעדיין לא הוחלט לסיים את הטיפול בו (שמשום כך הוא פטור ממעשר עד גמר מלאכתו), כיון שמוכנס לבית — הריהו מתחייב במעשר, ולשיטת ר' יהודה דין הסוכה כדין הבית לענין זה. הרי שר' יהודה מחמיר בדין סוכת החג לחייבה במזוזה, אף שאינה עשוייה למדור אלא לשבעה ימים בלבד!","\u0003וכי תימא מדרבנן\u0004 \u0005[ואם תאמר\u0006 שהדבר הוא רק \u0005מדברי סופרים]\u0006 ואין בכך חיוב מן התורה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 לגבי \u0003עירוב ומזוזה איכא למימר מדרבנן\u0004 \u0005[יש לומר\u0006 שהם \u0005מדברי סופרים]\u0006 שמצאו מקום להחמיר בהלכות אלה, אף שאין לכך עיקר בדין תורה, \u0003אלא מעשר, מי איכא למימר מדרבנן\u0004 \u0005[האם יש לומר\u0006 שחייב בו רק \u0005מדברי סופרים]?\u0006"],["\u0003דילמא אתי לאפרושי\u0004 \u0005[שמא יבוא להפריש]\u0006 \u0003מן החיוב על הפטור ומן הפטור על החיוב.\u0004 שכיון שלא ברור שחובת הפרשה זו היא רק מדברי סופרים, יש לחשוש שמא יבואו אנשים להפריש מתבואה החייבת במעשר מן התורה על תבואה זו שאין בה חיוב מן התורה, ולהיפך, ובשל כך לא תחול קדושת המעשר על הפירות המופרשים, ואף הפירות עליהם הפרישו לא יצאו מגדר טבל ולא נתקנו. ולכן אין לומר שקבע ר' יהודה חובת הפרשה זו רק כגזירת חכמים.","\u0003אלא אמר אביי:\u0004 יש לפרש את המחלוקת בענין מזוזה בדרך שונה; \u0003בשבעה\u0004 הימים של פרישה כשהכהן הגדול דר בלשכת פרהדרין — \u0003דכולי עלמא לא פליגי דמיחייבא\u0004 \u0005[הכל אינם חלוקים שהיא חייבת]\u0006 במזוזה. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בשאר ימות השנה,\u0004 שאין אדם דר שם. \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003גזרינן\u0004 \u0005[גוזרים אנו]\u0006 ב\u0003שאר ימות השנה אטו\u0004 \u0005[משום]\u0006 אותם \u0003שבעה\u0004 ימים שהכהן דר שם, \u0003ור' יהודה סבר: לא גזרינן\u0004 \u0005[אין אנו גוזרים]\u0006 ולכן בשאר ימות השנה פטורה היא ממזוזה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003סוכת החג בחג קתני\u0004 \u0005[שנינו]!\u0006 ומשמע שנחלקו בחיוב מזוזה אפילו בתוך החג עצמו, ואם לדעתך הכל מודים שבזמן המגורים במקום אף אם הוא לתקופה קצרה חייבים לקבוע בו מזוזה, מהיכן אם כן נובעת שיטת החכמים החולקים בסוכה, ואומרים שאין חייבים לקבוע בה מזוזה אפילו בחג עצמו?","\u0003אלא אמר רבא\u0004 לפרש באופן אחר \u0003: בשאר ימות השנה — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 שלשכת פרהדרין \u0003פטורה\u0004 מן המזוזה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003בשבעה\u0004 הימים בהם הכהן דר בה וכן בסוכה כל שבעת ימי החג. וכדי לתרץ את הסתירה בין הדעות האמורות בלשכה ובסוכה, יש לומר כי ב\u0003סוכה\u0004 קיים \u0003טעמא\u0004 \u0005[טעם]\u0006 \u0003לחוד\u0004 וב\u0003לשכה\u0004 קיים \u0003טעמא\u0004 \u0005[טעם]\u0006 \u0003לחוד.\u0004","ומסביר: \u0003סוכה טעמא לחוד\u0004 \u0005[סוכה\u0006 יש בה \u0005טעם בפני עצמו]\u0006 כי \u0003ר' יהודה לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר: סוכה דירת קבע בעינן\u0004 \u0005[צריכים אנו],\u0006 כלומר: דרוש שתהיה הסוכה בנויה היטב ועשויה כדירת קבע, ולכן, כשאכן בנויה היא באופן כזה הריהי \u0003מיחייבא\u0004 \u0005[מחויבת]\u0006 \u0003במזוזה. ורבנן לטעמייהו\u0004 \u0005[וחכמים לטעמם,\u0006 לשיטתם\u0005]\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003סוכה דירת ארעי בעינן\u0004 \u0005[צריכים אנו]\u0006 וכיון שהיא בנויה דרך ארעי, לכך היא \u0003לא מיחייבא\u0004 \u0005[מחויבת]\u0006 \u0003במזוזה,\u0004 שהרי אינה נחשבת כבית ממש.","וכן ב\u0003לשכה טעמא\u0004 \u0005[טעם]\u0006 \u0003לחוד,\u0004 שכן \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003דירה בעל כרחה\u0004 כשאדם דר במקום שלא מתוך בחירתו ורצונו \u0003שמה דירה,\u0004 ולכן אף שהכהן הגדול דר בלשכת פרהדרין רק משום המצוה ולא מפני רצונו — מכל מקום נחשבת היא לו כדירה וחייבת במזוזה. \u0003ור' יהודה סבר: דירה בעל כרחה לא שמה דירה\u0004 ולכן היה צריך לפוטרה ממזוזה, כמו שאר לשכות המקדש שדרים בהן, אלא \u0003מדרבנן\u0004 \u0005[\u0006מדברי \u0005סופרים]\u0006 \u0003הוא דתקינו לה\u0004 \u0005[שתיקנו אותה]\u0006 שתהא מזוזה בפתח לשכה זו, כדי \u0003שלא יאמרו\u0004 הבריות: \u0003כהן גדול חבוש בבית האסורין,\u0004 שחדר ללא מזוזה קיים רק בדירות פחותות ומגונות ונראה שאינן ראויות לדירה, והרי הוא כיושב בבית האסורים.","ושואלים: \u0003מאן תנא להא\u0004 \u0005[מי שנה\u0006 דבר \u0005זה]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006"],["\u0003כל השערים שהיו שם\u0004 במזרח העזרה \u0003לא היה להם מזוזה, חוץ משער ניקנור,\u0004 משום \u0003שלפנים ממנו\u0004 בתוך העזרה היתה \u0003לשכת פרהדרין\u0004 שהיתה חייבת במזוזה, ולכן קבעו מזוזה אף בו.","\u0003לימא רבנן\u0004 \u0005[האם נאמר\u0006 שברייתא זו היא כשיטת \u0005חכמים]\u0006 \u0003היא ולא\u0004 כשיטת \u0003ר' יהודה? דאי\u0004 \u0005[שאם]\u0006 תאמר שכדברי \u0003ר' יהודה,\u0004 הרי \u0003היא\u0004 קביעת המזוזה בלשכת פרהדרין \u0003גופה\u0004 \u0005[עצמה]\u0006 היא רק משום \u0003גזירה, ואנן ניקום\u0004 \u0005[ואנחנו נעמוד]\u0006 \u0003ונגזור גזירה לגזירה\u0004 לקבוע מזוזה גם לשערים שלפני לשכה זו? והרי כלל בידינו שאין גוזרים גזירה נוספת על הקיימת! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שברייתא זו כשיטת \u0003ר' יהודה\u0004 היא, מכל מקום \u0003כולה חדא גזירה\u0004 \u0005[גזירה אחת]\u0006 \u0003היא.\u0004 כלומר: כיון שגזרו שתהא לשכת פרהדרין חייבת במזוזה, ממילא יש לנהוג בה כאילו היה חיובה מן התורה, וכל הפתחים המוליכים אליה חייבים אף הם במזוזה.","מתוך שדנו בענין מזוזה בלשכת הכהן הגדול דנים בהלכות מזוזה בכללן. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר: \u0003\"\u0004וכתבתם על מזוזות ביתך ו\u0003בשעריך\"\u0004 (דברים ו, ט) — \u0003אחד שערי בתים ואחד שערי חצרות ואחד שערי מדינות\u0004 \u0005[ערים]\u0006 \u0003ואחד שערי עיירות —\u0004 בכולם \u0003יש בהן חובת מצוה למקום\u0004 לקבוע בהם מזוזה, \u0003משום שנאמר: \"וכתבתם על מזזות ביתך ובשעריך\"\u0004 (דברים ו, ט).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב ספרא:\u0004 אם כן, כיון שקיימת חובת מזוזה גם על שערי הערים, אם כן \u0003הני אבולי\u0004 \u0005[אותם שערים]\u0006 של העיר \u0003מחוזא,\u0004 שרוב תושביה יהודים, \u0003מאי טעמא לא עבדו להו רבנן\u0004 \u0005[מה טעם לא עשו להם חכמים]\u0006 \u0003מזוזה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הנהו חזוק לאקרא דכובי הוא דעבידי\u0004 \u0005[אלה חיזוק למבצר שעל השער הם עשויים]\u0006 ולכן אין לראותן כפתח שער ממש ולכך אינם חייבים במזוזה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואקרא דכובי גופה תבעי\u0004 \u0005[ומבצר השער עצמו שיצטרך]\u0006 \u0003מזוזה, דהא אית\u0004 \u0005[שהרי יש]\u0006 \u0003בה דירה לשומר בית האסורין, דהא תניא\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005]\u0006 במקרה דומה: \u0003בית הכנסת שיש בו בית דירה לחזן\u0004 (לשמש) בית \u0003הכנסת — חייבת במזוזה\u0004 שאף שאין דרים בבית הכנסת עצמו, כיון שהשמש דר בחדר הסמוך אליו — חייב גם בית הכנסת עצמו במזוזה!","\u0003אלא אמר אביי:\u0004 הטעם שאין קובעים מזוזה שם הוא \u0003משום סכנה,\u0004 שעיר שכולה של יהודים ודאי היתה חייבת במזוזה במקום כזה, אלא כיון שדרים בה גם גוים יכול הדבר לבוא לידי סכנה, בכך שיאשימו את היהודים בכשפים או בריגול. וראיה לדבר \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מזוזת יחיד נבדקת\u0004 אם נפסלה או נגנבה \u0003פעמים בשבוע\u0004 (בשבע שנים), \u0003ו\u0004מזוזה \u0003של רבים —\u0004 נבדקת \u0003פעמים ביובל,\u0004 שכל דבר שהוא של רבים ואינו שייך לאדם מסויים, אין להטריח את הרבים בו, ולכך מזוזת הרבים די שתיבדק פעמיים ביובל.","\u0003ואמר ר' יהודה: מעשה בארטבין\u0004 (בודק) \u0003אחד שהיה בודק מזוזות בשוק העליון של צפורי\u0004 בשעת גזירת המלכות שגזרה שמד על ישראל \u0003ומצאו קסדור\u0004 \u0005[פקיד רומי]\u0006 \u0003אחד ונטל ממנו\u0004 כקנס \u0003אלף זוז.\u0004 על אותו מעשה שואלים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: שלוחי מצוה אין ניזוקין,\u0004 ומדוע אם כן ניזוק זה? ומשיבים: \u0003היכא דקביע היזקא, שאני\u0004 \u0005[במקום שקבוע\u0006 וברור \u0005ההיזק, שונה\u0006 הדבר\u0005],\u0006 שאף שאמרנו ששלוחי מצוה אין ניזוקין, מכל מקום אין זה מדובר במקום שהסכנה בו מוחשית, שבו לא תמיד מתרחש נס. וראיה לדבר ממה \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר שמואל איך אלך ושמע שאול והרגני ויאמר ה' עגלת בקר תקח בידך ואמרת לזבח לה' באתי\"\u0004 (שמואל א' טז, ב), הרי שאף שנשלח שמואל בדבר ה' למשוח את דוד, מכל מקום לא סמך על הנס במקום שהיתה בו סכנה ברורה.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב כהנא\u0004 ברייתא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יהודה: בית\u0004 (מחסן) \u0003התבן ובית הבקר\u0004 (רפת) \u0003ובית העצים ובית האוצרות — פטורים מן המזוזה, מפני שהנשים נאותות בהן. ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"נאותות\"\u0004 — כוונתו \u0003רוחצות.\u0004 שכיון שהנשים רוחצות שם ללא בגדיהן, אין זה מכבוד שמים שיקבעו שם מזוזה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה: טעמא\u0004 \u0005[הטעם]\u0006 שנתת הוא משום ש\u0003רוחצות\u0004 שם, \u0003הא סתמא\u0004 \u0005[הרי סתם]\u0006 בית הבקר ובית התבן שאין הנשים רוחצות בהם — \u0003חייבים\u0004 במזוזה? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003רפת בקר — פטורה מן המזוזה,\u0004 משמע שהיא פטורה תמיד מצד עצמה!","\u0003אלא\u0004 כך צריך לפרש: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נאותות\" — מתקשטות. והכי קתני\u0004 \u0005[וכך שנויה],\u0006 כלומר כך יש להבין את הברייתא הראשונה: \u0003אף על פי\u0004 שבתים אלה סגורים היטב ונקיים עד \u0003שהנשים מתקשטות בהן,\u0004 מכל מקום \u0003פטורין,\u0004 כיון שאינם בתי דירה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב כהנא:\u0004 ולשיטתך בתים \u0003שהנשים מתקשטות בהן פטורין\u0004 מן המזוזה, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 אחרת: \u0003רפת בקר — פטורה מן המזוזה,\u0004 אבל אלו \u0003שהנשים מתקשטות בהן — חייבת במזוזה,\u0004 והרי זו שיטה סותרת!","\u0003אלא מאי אית לך למימר\u0004 \u0005[מה יש לך לומר]\u0006 שלענין בתים שהנשים \u0003מתקשטות\u0004 בהם \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא,\u0004 שיש מי שמחייב בכגון זה במזוזה ויש מי שפוטר, וכיון שאתה חייב לומר שקיימות כאן דעות שונות, אם כן \u0003לדידי נמי סתמא תנאי היא\u0004 \u0005[לשיטתי גם כן סתם\u0006 בית בקר מחלוקת \u0005תנאים היא]\u0006 שיש חכמים המחייבים ויש הפוטרים, ואין להוכיח מברייתא אחת על השניה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"\u0004על מזוזות \u0003ביתך\"\u0004 — כוונתו: \u0003ביתך המיוחד לך\u0004 למגורים, \u0003פרט לבית התבן ולבית הבקר ולבית העצים ולבית האוצרות, שפטורין\u0004 הם \u0003מן המזוזה, ויש מחייבין.\u0004 הרי זו הוכחה גמורה שנחלקו חכמים בסתם בית התבן.","ומוסיפה הברייתא: \u0003באמת אמרו,\u0004 מסורת הלכה היתה כי \u0003בית הכסא ובית הבורסקי ובית המרחץ ובית הטבילה,\u0004 וכל מקום \u0003שהנשים נאותות בהן — פטורים מן המזוזה.\u0004 ברייתא זו כשמעיינים בה מוצאים שאינה מכוונת לא כשיטת רב כהנא ולא כשיטת רב יהודה, ועל כן \u0003רב כהנא מתרץ\u0004 (מיישב) אותה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 \u0003ורב יהודה מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006","\u0003רב כהנא מתרץ לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 כך: \u0003\"ביתך\" — ביתך המיוחד לך\u0004 למגורים, \u0003פרט לבית התבן ולבית הבקר ולבית העצים ולבית האוצרות, שפטורים מן המזוזה בסתם.\u0004 כלומר: אם אין אנו יודעים שמתרחצים בהם או משתמשים בהם שימוש אחר של גנאי, \u0003ויש\u0004 מי \u0003שמחייבים בסתם. באמת אמרו: בית הכסא ובית הבורסקי ובית המרחץ ובית הטבילה\u0004 וכל המקומות \u0003שהנשים נאותות בהן, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"נאותות\": רוחצות\u0004 בהן בעירום — \u0003פטורין מן המזוזה.\u0004","על הסבר זה מקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם פירוש \"נאותות\" הוא רוחצות אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 בדיוק בית ה\u0003מרחץ\u0004 ומדוע הוא מחלק בדבריו בין בית המרחץ ומקום שהנשים נאותות בו! ומשיבים: \u0003אשמעינן\u0004 \u0005[השמיע לנו\u0006 הלכה זו\u0005]\u0006 בענין \u0003מרחץ\u0004 של \u0003רבים, ואשמעינן\u0004 \u0005[והשמיע לנו]\u0006 גם כן \u0003מרחץ\u0004 של \u0003יחיד. דסלקא דעתך אמינא\u0004 \u0005[שיעלה על דעתך לומר]:\u0006 \u0003מרחץ\u0004 של \u0003רבים דנפיש זוהמיה\u0004 \u0005[שמרובה זוהמתו]\u0006 מפני שרבים מתרחצים בו — הוא הפטור מן המזוזה, \u0003אבל מרחץ\u0004 של ה\u0003יחיד,\u0004 כגון זה שנשות הבית בלבד רוחצות בו, ש\u0003לא נפיש זוהמיה\u0004 \u0005[מרובה זוהמתו] —\u0006 \u0003אימא ליחייב\u0004 \u0005[אמור שיתחייב]\u0006 במזוזה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין אנו מחייבין אותו במזוזה.","\u0003ו\u0004אילו \u0003רב יהודה מתרץ\u0004 את הברייתא שהבאנו \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003הכי קתני\u0004 \u0005[כך\u0006 היא \u0005שנויה],\u0006 כך יש להבינה: \u0003\"ביתך\" —\u0004 הכוונה ל\u0003ביתך המיוחד לך\u0004 למגורים, \u0003פרט לבית התבן ובית הבקר ובית העצים ובית האוצרות שפטורין מן המזוזה, אפילו\u0004 היו הנשים \u0003מתקשטות\u0004 (שכך הוא מפרש \"נאותות\") בהם, \u0003ויש\u0004 ה\u0003מחייבין במתקשטות, אבל\u0004 ב\u0003סתם — דברי הכל פטור\u0004 ממזוזה. \u0003באמת אמרו: בית הכסא ובית הבורסקי ובית המרחץ ובית הטבילה, אף על פי שהנשים מתקשטות בהן — פטורין מן המזוזה, משום דנפיש זוהמיה\u0004 \u0005[שמרובה זוהמתם].\u0006","ושואלים: \u0003ולרב יהודה\u0004 הרי \u0003סתמא\u0004 סתם מחסן ואוצר \u0003דברי הכל פטור\u0004 ממזוזה, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא אחרת\u0005]:\u0006 נאמר: \u0003\"\u0004ו\u0003בשעריך\" —\u0004 לומר: \u0003אחד שערי בתים ואחד שערי חצירות ואחד שערי מדינות ואחד שערי עיירות,\u0004 וכן \u0003ורפת ולולין\u0004 לתרנגולות \u0003ומתבן\u0004 (מחסן התבן) \u0003ואוצרות יין ואוצרות שמן — חייבין\u0004 כולם \u0003במזוזה. יכול שאני מרבה\u0004 בכלל החיוב במזוזה \u0003אף\u0004"],["\u0003בית שער\u0004 כלומר בית קטן שליד השער העשוי לשם שמירת הפתח. \u0003אכסדרה\u0004 (כעין מרפסת פתוחה) \u0003ומרפסת\u0004 המשמשת כפרוזדור לדירות רבות שאף הם יהיו חייבים במזוזה \u0003— תלמוד לומר: \"בית\",\u0004 ללמד: \u0003מה בית\u0004 משמעו דווקא זה \u0003המיוחד לדירה, יצאו אלו שאין\u0004 הם \u0003מיוחדין לדירה,\u0004 ונועדו למעבר בלבד או לצרכים אחרים, שהם פטורים מן המזוזה.","\u0003יכול שאני מרבה\u0004 בחיוב המזוזה \u0003אף בית הכסא ובית הבורסקי ובית המרחץ ובית הטבילה — תלמוד לומר: \"בית\", מה בית\u0004 הוא מקום \u0003העשוי לכבוד\u0004 ולכבד אנשים הבאים בתוכו — \u0003אף כל\u0004 מקום \u0003העשוי לכבוד, יצאו אלו\u0004 שאינם \u0003עשויין לכבוד.\u0004","\u0003יכול שאני מרבה\u0004 בחיוב מזוזה \u0003אף\u0004 את \u0003הר הבית והלשכות\u0004 שבו \u0003והעזרות\u0004 שבו \u0003— תלמוד לומר: \"בית\",\u0004 לומר: \u0003מה בית שהוא חול — אף כל\u0004 מקום \u0003שהוא חול, יצאו אלו שהן קודש.\u0004 על כל פנים למדנו מברייתא זו שיש חכמים הסבורים שבית התבן ובית הבקר סתם חייבים במזוזה, בניגוד לשיטת רב יהודה שהכל מודים שהם פטורים, והרי זו \u0003תיובתא\u0004 לשיטתו. ובהכרח יש לקבל את דברי רב כהנא שקיימת מחלוקת תנאים בענין זה.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב שמואל בר יהודה\u0004 ברייתא \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבא: ששה שערים פטורין מן המזוזה:\u0004 שער \u0003בית התבן,\u0004 ושל \u0003בית הבקר, ובית העצים, ובית האוצרות, ושער המדי,\u0004 שאיננו עשוי שתי מזוזות ומשקוף, אלא עשוי כולו כתבנית כיפה, \u0003ושער שאינו מקורה\u0004 כלל בגג, \u0003ושער שאינו גבוה עשרה\u0004 טפחים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003פתחת בששה,\u0004 שבראשית דבריך נקבת במספר ואמרת שישה שערים הם, \u0003וסלקת\u0004 \u0005[וגמרת]\u0006 \u0003בשבעה,\u0004 שהרי בפרטיהם אתה מוצא שבעה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שער המדי תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא\u0004 בו אם דינו כשער לענין מזוזה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כיפה, ר' מאיר מחייב במזוזה, וחכמים פוטרים. ושוין\u0004 (ומסכימים) שניהם \u0003שאם יש ברגלה,\u0004 כלומר בחלק הזקוף שבצדיה לפני שמתקמרת בראשה, \u0003עשרה\u0004 טפחים \u0003שחייבת במזוזה,\u0004 שחלק זה דינו כמזוזת פתח. \u0003אמר אביי\u0004 לפרש את הדעות בענין זה: \u0003דכולי עלמא\u0004 \u0005[ל\u0006דעת \u0005הכל]\u0006 גם לר' מאיר וגם לחכמים, אם \u0003גבוהה\u0004 כל אותה כיפה \u0003עשרה\u0004 טפחים בלבד \u0003ואין ברגלה\u0004 לפני מקום הקימור גובה \u0003שלשה\u0004 טפחים — \u0003ולאו\u0004 \u0005[ולא]\u0006 \u0003כלום היא,\u0004 שודאי אין זה נחשב כפתח ופטורה ממזוזה. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003יש ברגלה שלשה\u0004 טפחים \u0003ואינה גבוהה עשרה — ולאו\u0004 \u0005[ולא]\u0006 \u0003כלום היא,\u0004 משום שאין זה פתח ראוי.","\u0003לא נחלקו אלא בגבוהה\u0004 כולה \u0003עשרה\u0004 טפחים \u0003ויש ברגלה שלשה טפחים\u0004 אבל \u0003אין ברחבה\u0004 של הכיפה לכל גובהה מרחב הפתוח \u0003ארבעה\u0004 טפחים, שהרי קמורה היא בראשה והולכת ונעשית צרה, אבל \u0003יש בה\u0004 במקום הקימור רוחב מספיק כדי שאפשר יהא \u0003לחוק\u0004 (לחתוך ולחקוק) ו\u0003להשלימה לארבעה\u0004 טפחים. ובבעיה זו נחלקו; ש\u0003ר' מאיר סבר: חוקקין להשלים,\u0004 כלומר: כיון שיש מקום במזוזה לחקוק שיעור פתח הרי אנו דנים אותה כאילו נעשתה כבר חקיקה זו, ולכן נחשבת כיפה זו כבת שיעור פתח הראוי למזוזה, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003אין חוקקין להשלים,\u0004 שכיון שבפועל רוחב הפתח פחות מארבעה טפחים, לכך אינו נחשב כאילו נחקק והושלם לארבעה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003בית הכנסת, ובית האשה, ובית השותפין — חייבת במזוזה.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 מדוע ייפטרו אלה ממזוזה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003\"ביתך\"\u0004 נאמר, והוא להדגיש \u0003ולא ביתה\u0004 של אשה, וכן \u0003\"ביתך\" — ולא בתיהם\u0004 של שותפים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין לדייק כך, ודינם לענין מזוזה כשאר בתים.","ומקשים: \u0003ואימא הכי נמי\u0004 \u0005[ו\u0006שמא \u0005אמור\u0006 כי \u0005כך הוא גם כן]\u0006 ודייק אכן כך מלשון הכתוב? ודוחים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 מיד לאחר מצוות מזוזה: \u0003\"למען ירבו ימיכם וימי בניכם\"\u0004 (דברים יא, כא), כשכר על קיום מצוה זו, ואם ייפטרו אלה ממזוזה יש לתמוה: וכי \u0003הני בעו חיי\u0004 \u0005[אלה,\u0006 הגברים והיחידים, \u0005צריכים חיים]\u0006 \u0003והני לא בעו חיי\u0004 \u0005[ואלה,\u0006 הנשים והשותפים, \u0005אינם צריכים חיים]?!\u0006 אלא ודאי חובת מזוזה היא לכל ישראל.","ושואלים: \u0003אלא,\u0004 אם כן, הדגשת הפסוק \u0003\"ביתך\" למה לי?\u0004 שהרי החובה בכל בית! ומשיבים: יש לפרש \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא:\u0004 \"ביתך\" יש לדרשו — \u0003דרך ביאתך,\u0004 בצד שבו אתה מתחיל לבוא להיכנס לבית \u0003וכי עקר איניש\u0004 \u0005[וכאשר עוקר אדם]\u0006 את רגליו ופוסע \u0005—\u0006 \u0003כרעיה דימינא עקר ברישא\u0004 \u0005[\u0006את \u0005רגלו הימנית\u0006 הוא \u0005עוקר בראשונה]\u0006 וכיון שדרך הכניסה לבית היא ברגלו הימנית הרי שזהו הצד בו קובעים את המזוזה.","כיון שהבאנו ברייתא זו בדיני מזוזה, מביאים ברייתא בנושא אחר, הדומה לזו בדרך מדרש ההלכה. \u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בית הכנסת ובית השותפין ובית האשה מטמאין בנגעים\u0004 שאם נראה בהם נגע צרעת — הרי הם מקבלים טומאה כשאר בתים. ומקשים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]!\u0006 ומדוע לא יהא כן? ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 הרי נאמר בדיני נגעים: \u0003\"ובא אשר לו הבית\"\u0004 (ויקרא יד, לה) ונוכל לומר שיש כאן הדגשה למעט: \u0003\"לו\" — ולא לה, \"לו\" — ולא להן,\u0004 ותוציא מכלל טומאה זו בית אשה ובית השותפים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף אלו בכלל דין זה.","ומקשים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 כי \u0005כך הוא גם כן]\u0006 ונלמד מדיוק הלשון שאין בתים אלה מקבלים טומאת נגעים! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"בבית ארץ אחזתכם\"\u0004 (ויקרא יד, לד) שמדבר בלשון רבים, ללמדנו שכל בית בישראל שייך בדין זה. ושואלים: אם כן, ההדגשה \u0003\"לו\"\u0004 שנאמרה בכתוב \"ובא אשר לו הבית\", \u0003למה לי?\u0004 ומשיבים: דבר זה בא ללמדנו לא לענין הלכה, אלא להסביר את הטעם לבוא הנגע, שדבר זה קורה ל\u0003מי שמייחד ביתו לו\u0004 בלבד, שהוא קמצן \u0003שאינו רוצה להשאיל כליו\u0004 לאחרים \u0003ואומר שאין לו\u0004 כלים אלה בביתו. וכעונש \u0003הקדוש ברוך הוא מפרסמו כשמפנה את ביתו\u0004 כדין בית שיש בו נגע, והכל רואים שהיו כלים אלה ברשותו. \u0003פרט למשאיל כליו לאחרים,\u0004 שכיון שאינו מייחד את ביתו רק לעצמו — אין נגע הצרעת פוגע בו.","על ברייתא זו שואלים מצד אחר: \u0003ובית הכנסת מי\u0004 \u0005[האם]\u0006 \u0003מטמא בנגעים? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול יהיו בתי כנסיות ובתי מדרשות מטמאין בנגעים, תלמוד לומר: \"ובא אשר לו הבית\" — מי שמיוחד לו\u0004 הבית באופן פרטי, \u0003יצאו\u0004 בתים \u0003אלו שאין מיוחדין לו\u0004 לאדם אחד אלא הם רכוש הציבור!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 משום שיש מחלוקת תנאים בדבר. \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זאת]\u0006 — כשיטת \u0003ר' מאיר, הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 — \u0003רבנן\u0004 \u0005[\u0006כשיטת \u0005חכמים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003בית הכנסת שיש בה בית דירה לחזן\u0004 (לשמש) בית \u0003הכנסת — חייב במזוזה,\u0004 שהרי נחשב כבית דירה. \u0003ושאין בה בית דירה — ר' מאיר מחייב, וחכמים פוטרין.\u0004 למדנו מכאן שר' מאיר סבור כי דין בית הכנסת כדין בית פרטי, וכשם שדין זה נוגע לענין מזוזה, כן הדין גם לגבי טומאת נגעים.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר לסתירה בין הברייתות בענין בית הכנסת, שאפשר לומר שגם \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האומרת שבית הכנסת מטמא \u0003ו\u0004גם \u0003הא\u0004 \u0005[וזו]\u0006 הברייתא האומרת שאינו מטמא \u0003רבנן\u0004 \u0005[\u0006כשיטת \u0005חכמים]\u0006 היא, \u0003ולא קשיא\u0004 \u0005[ואינו קשה]\u0006 \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאמרנו שהוא מטמא — \u0003דאית\u0004 \u0005[שיש]\u0006 \u0003בה בית דירה\u0004 כגון למגורי השמש, \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 שאינו מטמא — \u0003דלית\u0004 \u0005[שאין]\u0006 \u0003בה בית דירה.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ליישב את הסתירה בדרך נוספת: \u0003הא והא דלית\u0004 \u0005[זו וזו\u0006 מדובר \u0005שאין]\u0006 \u0003בה בית דירה\u0004"],["\u0003והא\u0004 \u0005[ו\u0006ברייתא \u0005זו]\u0006 שאינו מטמא — בבית כנסת של \u0003כרכים\u0004 (ערים גדולות), שכיון שמתקבצים אנשים ממקומות שונים להתפלל שם איננו רכושם של בני העיר בלבד, אלא של הציבור כולו. \u0003והא\u0004 \u0005[ו\u0006ברייתא \u0005זו]\u0006 שמטמא — בבית כנסת של \u0003כפרים\u0004 שהוא שייך רק לבני הכפר עצמו, והריהו כבית שותפים.","ומקשים: ובית כנסת של \u0003כרכים אין מטמא בנגעים? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"\u0004בבית ארץ \u0003אחזתכם\"\u0004 (ויקרא יד, לד) \u0003—\u0004 ללמד \u0003אחזתכם\u0004 שלכם \u0003מטמאה בנגעים, ואין\u0004 העיר \u0003ירושלים מטמאה בנגעים\u0004 לפי שאינה נחלה השייכת לשבט מסויים, אלא שייכת לכל ישראל. \u0003אמר ר' יהודה: אני לא שמעתי\u0004 על מקום בארץ ישראל שאינו מיטמא בנגעים \u0003אלא מקום מקדש בלבד.\u0004 ומדבריו נדייק ללמוד \u0003הא\u0004 \u0005[הרי]\u0006 שלשיטתו אפילו \u0003בתי כנסיות ובתי מדרשות\u0004 שבירושלים \u0003מטמאין בנגעים, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ששל \u0003כרכים נינהו\u0004 \u0005[הם]!\u0006 ודוחים: \u0003אימא\u0004 \u0005[אמור]\u0006 ותקן כך: \u0003אמר ר' יהודה: אני לא שמעתי אלא מקום מקודש בלבד,\u0004 ובכלל זה אף בתי כנסיות ובתי מדרשות.","כיון שהובאה ברייתא זו מסבירים אותה: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005נחלקו]\u0006 ר' יהודה וחכמים? \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003סבר\u0004 כי \u0003ירושלים לא נתחלקה לשבטים,\u0004 אלא שייכת לכלל ישראל ולכן אינה מיטמאה בנגעים. ואילו \u0003ר' יהודה סבר\u0004 כי \u0003ירושלים נתחלקה לשבטים,\u0004 לשבט יהודה ובנימין, ודינה כשאר ארץ ישראל, ולכך הריהי מיטמאה בנגעים כשאר ערי ארץ ישראל.","ומעירים: כי \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקת של תנאים אלה]\u0006 שנחלקו במפורש בנושא זה, נחלקו אף הם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מה היה בחלקו של יהודה\u0004 בתחום בית המקדש — \u0003הר הבית\u0004 עצמו, \u0003הלשכות והעזרות. ומה היה בחלקו של בנימין — אולם והיכל ובית קדשי הקדשים, ורצועה\u0004 של קרקע \u0003היתה יוצאה מחלקו של יהודה ונכנסת לחלקו של בנימין, ובה היה\u0004 ה\u0003מזבח בנוי. ובנימין הצדיק היה מצטער עליה לבלעה בכל יום\u0004 כלומר, היה מצטער על שרצועה זו של שבט יהודה, והיה רוצה שימסרנה שבט יהודה לרשותו, שיהיה מזבח כולו שלו.","ורמז לדבר, \u0003שנאמר\u0004 בברכת משה לבנימין: \u0003\"חפף עליו כל היום\u0004 ובין כתפיו שכן\u0003\"\u0004 (דברים לג, יב), כאדם שאינו יכול לסבול דבר הנמצא בין כתפיו ומתחכך (\"חופף\") תמיד להסירו. \u0003לפיכך\u0004 מפני דבר זה \u0003זכה בנימין הצדיק ונעשה אושפיזכן\u0004 \u0005[מארח]\u0006 \u0003לגבורה\u0004 (לשכינה), \u0003שנאמר: \"ובין כתפיו שכן\"\u0004 שקודש הקדשים היה בנחלת בנימין. הרי שלברייתא זו ברור הדבר שירושלים נתחלקה לשבטים.","\u0003ו\u0004אילו \u0003האי תנא\u0004 \u0005[ותנא זה\u0006 שיובאו דבריו\u0005]\u0006 \u0003סבר\u0004 כי \u0003ירושלים לא נתחלקה\u0004 כלל \u0003לשבטים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אין\u0004 בעלי הבתים שבירושלים \u0003משכירין בתים בירושלים לפי שאינה שלהן,\u0004 שאינם נחשבים כבעלי הבית אלא כדיירים בלבד, שאין להם זכות לאחוזת קבע בירושלים, ואינה אלא רכוש העם כולו. \u0003ר' אלעזר בר צדוק אומר: אף לא\u0004 משכירים בה \u0003מטות. לפיכך, עורות קדשים\u0004 (של שלמי חגיגה ושמחה) שהיו הבאים לרגל לירושלים נוהגים לתת במתנה לבעלי הבתים על שאירחום בביתם — אינם זכאים להם על פי דין, אלא \u0003בעלי אושפזיכנין\u0004 (המארחים) היו \u0003נוטלין אותן ב\u0004כוח ה\u0003זרוע. אמר אביי\u0004 אגב כך: \u0003שמע מינה\u0004 \u0005[למד מכאן],\u0006 כי \u0003אורח ארעא למישבק איניש גולפא ומשכא לאושפיזיה\u0004 \u0005[דרך ארץ\u0006 הוא \u0005שיעזוב\u0006 שיניח אחריו \u0005אדם את כד\u0006 היין ששתה בו, \u0005ואת עור\u0006 הבהמה ששחט ואכל \u0005למארח שלו],\u0006 כתמורה על שאירחו בביתו.","לאחר שנתברר ענין חלוקת ירושלים, שבים לבירור דין בתי כנסת של רבים. ושואלים: \u0003ו\u0004בית הכנסת של \u0003כפרים מי\u0004 \u0005[האם]\u0006 \u0003מטמא בנגעים? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \"כי תבואו אל ארץ כנען אשר אני נותן לכם \u0003לאחזה\u0004 ונתתי נגע צרעת...\" (ויקרא יד, לד), ונדייק: \"לאחוזה\" — כוונתו \u0003עד שיכבשו אותה\u0004 ותהיה לגמרי שלהם. \u0003כבשו אותה ולא חלקוה לשבטים,\u0004 ואפילו \u0003חלקו לשבטים ולא חלקו לבית אבות, חלקו לבית אבות ו\u0004עדיין \u0003אין כל אחד מכיר את\u0004 חלקו \u0003שלו\u0004 המיוחד לו, \u0003מניין\u0004 שאינו מיטמא?","\u0003תלמוד לומר: \"ובא אשר לו הבית\"\u0004 (ויקרא יד, לה): \u0003מי שמיוחד\u0004 הבית \u0003לו\u0004 ויודע את בעלותו עליו, \u0003יצא\u0004 בתים \u0003אלו שאין מיוחדין לו.\u0004 ומכאן נלמד שאפילו בית הכנסת שבכפרים, כיון שאין היכר בחלקו של כל אחד מהמתפללים, לכך הריהו נחשב כרכוש הכלל, ואינו מטמא. \u0003אלא\u0004 יש לדחות את החילוק בין דין הכפרים ודין הכרכים. ולקושייתנו הראשונה \u0003מחורתא כדשנין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כמו שהסברנו מתחילה]\u0006 שיש טעמים אחרים לישוב הסתירה בין הברייתות.","במשנה שנינו כי \u0003מתקינין\u0004 (מכינים) \u0003לו\u0004 לכהן הגדול עוד \u0003כהן אחר\u0004 שיוכל למלא מקומו אם נטמא הכהן הגדול ביום הכיפורים. ויש לברר שאלה המתעוררת בענין זה, ויש להקדים לה כי \u0003פשיטא\u0004 \u0005[פשוט,\u0006 ברור הדבר\u0005]\u0006 כי \u0003אם אירע בו פסול\u0004 בכהן הגדול המכהן \u0003קודם\u0004 הקרבת \u0003תמיד של שחר\u0004 ביום הכיפורים \u0003— מחנכין אותו\u0004 את הכהן הגדול החדש \u0003בתמיד של שחר,\u0004 שמלבישים אותו בשמונת בגדי הכהן הגדול והוא מקריב את קרבן התמיד של שחר, ועל ידי זה הריהו נעשה כהן גדול בפועל. \u0003אלא\u0004 אם \u0003אירע בו פסול\u0004 בכהן המכהן ל\u0003אחר תמיד של שחר,\u0004 שאז על הכהן הגדול להתחיל בעבודה המיוחדת ליום הכיפורים, ועבודה זו נעשית רק בארבעה בגדי לבן (כתונת, מכנסיים, מצנפת ואבנט) שהם בגדיו של כהן הדיוט, אם כן \u0003במה מחנכין אותו?\u0004 במה, ניכר כי נעשה כהן גדול בפועל?","\u0003אמר רב אדא בר אהבה: באבנט,\u0004 כי האבנט שלובש הכהן הגדול ביום הכיפורים הוא אבנט עשוי בד (פשתן) ואינו כמו אבנטו של כהן הדיוט העשוי כלאים של צמר ופשתים. ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 כי \u0003אבנטו של כהן גדול\u0004 בכל ימות השנה, שמפורש בכתוב שהוא כלאים, \u0003זה הוא אבנטו של כהן הדיוט\u0004 שאין הבדל ביניהם. וביום הכיפורים לובש הכהן הגדול אבנט מיוחד של בוץ (פשתן), ולכן כשלובשו הרי בכך מתחנך לכהונה גדולה. \u0003אלא למאן\u0004 \u0005[ל\u0006שיטת \u0005מי]\u0006 ש\u0003אמר\u0004 ש\u0003אבנטו של כהן גדול\u0004 בכל ימות השנה \u0003לא זהו אבנטו של כהן הדיוט,\u0004 ורק הכהן הגדול לובש אבנט של תכלת ארגמן ופשתים, ואילו אבנטו של כהן הדיוט הינו של פשתן בכל ימות השנה, כשאר בגדיו, אם כן, ביום הכיפורים כאשר הכהן הגדול לבוש אבנט בד כמפורש בתורה, הרי אין הבדל בין כהן הדיוט וכהן גדול, ולשיטה זו \u0003מאי איכא למימר\u0004 \u0005[מה יש\u0006 לנו \u0005לומר],\u0006 במה מתחנך הוא לכהונה גדולה?","\u0003אמר אביי:\u0004 כך היא דרך חינוכו ועלייתו לכהונה גדולה: לפני שיתחיל בעבודת יום הכיפורים שנעשית בארבעה בגדי לבן הריהו \u0003לובש שמונה\u0004 בגדים המיוחדים לכהן גדול, \u0003ומהפך בצינורא\u0004 \u0005[במזלג]\u0006 שעל המזבח להחיש את הבערת אברי קרבן התמיד ועל ידי עבודת קודש בבגדי כהונה גדולה — נעשה כהן גדול. \u0003וכ\u0004שיטת \u0003רב הונא,\u0004 ש\u0003אמר רב הונא: זר שהפך\u0004 חלק מהקרבנות \u0003בצינורא\u0004 \u0005[במזלג] —\u0006 \u0003חייב מיתה\u0004 משום שעבד עבודת קודש מיוחדת לכהונה. \u0003ורב פפא אמר:\u0004 אין צורך בפעולה זו, אלא"],["\u0003עבודתו מחנכתו\u0004 כלומר, אין ממלא המקום צריך חינוך מיוחד, אלא בעצם העובדה שהוא עובד עבודת יום הכיפורים שאינה כשרה אלא בכהן גדול — בכך נעשה כהן גדול. וראיה לדבר \u0003מי לא תניא\u0004 \u0005[האם לא שנינו\u0006 בברייתא\u0005]\u0006 כי \u0003כל הכלים\u0004 של מקדש \u0003שעשה משה — משיחתן מקדשתן,\u0004 שהרי נצטווה בתורה למשחם בשמן המשחה כדי לקדשם \u0003ומכאן ואילך\u0004 לאחר ימי משה — שוב אין צורך למשוח כלי קודש חדש בשמן המשחה כדי לקדשו, אלא \u0003עבודתן\u0004 עצמה היא ש\u0003מחנכתן.\u0004 שכאשר נוטלים כלי מתאים ומשתמשים בו לעבודת הקודש, הרי באותה עבודה עצמה הוא מתקדש למלאכתו, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בכהן גדול — \u0003עבודתו\u0004 ככהן גדול היא \u0003מחנכתו.\u0004","כיון שהוזכרה המחלוקת ביחס לאבנטו של כהן גדול, מביאים אותה בשלמותה. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר:\u0004 ביחס \u0003לאבנטו של כהן הדיוט\u0004 נחלקו \u0003רבי ור' אלעזר בר' שמעון; חד\u0004 \u0005[אחד\u0006 מהם] \u0003אמר: של כלאים\u0004 היה, כאבנטו של הכהן הגדול המתואר בתורה במפורש, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: של בוץ\u0004 (פשתן) היה, ככל שאר בגדי כהן הדיוט שהיו בגדי בוץ.","ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר,\u0006 תתברר\u0005]\u0006 כי \u0003רבי הוא\u0004 ש\u0003אמר\u0004 ששל \u0003כלאים\u0004 הוא. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין בין כהן גדול לכהן הדיוט אלא אבנט,\u0004 אלו \u0003דברי רבי. ר' אלעזר בר' שמעון אומר: אף לא אבנט.\u0004 ונברר את הדברים; \u0003אימת\u0004 \u0005[אימתי]\u0006 לגבי איזה זמן נאמרה מחלוקת זו? \u0003אי נימא\u0004 \u0005[אם נאמר]\u0006 \u0003בשאר ימות השנה\u0004 שאבנטו של הכהן הגדול של כלאים הוא ובשל הדיוט נחלקו — הרי בלא זה \u0003טובא איכא\u0004 \u0005[\u0006הבדל \u0005מרובה יש]\u0006 כי \u0003כהן גדול משמש בשמונה\u0004 בגדים ואילו כהן \u0003הדיוט\u0004 משמש \u0003בארבעה\u0004 בגדים בלבד!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003ביום הכפורים\u0004 שהכהן הגדול משמש באבנט בוץ ובשל הדיוט נחלקו, שלשיטת רבי שאינו כשל כהן גדול, משמע ששל ההדיוט של כלאים הוא. ואילו לשיטת ר' אלעזר בר' שמעון שהאבנטים שוים, משמע שאף אבנטו של כהן הדיוט של בוץ הוא, כאבנטו של כהן גדול.","את ההוכחה הזו דוחים; \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 אין כאן הוכחה, כי \u0003לעולם\u0004 יכול אתה לפרש כי מדובר כאן \u0003בשאר ימות השנה\u0004 ואין מדובר כאן בהבדל המפורש ביניהם בארבעה בגדים יתרים של הכהן הגדול, אלא, \u0003בהנך\u0004 \u0005[באותם]\u0006 ארבעת הבגדים ש\u0003שוין\u0004 הם — כתונת, מכנסים, מצנפת ואבנט — שבהם שוים כהן גדול וכהן הדיוט. ולפי זה תהא המסקנה הפוכה, שלדעת רבי אבנטו של כהן גדול הריהו של כלאים ושל כהן הדיוט של בוץ, ואילו לדעת ר' אלעזר בר' שמעון אף אבנטו של כהן הדיוט של כלאים הוא. ואם כן אין להביא הוכחה גמורה מברייתא זו.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 מסורת זו באופן מפורש יותר: \u0003אבנטו של כהן גדול ביום הכפורים — דברי הכל של בוץ\u0004 הוא, כמפורש בתורה. ו\u0003בשאר ימות השנה — דברי הכל\u0004 הריהו \u0003של כלאים. לא נחלקו אלא באבנטו של כהן הדיוט בין בשאר ימות השנה, ובין ביום הכפורים. שרבי אומר\u0004 שהוא \u0003של כלאים, ו\u0004אילו \u0003ר' אלעזר בר' שמעון אומר: של בוץ\u0004 הוא.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 בברייתא כעין שיטה זו. שכך שנו: נאמר בתרומת הדשן מן המזבח: \u0003\"\u0004ולבש הכהן מידו בד ומכנסי בד ילבש \u0003על בשרו\"\u0004 (ויקרא ו, ג), ולשון הפסוק תמוה, שהרי אחר שנאמר כבר \"ולבש\" \u0003מה תלמוד לומר \"ילבש\"?\u0004 אלא בא הכתוב \u0003להביא\u0004 (להוסיף) חובת חבישת \u0003מצנפת\u0004 וחגירת \u0003אבנט להרמת הדשן\u0004 אף שלא נתפרש הדבר בכתוב, אלו \u0003דברי ר' יהודה.\u0004","\u0003ר' דוסא אומר:\u0004 ייתור לשון זה בא \u0003להביא\u0004 (לרבות) \u0003בגדי כהן גדול ביום הכפורים שהם כשרין לכהן הדיוט,\u0004 שהרי כהן גדול ביום הכיפורים לובש רק ארבעה בגדי בוץ, ואף שאין הכהן הגדול עצמו יכול לשמש באותם בגדים ביום הכיפורים לשנה אחרת, מכל מקום רשאי כהן הדיוט ללבוש בגדים אלו בשאר ימות השנה. \u0003רבי אומר: שתי תשובות בדבר\u0004 לדחות את דברי ר' דוסא; \u0003חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 היא: ש\u0003אבנטו של כהן גדול ביום הכפורים לא זה הוא אבנטו של כהן הדיוט\u0004 בשאר ימות השנה. הרי ברור מכאן כי לדעת רבי אבנטו של כהן גדול ביום כיפור הוא של בוץ, ושל הדיוט בכל השנה של כלאים.","\u0003ועוד\u0004 תשובה (דחיה) לדברי ר' דוסא: כיצד יתכן ש\u0003בגדים שנשתמשתה בהן קדושה חמורה\u0004 של כהן גדול, \u0003תשמש בהן קדושה קלה\u0004 של כהן הדיוט? \u0003אלא\u0004 לשיטת רבי \u0003מה תלמוד לומר\u0004 בריבוי הלשון \u0003\"ילבש\"?\u0004 — הרי זה בא \u0003לרבות את\u0004 הבגדים \u0003השחקין\u0004 (השחוקים), שכל עוד אינם בלויים לגמרי מותר להשתמש בהן לעבודה זו.","ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003ר' דוסא לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר: \u0003\"\u0004ובא אהרן אל אהל מועד ופשט את בגדי הבד אשר לבש בבואו אל הקודש \u0003והניחם שם\"\u0004 (ויקרא טז, כג) \u0003מלמד\u0004 שבגדים ששימש בהם הכהן הגדול ביום הכיפורים \u0003טעונין גניזה\u0004 ואסורים בשימוש נוסף. \u0003ר' דוסא אומר:\u0004 אין כוונת הכתוב אלא \u0003שלא ישתמש בהן\u0004 הכהן הגדול ב\u0003יום הכפורים אחר.\u0004 משמע כי לדבריו אף שאין הכהן גדול רשאי להשתמש בהם יותר, מכל מקום מותרים הם לשימוש כהן הדיוט בכל ימות השנה, שהרי אינם טעונים גניזה.","שוב חוזרים אנו לגוף ההלכה בענין התקנת כהן אחר תחתיו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אירע בו פסול\u0004 בכהן הגדול המכהן \u0003ומינו אחר תחתיו,\u0004 ואחר כך נתקן פסולו של ראשון, כגון שנטהר מטומאתו, הכהן ה\u0003ראשון חוזר לעבודתו\u0004 להיות ככהן גדול, וה\u0003שני\u0004 שנתמנה לפי שעה \u0003כל מצות כהונה גדולה עליו\u0004 שמשמש בשמונה בגדים ואסור בפריעה ופרימה ולהיטמא לקרוביו ואינו נושא את האלמנה, אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יוסי אומר:\u0004 לא כן, אלא הכהן ה\u0003ראשון — חוזר לעבודתו,\u0004 ואילו ה\u0003שני — אינו ראוי\u0004 לשמש \u0003לא לכהן גדול\u0004 בשמונה בגדים, שהרי יש כהן גדול אחר, \u0003ולא לכהן הדיוט\u0004 בארבעה בגדים, מאחר וכבר היה קדוש בקדושה חמורה, שוב אינו יורד לקדושה קלה ממנה,","\u0003אמר ר' יוסי\u0004 ראיה לדבריו: \u0003מעשה ב\u0004כהן \u0003יוסף בן אלם\u0004 שהיה דר \u0003בציפורי ש\u0004בזמנו \u0003אירע בו\u0004 פעם \u0003פסול בכהן גדול ומינוהו\u0004 ליוסף בן אלם \u0003תחתיו\u0004 לכהונה גדולה, \u0003ו\u0004לאחר שנתקן הכהן הגדול הראשון \u0003אמרו חכמים: ראשון — חוזר לעבודתו,\u0004 ואילו ה\u0003שני — אינו ראוי לא\u0004 להיות \u0003כהן גדול\u0004 ולעבוד בשמונה בגדים, ולא להיות כ\u0003כהן הדיוט\u0004 ולעבוד בארבעה. ומסבירים: \u0003כהן גדול\u0004 אינו יכול להיות — \u0003משום איבה,\u0004 כי אם יהיו שני כהנים גדולים במקדש, הרי זה פתח לשנאה קנאה ומרירות, ועלינו להמנע מכך. וכן \u0003כהן הדיוט אינו יכול להיות, משום שמעלין בקודש ולא מורידין,\u0004 ומאחר שהיה כבר כהן גדול, שוב אינו יכול לחזור ולשמש ככהן הדיוט.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן:\u0004"],["\u0003הלכה כר' יוסי\u0004 שהראשון חוזר לעבודתו ככהן גדול ואילו השני אינו ראוי לשמש לא ככהן גדול ולא כהדיוט\u0003. ומודה ר' יוסי, שאם עבר\u0004 הכהן השני \u0003ועבד\u0004 ככהן גדול בשמונה בגדים ש\u0003עבודתו כשרה. אמר רב יהודה אמר רב: הלכה כר' יוסי, ומודה ר' יוסי שאם מת\u0004 הכהן ה\u0003ראשון, שחוזר\u0004 השני \u0003לעבודתו\u0004 ככהן גדול.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיכול השני לשמש ככהן גדול, שהרי מאחר ומת הראשון שוב אין לחשוש לאיבה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 אם ידע הכהן הגדול שיש כבר כהן אחר העומד מוכן להתמנות תחתיו, הרי מצב הזה \u0003הויא ליה\u0004 \u0005[יהיה\u0006 \u0005לו]\u0006 כשל אשה שיש לה \u0003צרה מחיים,\u0004 שבעלה מכין לעצמו אשה אחרת במקומה. ומצב זה עצמו עשוי להביא לידי איבה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו ]\u0006 שאין לחשוש לכך.","שנינו במשנה, \u0003ר' יהודה אומר: אף אשה אחרת\u0004 היו \u0003מתקינין לו.\u0004 וחכמים אומרים שאין חוששים שמא תמות אשתו, ולכך לא היו מתקינים לו אשה אחרת. ושואלים: \u0003לרבנן נמי\u0004 \u0005[לחכמים גם כן]\u0006 \u0003הא חיישי\u0004 \u0005[הרי חוששים הם]\u0006 \u0003לשמא\u0004 יטמא, ובשל כך מתקינים לו כהן אחר תחתיו, ומדוע לא יחששו גם שמא תמות אשתו? ומשיבים: \u0003אמרי לך רבנן\u0004 \u0005[\u0006יכולים היו \u0005חכמים לומר לך]:\u0006 \u0003טומאה — שכיחא\u0004 \u0005[מצויה]\u0006 שעשוי הכהן להיטמא בכל שעה בין בטומאה היוצאת מגופו, בין מזו הבאה מבחוץ, אבל \u0003מיתה לא שכיחא\u0004 \u0005[מצויה]\u0006 כל כך, ואין צורך לחשוש לכך.","נאמר במשנה ש\u0003אמרו לו\u0004 חכמים: \u0003אם כן, אין לדבר סוף,\u0004 שאם אתה חושש שמא תמות אשתו, אם כן יש לחשוש כן אף למות אשתו השניה, וצריך להכין מראש אשה שלישית ורביעית. ומעירים: \u0003שפיר קא אמרי ליה\u0004 \u0005[יפה אמרו לו]\u0006 חכמים \u0003לר' יהודה!\u0004 ומה יענה הוא על כך? ומסבירים: \u0003ור' יהודה\u0004 מה הוא אומר — \u0003אמר\u0004 \u0005[י\u0006 כול היה \u0005לומר]\u0006 \u0003לך: למיתה דחדא\u0004 \u0005[של\u0006 אשה \u0005אחת] —\u0006 \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 אבל \u0003למיתה דתרתי לא חיישינן\u0004 \u0005[של שתים אין אנו חוששים],\u0006 שזהו חשש רחוק מאד, ואין צורך להביאו בחשבון. ושואלים: \u0003ורבנן,\u0004 מה משיבים הם על טענה זו? ומשיבים: שלדעתם \u0003אי איכא למיחש\u0004 \u0005[אם יש\u0006 בכלל סיבה \u0005לחשוש] —\u0006 אם כן \u0003אפילו למיתה דתרין חיישינן\u0004 \u0005[של שתים אנו חוששים].\u0006","ומקשים: אם אמנם לדעת חכמים אין לחלק בין חשש לאחד וביו חשש לשנים, אם כן, \u0003נימרו אינהו לנפשייהו\u0004 \u0005[שיאמרו,\u0006 יקשו \u0005הם לעצמם]\u0006 שמאחר וחוששים שמא יטמא הכהן גדול ולכן ממנים לו ממלא מקום, מדוע אם כן אין חוששים שמא יטמא אף זה, ולכך יש איפוא לתקן ממלא מקום נוסף! ומשיבים: \u0003אמרי לך רבנן\u0004 \u0005[\u0006יכולים היו \u0005חכמים לומר לך]:\u0006 \u0003כהן גדול זריז הוא\u0004 ונזהר מטומאה, אבל ממיתה אין באפשרותו להיזהר, לכן יש לחשוש ולמנות לו ממלא מקום נוסף. ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003זריז הוא\u0004 ואין לחשוש לטומאה, אם כן \u0003למה\u0004 בכלל \u0003מתקינין\u0004 לו \u0003כהן אחר?\u0004 ומשיבים: תקנה זו למטרה זו נתקנה, כי \u0003כיון דעבדינן ליה\u0004 \u0005[שעושים לו]\u0006 ממלא מקום, שהוא לו כעין \u0003צרה\u0004 והריהו לו כיריב, \u0003כל שכן דמזדרז טפי\u0004 \u0005[ש\u0006הוא \u0005מזדרז יותר]\u0006 ונזהר שלא יטמא כלל, כדי שלא יבואו להחליפו בממלא מקומו.","על גוף שיטת ר' יהודה מקשים: \u0003ומי סגי ליה בתקנתא\u0004 \u0005[והאם די לו בתקנה\u0006 זו\u0005]\u0006 שמתקינים לו אשה אחרת? הלא \u0003\"\u0004וכפר בעדו ובעד \u0003ביתו\"\u0004 (ויקרא טז, יא) \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 ו\"ביתו\" זו אשתו. \u0003והך\u0004 \u0005[ו\u0006אשה \u0005זו]\u0006 שהתקינו לו הרי \u0003לאו ביתו היא\u0004 שהרי עדיין אינה מקודשת לו, ומה תועיל אם אמנם תמות אשתו ביום הכיפורים? ומשיבים: שאכן \u0003מקדש\u0004 הוא \u0003לה\u0004 \u0005[אותה]\u0006 קודם יום הכיפורים. ומקשים: \u0003והא כמה דלא כניס לה\u0004 \u0005[והרי כל עוד שאינו כונס אותה]\u0006 לביתו בנישואין — עדיין \u0003לאו\u0004 \u0005[לא]\u0006 נחשבת כ\u0003ביתו היא!\u0004 ומשיבים: אכן מדובר \u0003דכניס לה\u0004 \u0005[ש\u0006הוא \u0005כונס אותה]\u0006 בנישואין ממש. ומקשים: \u0003אם כן\u0004 קשה הדבר מטעם אחר: שהרי \u0003הוה ליה\u0004 \u0005[הריהו זה]\u0006 הכהן הגדול שיש לו \u0003שני בתים\u0004 (נשים) \u0003ורחמנא\u0004 \u0005[והכתוב]\u0006 \u0003אמר: \"וכפר בעדו ובעד ביתו\",\u0004 ונדייק: עבור \"ביתו\" האחד הוא מכפר, \u0003ולא בעד שני בתים!\u0004","ומשיבים: \u0003דהדר\u0004 \u0005[שחוזר]\u0006 הוא ו\u0003מגרש לה\u0004 [\u0005אותה]\u0006 את האשה הנוספת. ומקשים: אם כן, \u0003אי\u0004 \u0005[אם]\u0006 \u0003מגרש\u0004 הוא \u0003לה\u0004 \u0005[אותה],\u0006 אם כן \u0003הדרא קושיין לדוכתא\u0004 \u0005[חוזרת קושייתנו למקומה]\u0006 שאין תועלת בתקנה, שהרי יש לחשוש שמא תמות אשתו, וזו המתוקנת לו הרי שוב אינה \"ביתו\"! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא באופן שהוא נושא אותה ולאחר מכן הוא שב ו\u0003מגרש לה\u0004 \u0005[אותה]\u0006 \u0003על תנאי.\u0004 כיצד? — \u0003דאמר\u0004 \u0005[שאומר\u0006 הוא\u0005]\u0006 \u0003לה: \"הרי זה גיטיך על מנת שתמותי\u0004 ביום הכיפורים\u0003\".\u0004 ומעתה, אם תמות היא ביום הכיפורים — נמצא הגט חל למפרע ויש לו רק אשה אחת. ואם לא תמות היא אלא חברתה — הרי שלא חל גיטה ועדיין נשואה היא לו, ואף עתה נמצא שאין לו אלא אשה אחת. ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא מייתא\u0004 \u0005[תמות]\u0006 לא היא ולא חברתה, \u0003והוה ליה\u0004 \u0005[והרי לו]\u0006 \u0003שני בתים\u0004 ביום הכיפורים!","\u0003אלא\u0004 כך הוא נוסח התנאי; \u0003דאמר\u0004 \u0005[שאומר\u0006 הוא\u0005]\u0006 \u0003לה\u0004 לאשה שהתקינו לו: \u0003\"הרי זה גיטיך על מנת שלא תמותי\u0004 ביום הכיפורים\u0003\".\u0004 ומעתה \u0003אי\u0004 \u0005[אם]\u0006 אכן \u0003לא מיתה\u0004 \u0005[תמות] —\u0006 הרי \u0003מיגרשא לה\u0004 \u0005[היא מגורשת]\u0006 כמו שהתנה עמה, ונשארת עמו אשתו הראשונה בלבד. \u0003ואי מיתה הא\u0004 \u0005[ואם מתה זו] —\u0006 הרי \u0003קיימא הך\u0004 \u0005[עומדת\u0006 וקיימת \u0005זו\u0006 השניה\u0005]\u0006 ושוב אינו נשוי אלא לאחת. ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003היא\u0004 השניה \u0003לא מיתה\u0004 \u0005[תמות]\u0006 \u0003והוה לה גיטא דהאי גיטא\u0004 \u0005[ונמצא גיטה של זו גט\u0006 הוא\u0005]\u0006 ואיננה אשתו, \u0003ו\u0004גם \u0003מייתא\u0004 \u0005[ומתה]\u0006 \u0003חברתה\u0004 האשה הראשונה, \u0003וקם ליה\u0004 \u0005[ועומד הוא\u0006 שוב\u0005]\u0006 \u0003בלא בית\u0004 (אשה) ביום הכיפורים!","\u0003אלא\u0004 כך יש לנסח, שבשעה שהוא נותן לה את הגט \u0003אמר\u0004 \u0005[אומר\u0006 הוא\u0005]\u0006 \u0003לה\u0004 תנאי זה: שהוא נותן לה גט \u0003\"על מנת שתמות אחת מכם\".\u0004 ולכן אם \u0003מיתה הא\u0004 \u0005[מתה זו] —\u0006 \u0003קיימא הך\u0004 \u0005[עומדת זו]\u0006 האחרת, ואם \u0003מיתה הך\u0004 \u0005[מתה זו\u0006 האחרת\u0005]\u0006 — \u0003הא קיימא הא\u0004 \u0005[הרי עומדת זו].\u0006 ועדיין מקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא מייתא\u0004 \u0005[תמות]\u0006 \u0003ולא חדא מינייהו\u0004 \u0005[אחת מהן],\u0006 \u0003והוה ליה\u0004 \u0005[והרי לו]\u0006 אם כן \u0003שני בתים,\u0004 שנמצא נשוי לשתי נשים.","\u0003ועוד,\u0004 יש להקשות: \u0003כי האי גוונא מי הוי גיטא\u0004 \u0005[כעין זה האם הוא\u0006 נחשב כ\u0005גט],\u0006 האם יש בכלל תוקף לתנאי כעין זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא:\u0004 האומר לאשה: \u0003\"הרי זה גיטיך על מנת שלא תשתי יין כל ימי חיי וחייכי\u0004 (חייך) \u0003\"\u0004— \u0003אין זה כריתות,\u0004 שהרי בתורה נקרא הגט \"ספר כריתות\" ללמד כי הגט צריך לנתק לחלוטין את הקשר שבין האיש והאשה. ואם יש תנאי בגט הממשיך לקשור את האשה לבעלה, כתנאי זה לגבי שתיית יין, אין זה גט.","ואולם אם אמר לאשתו: אל תשתי יין \u0003כל ימי חיי פלוני — הרי זה כריתות,\u0004 שכיון שאין התנאי קשור בו ובה, אלא בחייו של אחר, הרי הוא כשאר תנאים שבגט. ואם כן, מאחר ולפי תנאו של הכהן הגדול, אין גיטה חל אלא באופן שלא מתה אף אחת מהן, נמצא שתנאי זה אינו מנתק את הקשר בין הבעל ואשתו כל ימי חייה, ותנאי כעין זה אינו בר תוקף!","\u0003אלא\u0004 כך יש לומר: \u0003דאמר\u0004 \u0005[שאומר]\u0006 \u0003לה\u0004 הכהן הגדול לאשה השניה: \u0003\"הרי זה גיטיך על מנת שלא תמות חברתיך\".\u0004 ואז יהיה המצב כך; \u0003אי לא מיתה\u0004 \u0005[אם לא מתה]\u0006 \u0003חברתה\u0004 \u0005—\u0006 \u0003מיגרשא\u0004 \u0005[\u0006הרי \u0005היא מגורשת],\u0006 \u0003ואי מיתה הא\u0004 \u0005[ואם תמות זו] —\u0006 \u0003הא קיימא הא\u0004 \u0005[הרי עומדת\u0006 וקיימת \u0005זו,]\u0006 האחרת. ומקשים: \u0003ודילמא מייתא\u0004 \u0005[ושמא תמות]\u0006 \u0003חברתה בפלגא\u0004 \u0005[באמצע]\u0006 ה\u0003עבודה\u0004 של יום הכיפורים, \u0003ואיגלי מלתא\u0004 \u0005[ויתגלה הדבר]\u0006"],["\u0003למפרע דגיטא דהא לאו גיטא\u0004 \u0005[שהגט\u0006 של \u0005זו לא גט]\u0006 \u0003הוא\u0004 שהרי השניה עדיין חיה, \u0003ועביד ליה\u0004 \u0005[ונמצא שעשה]\u0006 \u0003עבודה\u0004 כשיש לו \u0003שני בתים\u0004 (נשים)! \u0003אלא\u0004 עלינו להציע פתרון אחר: \u0003דאמר\u0004 \u0005[שאומר\u0006 הוא\u0005]\u0006 \u0003לה\u0004 לאשה השניה: \u0003\"הרי זה גיטיך על מנת שתמות חברתיך\".\u0004 ומקשים: הלא גם במקרה כזה עדיין \u0003ודילמא מייתא\u0004 \u0005[ושמא\u0006 אכן \u0005תמות]\u0006 \u0003חברתה והוה ליה גיטא דהא גיטא\u0004 \u0005[ויהיה הגט של זו גט]\u0006 \u0003וקם ליה\u0004 \u0005[ו\u0006נמצא \u0005עומד]\u0006 \u0003בלא בית\u0004 כלל!","\u0003אלא\u0004 כך יש לומר: ש\u0003מגרש להו לתרוייהו\u0004 \u0005[אותן את שתיהן]\u0006 בגט, אלא קובע לשתיהן תנאים שונים, \u0003לחדא\u0004 \u0005[לאחת\u0006 מהן\u0005]\u0006 \u0003אמר\u0004 \u0005[אומר\u0006 הוא\u0005]\u0006 \u0003לה: \"הרי זה גיטיך על מנת שלא תמות חברתיך\", ולחדא\u0004 \u0005[ולאחת\u0006 מהן, לאחרת\u0005]\u0006 \u0003אמר\u0004 \u0005[אומר\u0006 הוא\u0005]\u0006 \u0003לה: \"הרי זה גיטיך על מנת שלא תכנסי\u0004 ביום הכיפורים \u0003לבית הכנסת\",\u0004 שיש אפשרות קלה לגרום שיהא זה גט במניעת כניסתה לבית הכנסת. ומקשים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003לא מייתא\u0004 \u0005[תמות]\u0006 \u0003חברתה ולא עיילא\u0004 \u0005[תכנס]\u0006 \u0003היא לבית הכנסת\u0004 ואם כן \u0003והוה ליה גיטא דתרוייהו גיטא\u0004 \u0005[ונמצא הגט של שניהן גט]\u0006 \u0003וקם ליה\u0004 \u0005[ו\u0006נמצא \u0005הוא עומד]\u0006 שוב \u0003בלא בית!\u0004","\u0003אלא,\u0004 כך צריך לומר: \u0003לחדא אמר\u0004 \u0005[לאחת אומר\u0006 הוא\u0005]\u0006 \u0003לה: \"הרי זה גיטיך על מנת שלא תמות חברתיך\", ולחדא אמר\u0004 \u0005[ולאחת אומר\u0006 הוא\u0005]\u0006 \u0003לה: \"הרי זה גיטיך על מנת שאכנס אני לבית הכנסת\". דאי מייתא הא\u0004 \u0005[שאם מתה זו] —\u0006 הרי \u0003קיימא הא\u0004 \u0005[נשארת זו]\u0006 \u0003ואי מייתא הא\u0004 \u0005[ואם מתה זו] —\u0006 הרי \u0003קיימא הא\u0004 \u0005[עומדת זו].\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש\u0006 לך \u0005לומר]\u0006 ולחשוש עוד \u0003דילמא מייתא\u0004 \u0005[שמא תמות]\u0006 \u0003חברתה בפלגא\u0004 \u0005[באמצע]\u0006 ה\u0003עבודה\u0004 ונמצא כי \u0003עבד ליה\u0004 \u0005[עושה הוא]\u0006 \u0003עבודה למפרע\u0004 כשהוא נשוי ל\u0003שני בתים\u0004 (נשים), \u0003אי חזי לה דקא בעיא למימת\u0004 \u0005[אם רואה הוא שרצונה,\u0006 שהיא עומדת \u0005למות]\u0006 — \u0003קדים איהו ועייל\u0004 \u0005[מקדים הוא ונכנס]\u0006 \u0003לבית הכנסת ומשוי לגיטא דהא גיטא\u0004 \u0005[ועושה את הגט של זו גט]\u0006 \u0003למפרע\u0004 ונמצא שאינו נשוי אלא לאשה אחת. והצלחנו איפוא למצא אפשרות לשיטת ר' יהודה, שיהיה הכהן הגדול מכין לעצמו אשה נוספת, בלא שיהיה נשוי לשתי נשים בבת אחת ביום הכיפורים.","על אחד מעיקריה של סוגיה זו \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב אסי, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב עוירא: אלא מעתה\u0004 שאנו מדייקים בלשון הכתוב \"ביתו\" ולא שני בתים, אם כן \u0003שתי יבמות הבאות מבית אחד\u0004 כלומר, שהיו שתיהן נשואות לאדם אחד \u0003לא יתייבמו\u0004 אף לא אחת מהן, שהרי גם שם אמרה התורה \"את בית אחיו\" (דברים כה, ט) ונדייק: ולא שני בתים! ומשיבים: \u0003\"יבמתו\" \"יבמתו\" ריבה\u0004 הכתוב, שכיון שנאמרה מלה זו פעמיים בכתובים, הרי זה מרמז שאפילו כשיש שתי נשים מבית אחד הזקוקות לו ליבום, אחת מהן צריכה יבום.","מצד אחר \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רבינא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שהיה זה \u0003רב שרביה:\u0004 מה שאמרנו בכהן גדול שכל עוד אינו נושא את אשתו אף שהיא ארוסה, אינה בכלל \"ביתו\", \u0003אלא מעתה ארוסה לא תתייבם?\u0004 שהרי ביבום נאמר לשון \"בית\" והלא דבר זה הוא בניגוד להלכה המקובלת! ומשיבים: נאמר: \"לא תהיה אשת המת \u0003החוצה\u0004 לאיש זר\" (דברים כה, ה) ובא כתוב זה \u0003לרבות את הארוסה,\u0004 שאף שלא היתה בתוך ביתו, והיא לפי שעה עדיין בחוץ (\"החוצה\") מכל מקום חייבת יבום או חליצה.","בהקשר לסוגיה הקודמת מביאים ברייתא נוספת. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כהן גדול מקריב\u0004 קרבנות כשהוא \u0003אונן,\u0004 ביום מיתת קרוביו, אבל \u0003אינו אוכל\u0004 מן הקרבנות הללו. \u0003ר' יהודה אומר: כל היום.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"כל היום\"? אמר רבא: לא נצרכה\u0004 הוספה זו \u0003אלא\u0004 כדי \u0003להביאו מתוך ביתו.\u0004 כלומר: לא רק שמותר לו לעבוד במקדש כשהוא אונן, אלא אף מצוה היא להביאו באותו יום אל המקדש כדי שיעבוד בו כל היום ובכך יתפכח מצערו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: השתא\u0004 \u0005[עתה]\u0006 \u0003ל\u0004דעת \u0003ר' יהודה אפוקי מפקינן ליה\u0004 \u0005[מוציאים אנו אותו]\u0006 את הכהן האונן מן המקדש, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה\u0004 כהן הדיוט \u0003עומד ומקריב על גבי המזבח ושמע שמת לו מת — מניח עבודתו\u0004 באמצע \u0003ויוצא,\u0004 אלו \u0003דברי ר' יהודה.\u0004 ואילו \u0003ר' יוסי אומר: יגמור\u0004 את עבודתו ואחר כך יוצא, הרי שר' יהודה מחמיר בהקרבה בשעה שהוא אונן ואף שדיבר מענין כהן הדיוט, סברה היא שכן הדין גם בכהן גדול \u0003ואת אמרת מייתינן ליה\u0004 \u0005[ו\u0006כאן \u0005אתה אומר\u0006 ש\u0005מביאים אותו]\u0006 את הכהן הגדול \u0003מתוך ביתו\u0004 לעבוד באוננות?","\u0003אלא אמר רבא,\u0004 עלינו לחזור מהפירוש הראשון וכך יש לפרש: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כל היום\"\u0004"]]};
